274:      * Note that this only considers the subscribedPattern because this functionality is only used under the
275:      * classic protocol, where subscribedRe2JPattern is not supported.
276:      *
277:      * @return true if assignments matches subscription, otherwise false.
278:      */
279:     public synchronized boolean checkAssignmentMatchedSubscription(Collection<TopicPartition> assignments) {
280:         for (TopicPartition topicPartition : assignments) {
281:             if (this.subscribedPattern != null) {
282:                 if (!this.subscribedPattern.matcher(topicPartition.topic()).matches()) {
283:                     log.info("Assigned partition {} for non-subscribed topic regex pattern; subscription pattern is {}",
284:                         topicPartition,
285:                         this.subscribedPattern);
286: 
287:                     return false;
288:                 }
289:             } else {
290:                 if (!this.subscription.contains(topicPartition.topic())) {
291:                     log.info("Assigned partition {} for non-subscribed topic; subscription is {}", topicPartition, this.subscription);
292: 
293:                     return false;
294:                 }
295:             }
296:         }
297: 
298:         return true;
299:     }
