542:     /**
543:      * Attempt to complete validation with the end offset returned from the OffsetForLeaderEpoch request.
544:      * @return Log truncation details if detected and no reset policy is defined.
545:      */
546:     public synchronized Optional<LogTruncation> maybeCompleteValidation(TopicPartition tp,
547:                                                                         FetchPosition requestPosition,
548:                                                                         EpochEndOffset epochEndOffset) {
549:         TopicPartitionState state = assignedStateOrNull(tp);
550:         if (state == null) {
551:             log.debug("Skipping completed validation for partition {} which is not currently assigned.", tp);
552:         } else if (!state.awaitingValidation()) {
553:             log.debug("Skipping completed validation for partition {} which is no longer expecting validation.", tp);
554:         } else {
555:             SubscriptionState.FetchPosition currentPosition = state.position;
556:             if (!currentPosition.equals(requestPosition)) {
557:                 log.debug("Skipping completed validation for partition {} since the current position {} " +
558:                           "no longer matches the position {} when the request was sent",
559:                           tp, currentPosition, requestPosition);
560:             } else if (epochEndOffset.endOffset() == UNDEFINED_EPOCH_OFFSET ||
561:                         epochEndOffset.leaderEpoch() == UNDEFINED_EPOCH) {
562:                 if (hasDefaultOffsetResetPolicy()) {
563:                     log.info("Truncation detected for partition {} at offset {}, resetting offset",
564:                              tp, currentPosition);
565:                     requestOffsetReset(tp);
566:                 } else {
567:                     log.warn("Truncation detected for partition {} at offset {}, but no reset policy is set",
568:                              tp, currentPosition);
569:                     return Optional.of(new LogTruncation(tp, requestPosition, Optional.empty()));
570:                 }
571:             } else if (epochEndOffset.endOffset() < currentPosition.offset) {
572:                 if (hasDefaultOffsetResetPolicy()) {
573:                     SubscriptionState.FetchPosition newPosition = new SubscriptionState.FetchPosition(
574:                             epochEndOffset.endOffset(), Optional.of(epochEndOffset.leaderEpoch()),
575:                             currentPosition.currentLeader);
576:                     log.info("Truncation detected for partition {} at offset {}, resetting offset to " +
577:                              "the first offset known to diverge {}", tp, currentPosition, newPosition);
578:                     state.seekValidated(newPosition);
579:                 } else {
580:                     OffsetAndMetadata divergentOffset = new OffsetAndMetadata(epochEndOffset.endOffset(),
581:                         Optional.of(epochEndOffset.leaderEpoch()), null);
582:                     log.warn("Truncation detected for partition {} at offset {} (the end offset from the " +
583:                              "broker is {}), but no reset policy is set", tp, currentPosition, divergentOffset);
584:                     return Optional.of(new LogTruncation(tp, requestPosition, Optional.of(divergentOffset)));
585:                 }
586:             } else {
587:                 state.completeValidation();
588:             }
589:         }
590: 
591:         return Optional.empty();
592:     }
