1007:         private void updatePreferredReadReplica(int preferredReadReplica, LongSupplier timeMs) {
1008:             if (this.preferredReadReplica == null || preferredReadReplica != this.preferredReadReplica) {
1009:                 this.preferredReadReplica = preferredReadReplica;
1010:                 this.preferredReadReplicaExpireTimeMs = timeMs.getAsLong();
1011:             }
1012:         }
