1068:         private void validatePosition(FetchPosition position) {
1069:             if (position.offsetEpoch.isPresent() && position.currentLeader.epoch.isPresent()) {
1070:                 transitionState(FetchStates.AWAIT_VALIDATION, () -> {
1071:                     this.position = position;
1072:                     this.nextRetryTimeMs = null;
1073:                 });
1074:             } else {
1075:                 // If we have no epoch information for the current position, then we can skip validation
1076:                 transitionState(FetchStates.FETCHING, () -> {
1077:                     this.position = position;
1078:                     this.nextRetryTimeMs = null;
1079:                 });
1080:             }
1081:         }
