526:             return false;
527:         }
528:         if (leaderAndEpoch.leader.isPresent()) {
529:             NodeApiVersions nodeApiVersions = apiVersions.get(leaderAndEpoch.leader.get().idString());
530:             if (nodeApiVersions == null || hasUsableOffsetForLeaderEpochVersion(nodeApiVersions)) {
531:                 return state.maybeValidatePosition(leaderAndEpoch);
532:             } else {
533:                 // If the broker does not support a newer version of OffsetsForLeaderEpoch, we skip validation
534:                 state.updatePositionLeaderNoValidation(leaderAndEpoch);
535:                 return false;
536:             }
537:         } else {
538:             return state.maybeValidatePosition(leaderAndEpoch);
