998:         private Optional<Integer> preferredReadReplica(long timeMs) {
999:             if (preferredReadReplicaExpireTimeMs != null && timeMs > preferredReadReplicaExpireTimeMs) {
1000:                 preferredReadReplica = null;
1001:                 return Optional.empty();
1002:             } else {
1003:                 return Optional.ofNullable(preferredReadReplica);
1004:             }
1005:         }
