1007:         private void updatePreferredReadReplica(int preferredReadReplica, LongSupplier timeMs) {
1008:             if (this.preferredReadReplica == null || preferredReadReplica != this.preferredReadReplica) {
1009:                 this.preferredReadReplica = preferredReadReplica;
1010:                 this.preferredReadReplicaExpireTimeMs = timeMs.getAsLong();
1011:             }
1012:         }
1013: 
1014:         private Optional<Integer> clearPreferredReadReplica() {
1015:             if (preferredReadReplica != null) {
1016:                 int removedReplicaId = this.preferredReadReplica;
1017:                 this.preferredReadReplica = null;
1018:                 this.preferredReadReplicaExpireTimeMs = null;
1019:                 return Optional.of(removedReplicaId);
1020:             } else {
1021:                 return Optional.empty();
1022:             }
