1056:         /**
1057:          * For older versions of the API, we cannot perform offset validation so we simply transition directly to FETCHING
1058:          */
1059:         private void updatePositionLeaderNoValidation(Metadata.LeaderAndEpoch currentLeaderAndEpoch) {
1060:             if (position != null) {
1061:                 transitionState(FetchStates.FETCHING, () -> {
1062:                     this.position = new FetchPosition(position.offset, position.offsetEpoch, currentLeaderAndEpoch);
1063:                     this.nextRetryTimeMs = null;
1064:                 });
1065:             }
1066:         }
