553:     /**
554:      * Compute the latest partition metadata to cache given ordering by leader epochs (if both
555:      * available and reliable) and whether the topic ID changed.
556:      */
557:     private Optional<MetadataResponse.PartitionMetadata> updateLatestMetadata(
558:             MetadataResponse.PartitionMetadata partitionMetadata,
559:             boolean hasReliableLeaderEpoch,
560:             Uuid topicId,
561:             Uuid oldTopicId) {
562:         TopicPartition tp = partitionMetadata.topicPartition;
563:         if (hasReliableLeaderEpoch && partitionMetadata.leaderEpoch.isPresent()) {
564:             int newEpoch = partitionMetadata.leaderEpoch.get();
565:             Integer currentEpoch = lastSeenLeaderEpochs.get(tp);
566:             if (currentEpoch == null) {
567:                 // We have no previous info, so we can just insert the new epoch info
568:                 log.debug("Setting the last seen epoch of partition {} to {} since the last known epoch was undefined.",
569:                         tp, newEpoch);
570:                 lastSeenLeaderEpochs.put(tp, newEpoch);
571:                 this.equivalentResponseCount = 0;
572:                 return Optional.of(partitionMetadata);
573:             } else if (topicId != null && !topicId.equals(oldTopicId)) {
574:                 // If the new topic ID is valid and different from the last seen topic ID, update the metadata.
575:                 // Between the time that a topic is deleted and re-created, the client may lose track of the
576:                 // corresponding topicId (i.e. `oldTopicId` will be null). In this case, when we discover the new
577:                 // topicId, we allow the corresponding leader epoch to override the last seen value.
578:                 log.info("Resetting the last seen epoch of partition {} to {} since the associated topicId changed from {} to {}",
579:                         tp, newEpoch, oldTopicId, topicId);
580:                 lastSeenLeaderEpochs.put(tp, newEpoch);
581:                 this.equivalentResponseCount = 0;
582:                 return Optional.of(partitionMetadata);
583:             } else if (newEpoch >= currentEpoch) {
584:                 // If the received leader epoch is at least the same as the previous one, update the metadata
585:                 log.debug("Updating last seen epoch for partition {} from {} to epoch {} from new metadata", tp, currentEpoch, newEpoch);
586:                 lastSeenLeaderEpochs.put(tp, newEpoch);
587:                 if (newEpoch > currentEpoch) {
588:                     this.equivalentResponseCount = 0;
589:                 }
590:                 return Optional.of(partitionMetadata);
591:             } else {
592:                 // Otherwise ignore the new metadata and use the previously cached info
593:                 log.debug("Got metadata for an older epoch {} (current is {}) for partition {}, not updating", newEpoch, currentEpoch, tp);
594:                 return metadataSnapshot.partitionMetadata(tp);
595:             }
596:         } else {
597:             // Handle old cluster formats as well as error responses where leader and epoch are missing
598:             lastSeenLeaderEpochs.remove(tp);
599:             this.equivalentResponseCount = 0;
600:             return Optional.of(partitionMetadata.withoutLeaderEpoch());
601:         }
602:     }
