140:     /**
141:      * Return the next time when the current cluster info can be updated (i.e., backoff time has elapsed).
142:      * There are two calculations for backing off based on how many attempts to retrieve metadata have been made
143:      * since the last successful response, and how many equivalent metadata responses have been received.
144:      * The second of these allows backing off when there are errors to do with stale metadata, even though the
145:      * metadata responses are clean.
146:      * <p>
147:      * This can be used to check whether it's worth requesting an update in the knowledge that it will
148:      * not be delayed if this method returns 0.
149:      *
150:      * @param nowMs current time in ms
151:      * @return remaining time in ms till the cluster info can be updated again
152:      */
153:     public synchronized long timeToAllowUpdate(long nowMs) {
154:         // Calculate the backoff for attempts which acts when metadata responses fail
155:         long backoffForAttempts = Math.max(this.lastRefreshMs +
156:                 this.refreshBackoff.backoff(this.attempts > 0 ? this.attempts - 1 : 0) - nowMs, 0);
157: 
158:         // Periodic updates based on expiration resets the equivalent response count so exponential backoff is not used
159:         if (Math.max(this.lastSuccessfulRefreshMs + this.metadataExpireMs - nowMs, 0) == 0) {
160:             this.equivalentResponseCount = 0;
161:         }
162: 
163:         // Calculate the backoff for equivalent responses which acts when metadata responses are not making progress
164:         long backoffForEquivalentResponseCount = Math.max(this.lastRefreshMs +
165:                 (this.equivalentResponseCount > 0 ? this.refreshBackoff.backoff(this.equivalentResponseCount - 1) : 0) - nowMs, 0);
166: 
167:         return Math.max(backoffForAttempts, backoffForEquivalentResponseCount);
168:     }
