170:     /**
171:      * The next time to update the cluster info is the maximum of the time the current info will expire and the time the
172:      * current info can be updated (i.e. backoff time has elapsed). If an update has been requested, the metadata
173:      * expiry time is now.
174:      *
175:      * @param nowMs current time in ms
176:      * @return remaining time in ms till updating the cluster info
177:      */
178:     public synchronized long timeToNextUpdate(long nowMs) {
179:         long timeToExpire = updateRequested() ? 0 : Math.max(this.lastSuccessfulRefreshMs + this.metadataExpireMs - nowMs, 0);
180:         return Math.max(timeToExpire, timeToAllowUpdate(nowMs));
181:     }
