222:     /**
223:      * Request an update for the partition metadata iff we have seen a newer leader epoch. This is called by the client
224:      * any time it handles a response from the broker that includes leader epoch, except for update via Metadata RPC which
225:      * follows a different code path ({@link #update}).
226:      *
227:      * @param topicPartition
228:      * @param leaderEpoch
229:      * @return true if we updated the last seen epoch, false otherwise
230:      */
231:     public synchronized boolean updateLastSeenEpochIfNewer(TopicPartition topicPartition, int leaderEpoch) {
232:         Objects.requireNonNull(topicPartition, "TopicPartition cannot be null");
233:         if (leaderEpoch < 0)
234:             throw new IllegalArgumentException("Invalid leader epoch " + leaderEpoch + " (must be non-negative)");
235: 
236:         Integer oldEpoch = lastSeenLeaderEpochs.get(topicPartition);
237:         log.trace("Determining if we should replace existing epoch {} with new epoch {} for partition {}", oldEpoch, leaderEpoch, topicPartition);
238: 
239:         final boolean updated;
240:         if (oldEpoch == null) {
241:             log.debug("Not replacing null epoch with new epoch {} for partition {}", leaderEpoch, topicPartition);
242:             updated = false;
243:         } else if (leaderEpoch > oldEpoch) {
244:             log.debug("Updating last seen epoch from {} to {} for partition {}", oldEpoch, leaderEpoch, topicPartition);
245:             lastSeenLeaderEpochs.put(topicPartition, leaderEpoch);
246:             updated = true;
247:         } else {
248:             log.debug("Not replacing existing epoch {} with new epoch {} for partition {}", oldEpoch, leaderEpoch, topicPartition);
249:             updated = false;
250:         }
251: 
252:         this.needFullUpdate = this.needFullUpdate || updated;
253:         return updated;
254:     }
