327:     /**
328:      * Updates the cluster metadata. If topic expiry is enabled, expiry time
329:      * is set for topics if required and expired topics are removed from the metadata.
330:      *
331:      * @param requestVersion The request version corresponding to the update response, as provided by
332:      *     {@link #newMetadataRequestAndVersion(long)}.
333:      * @param response metadata response received from the broker
334:      * @param isPartialUpdate whether the metadata request was for a subset of the active topics
335:      * @param nowMs current time in milliseconds
336:      */
337:     public synchronized void update(int requestVersion, MetadataResponse response, boolean isPartialUpdate, long nowMs) {
338:         Objects.requireNonNull(response, "Metadata response cannot be null");
339:         if (isClosed())
340:             throw new IllegalStateException("Update requested after metadata close");
341: 
342:         this.needPartialUpdate = requestVersion < this.requestVersion;
343:         this.lastRefreshMs = nowMs;
344:         this.attempts = 0;
345:         this.updateVersion += 1;
346:         if (!isPartialUpdate) {
347:             this.needFullUpdate = false;
348:             this.lastSuccessfulRefreshMs = nowMs;
349:         }
350:         // If we subsequently find that the metadata response is not equivalent to the metadata already known,
351:         // this count is reset to 0 in updateLatestMetadata()
352:         this.equivalentResponseCount++;
353: 
354:         String previousClusterId = metadataSnapshot.clusterResource().clusterId();
355: 
356:         this.metadataSnapshot = handleMetadataResponse(response, isPartialUpdate, nowMs);
357: 
358:         Cluster cluster = metadataSnapshot.cluster();
359:         setMetadataErrorIfPresent(cluster);
360: 
361:         this.lastSeenLeaderEpochs.keySet().removeIf(tp -> !retainTopic(tp.topic(), false, nowMs));
362: 
363:         String newClusterId = metadataSnapshot.clusterResource().clusterId();
364:         if (!Objects.equals(previousClusterId, newClusterId)) {
365:             log.info("Cluster ID: {}", newClusterId);
366:         }
367:         clusterResourceListeners.onUpdate(metadataSnapshot.clusterResource());
368: 
369:         log.debug("Updated cluster metadata updateVersion {} to {}", this.updateVersion, this.metadataSnapshot);
370:     }
