483:     /**
484:      * Transform a MetadataResponse into a new MetadataCache instance.
485:      */
486:     private MetadataSnapshot handleMetadataResponse(MetadataResponse metadataResponse, boolean isPartialUpdate, long nowMs) {
487:         // All encountered topics.
488:         Set<String> topics = new HashSet<>();
489: 
490:         // Retained topics to be passed to the metadata cache.
491:         Set<String> internalTopics = new HashSet<>();
492:         Set<String> unauthorizedTopics = new HashSet<>();
493:         Set<String> invalidTopics = new HashSet<>();
494: 
495:         List<MetadataResponse.PartitionMetadata> partitions = new ArrayList<>();
496:         Map<String, Uuid> topicIds = new HashMap<>();
497:         Map<String, Uuid> oldTopicIds = metadataSnapshot.topicIds();
498:         for (MetadataResponse.TopicMetadata metadata : metadataResponse.topicMetadata()) {
499:             String topicName = metadata.topic();
500:             Uuid topicId = metadata.topicId();
501:             topics.add(topicName);
502:             // We can only reason about topic ID changes when both IDs are valid, so keep oldId null unless the new metadata contains a topic ID
503:             Uuid oldTopicId = null;
504:             if (!Uuid.ZERO_UUID.equals(topicId)) {
505:                 topicIds.put(topicName, topicId);
506:                 oldTopicId = oldTopicIds.get(topicName);
507:             } else {
508:                 topicId = null;
509:             }
510: 
511:             if (!retainTopic(topicName, metadata.isInternal(), nowMs))
512:                 continue;
513: 
514:             if (metadata.isInternal())
515:                 internalTopics.add(topicName);
516: 
517:             if (metadata.error() == Errors.NONE) {
518:                 for (MetadataResponse.PartitionMetadata partitionMetadata : metadata.partitionMetadata()) {
519:                     // Even if the partition's metadata includes an error, we need to handle
520:                     // the update to catch new epochs
521:                     updateLatestMetadata(partitionMetadata, metadataResponse.hasReliableLeaderEpochs(), topicId, oldTopicId)
522:                         .ifPresent(partitions::add);
523: 
524:                     if (partitionMetadata.error.exception() instanceof InvalidMetadataException) {
525:                         log.debug("Requesting metadata update for partition {} due to error {}",
526:                                 partitionMetadata.topicPartition, partitionMetadata.error);
527:                         requestUpdate(false);
528:                     }
529:                 }
530:             } else {
531:                 if (metadata.error().exception() instanceof InvalidMetadataException) {
532:                     log.debug("Requesting metadata update for topic {} due to error {}", topicName, metadata.error());
533:                     requestUpdate(false);
534:                 }
535: 
536:                 if (metadata.error() == Errors.INVALID_TOPIC_EXCEPTION)
537:                     invalidTopics.add(topicName);
538:                 else if (metadata.error() == Errors.TOPIC_AUTHORIZATION_FAILED)
539:                     unauthorizedTopics.add(topicName);
540:             }
541:         }
542: 
543:         Map<Integer, Node> nodes = metadataResponse.brokersById();
544:         if (isPartialUpdate)
545:             return this.metadataSnapshot.mergeWith(metadataResponse.clusterId(), nodes, partitions,
546:                 unauthorizedTopics, invalidTopics, internalTopics, metadataResponse.controller(), topicIds,
547:                 (topic, isInternal) -> !topics.contains(topic) && retainTopic(topic, isInternal, nowMs));
548:         else
549:             return new MetadataSnapshot(metadataResponse.clusterId(), nodes, partitions,
550:                 unauthorizedTopics, invalidTopics, internalTopics, metadataResponse.controller(), topicIds);
551:     }
