733:     public static Map<String, Object> appendDeserializerToConfig(Map<String, Object> configs,
734:                                                                  Deserializer<?> keyDeserializer,
735:                                                                  Deserializer<?> valueDeserializer) {
736:         // validate deserializer configuration, if the passed deserializer instance is null, the user must explicitly set a valid deserializer configuration value
737:         Map<String, Object> newConfigs = new HashMap<>(configs);
738:         if (keyDeserializer != null)
739:             newConfigs.put(KEY_DESERIALIZER_CLASS_CONFIG, keyDeserializer.getClass());
740:         else if (newConfigs.get(KEY_DESERIALIZER_CLASS_CONFIG) == null)
741:             throw new ConfigException(KEY_DESERIALIZER_CLASS_CONFIG, null, "must be non-null.");
742:         if (valueDeserializer != null)
743:             newConfigs.put(VALUE_DESERIALIZER_CLASS_CONFIG, valueDeserializer.getClass());
744:         else if (newConfigs.get(VALUE_DESERIALIZER_CLASS_CONFIG) == null)
745:             throw new ConfigException(VALUE_DESERIALIZER_CLASS_CONFIG, null, "must be non-null.");
746:         return newConfigs;
747:     }
