762:     protected void checkUnsupportedConfigsPostProcess() {
763:         String groupProtocol = getString(GROUP_PROTOCOL_CONFIG);
764:         if (GroupProtocol.CLASSIC.name().equalsIgnoreCase(groupProtocol)) {
765:             checkUnsupportedConfigsPostProcess(GroupProtocol.CLASSIC, CLASSIC_PROTOCOL_UNSUPPORTED_CONFIGS);
766:         } else if (GroupProtocol.CONSUMER.name().equalsIgnoreCase(groupProtocol)) {
767:             checkUnsupportedConfigsPostProcess(GroupProtocol.CONSUMER, CONSUMER_PROTOCOL_UNSUPPORTED_CONFIGS);
768:         }
769:     }
770: 
771:     private void checkUnsupportedConfigsPostProcess(GroupProtocol groupProtocol, List<String> unsupportedConfigs) {
772:         if (getString(GROUP_PROTOCOL_CONFIG).equalsIgnoreCase(groupProtocol.name())) {
773:             List<String> invalidConfigs = new ArrayList<>();
774:             unsupportedConfigs.forEach(configName -> {
775:                 Object config = originals().get(configName);
776:                 if (config != null && !Utils.isBlank(config.toString())) {
777:                     invalidConfigs.add(configName);
778:                 }
779:             });
780:             if (!invalidConfigs.isEmpty()) {
781:                 throw new ConfigException(String.join(", ", invalidConfigs) +
782:                         " cannot be set when " + GROUP_PROTOCOL_CONFIG + "=" + groupProtocol.name());
783:             }
784:         }
785:     }
