95:             if (task == null) {
96:                 return new FetchAction(fetchBuffer);
97:             } else if (task instanceof WakeupFuture) {
98:                 throwWakeupException.set(true);
99:                 return null;
100:             } else if (task instanceof DisabledWakeups) {
