50: 
51:     private final Logger log;
52:     private final ConcurrentLinkedQueue<CompletedFetch> completedFetches;
53:     private final Lock lock;
54:     private final Condition notEmptyCondition;
55:     private final IdempotentCloser idempotentCloser = new IdempotentCloser();
