200:      * Initialize the coordination manager.
201:      */
202:     public ConsumerCoordinator(GroupRebalanceConfig rebalanceConfig,
203:                                LogContext logContext,
204:                                ConsumerNetworkClient client,
205:                                List<ConsumerPartitionAssignor> assignors,
206:                                ConsumerMetadata metadata,
207:                                SubscriptionState subscriptions,
208:                                Metrics metrics,
209:                                String metricGrpPrefix,
210:                                Time time,
211:                                boolean autoCommitEnabled,
212:                                int autoCommitIntervalMs,
213:                                ConsumerInterceptors<?, ?> interceptors,
214:                                boolean throwOnFetchStableOffsetsUnsupported,
215:                                Optional<ClientTelemetryReporter> clientTelemetryReporter,
216:                                Optional<Supplier<BaseHeartbeatThread>> heartbeatThreadSupplier) {
217:         super(rebalanceConfig,
218:               logContext,
219:               client,
220:               metrics,
221:               metricGrpPrefix,
222:               time,
223:               clientTelemetryReporter,
224:               heartbeatThreadSupplier);
225:         this.rebalanceConfig = rebalanceConfig;
226:         this.log = logContext.logger(ConsumerCoordinator.class);
227:         this.metadata = metadata;
228:         this.rackId = rebalanceConfig.rackId;
229:         this.metadataSnapshot = new MetadataSnapshot(this.rackId, subscriptions, metadata.fetch(), metadata.updateVersion());
230:         this.subscriptions = subscriptions;
231:         this.defaultOffsetCommitCallback = new DefaultOffsetCommitCallback();
232:         this.autoCommitEnabled = autoCommitEnabled;
233:         this.autoCommitIntervalMs = autoCommitIntervalMs;
234:         this.assignors = assignors;
235:         this.completedOffsetCommits = new ConcurrentLinkedQueue<>();
236:         this.coordinatorMetrics = new ConsumerCoordinatorMetrics(metrics, metricGrpPrefix);
237:         this.interceptors = interceptors;
238:         this.inFlightAsyncCommits = new AtomicInteger();
239:         this.pendingAsyncCommits = new AtomicInteger();
240:         this.asyncCommitFenced = new AtomicBoolean(false);
241:         this.groupMetadata = new ConsumerGroupMetadata(rebalanceConfig.groupId,
242:             JoinGroupRequest.UNKNOWN_GENERATION_ID, JoinGroupRequest.UNKNOWN_MEMBER_ID, rebalanceConfig.groupInstanceId);
243:         this.throwOnFetchStableOffsetsUnsupported = throwOnFetchStableOffsetsUnsupported;
244: 
245:         if (autoCommitEnabled)
246:             this.nextAutoCommitTimer = time.timer(autoCommitIntervalMs);
247: 
248:         // select the rebalance protocol such that:
249:         //   1. only consider protocols that are supported by all the assignors. If there is no common protocols supported
250:         //      across all the assignors, throw an exception.
251:         //   2. if there are multiple protocols that are commonly supported, select the one with the highest id (i.e. the
252:         //      id number indicates how advanced the protocol is).
253:         // we know there are at least one assignor in the list, no need to double check for NPE
254:         if (!assignors.isEmpty()) {
255:             List<RebalanceProtocol> supportedProtocols = new ArrayList<>(assignors.get(0).supportedProtocols());
256: 
257:             for (ConsumerPartitionAssignor assignor : assignors) {
258:                 supportedProtocols.retainAll(assignor.supportedProtocols());
259:             }
260: 
261:             if (supportedProtocols.isEmpty()) {
262:                 throw new IllegalArgumentException("Specified assignors " +
263:                     assignors.stream().map(ConsumerPartitionAssignor::name).collect(Collectors.toSet()) +
264:                     " do not have commonly supported rebalance protocol");
265:             }
266: 
267:             Collections.sort(supportedProtocols);
268: 
269:             protocol = supportedProtocols.get(supportedProtocols.size() - 1);
270:         } else {
271:             protocol = null;
272:         }
273: 
274:         this.rebalanceListenerInvoker = new ConsumerRebalanceListenerInvoker(
275:             logContext,
276:             subscriptions,
277:             time,
278:             new RebalanceCallbackMetricsManager(metrics, metricGrpPrefix)
279:         );
280:         this.metadata.requestUpdate(true);
281:     }
