749:     @Override
750:     protected boolean onJoinPrepare(Timer timer, int generation, String memberId) {
751:         log.debug("Executing onJoinPrepare with generation {} and memberId {}", generation, memberId);
752:         if (joinPrepareTimer == null) {
753:             // We should complete onJoinPrepare before rebalanceTimeoutMs,
754:             // and continue to join group to avoid member got kicked out from group
755:             joinPrepareTimer = time.timer(rebalanceConfig.rebalanceTimeoutMs);
756:         } else {
757:             joinPrepareTimer.update();
758:         }
759: 
760:         // async commit offsets prior to rebalance if auto-commit enabled
761:         // and there is no in-flight offset commit request
762:         if (autoCommitEnabled && autoCommitOffsetRequestFuture == null) {
763:             maybeMarkPartitionsPendingRevocation();
764:             autoCommitOffsetRequestFuture = maybeAutoCommitOffsetsAsync();
765:         }
766: 
767:         // wait for commit offset response before timer expired
768:         if (autoCommitOffsetRequestFuture != null) {
769:             Timer pollTimer = timer.remainingMs() < joinPrepareTimer.remainingMs() ?
770:                     timer : joinPrepareTimer;
771:             client.poll(autoCommitOffsetRequestFuture, pollTimer);
772:             joinPrepareTimer.update();
773: 
774:             // Keep retrying/waiting the offset commit when:
775:             // 1. offset commit haven't done (and joinPrepareTimer not expired)
776:             // 2. failed with retriable exception (and joinPrepareTimer not expired)
777:             // Otherwise, continue to revoke partitions, ex:
778:             // 1. if joinPrepareTimer has expired
779:             // 2. if offset commit failed with non-retriable exception
780:             // 3. if offset commit success
781:             boolean onJoinPrepareAsyncCommitCompleted = true;
782:             if (joinPrepareTimer.isExpired()) {
783:                 log.error("Asynchronous auto-commit of offsets failed: joinPrepare timeout. Will continue to join group");
784:             } else if (!autoCommitOffsetRequestFuture.isDone()) {
785:                 onJoinPrepareAsyncCommitCompleted = false;
786:             } else if (autoCommitOffsetRequestFuture.failed() && autoCommitOffsetRequestFuture.isRetriable()) {
787:                 log.debug("Asynchronous auto-commit of offsets failed with retryable error: {}. Will retry it.",
788:                         autoCommitOffsetRequestFuture.exception().getMessage());
789:                 onJoinPrepareAsyncCommitCompleted = false;
790:             } else if (autoCommitOffsetRequestFuture.failed() && !autoCommitOffsetRequestFuture.isRetriable()) {
791:                 log.error("Asynchronous auto-commit of offsets failed: {}. Will continue to join group.",
792:                         autoCommitOffsetRequestFuture.exception().getMessage());
793:             }
794:             if (autoCommitOffsetRequestFuture.isDone()) {
795:                 autoCommitOffsetRequestFuture = null;
796:             }
797:             if (!onJoinPrepareAsyncCommitCompleted) {
798:                 pollTimer.sleep(Math.min(pollTimer.remainingMs(), rebalanceConfig.retryBackoffMs));
799:                 timer.update();
800:                 return false;
801:             }
802:         }
803: 
804:         // the generation / member-id can possibly be reset by the heartbeat thread
805:         // upon getting errors or heartbeat timeouts; in this case whatever is previously
806:         // owned partitions would be lost, we should trigger the callback and cleanup the assignment;
807:         // otherwise we can proceed normally and revoke the partitions depending on the protocol,
808:         // and in that case we should only change the assignment AFTER the revoke callback is triggered
809:         // so that users can still access the previously owned partitions to commit offsets etc.
810:         Exception exception = null;
811:         final SortedSet<TopicPartition> revokedPartitions = new TreeSet<>(COMPARATOR);
812:         if (generation == Generation.NO_GENERATION.generationId ||
813:             memberId.equals(Generation.NO_GENERATION.memberId)) {
814:             revokedPartitions.addAll(subscriptions.assignedPartitions());
815: 
816:             if (!revokedPartitions.isEmpty()) {
817:                 log.info("Giving away all assigned partitions as lost since generation/memberID has been reset," +
818:                     "indicating that consumer is in old state or no longer part of the group");
819:                 exception = rebalanceListenerInvoker.invokePartitionsLost(revokedPartitions);
820: 
821:                 subscriptions.assignFromSubscribed(Collections.emptySet());
822:             }
823:         } else {
824:             switch (protocol) {
825:                 case EAGER:
826:                     // revoke all partitions
827:                     revokedPartitions.addAll(subscriptions.assignedPartitions());
828:                     exception = rebalanceListenerInvoker.invokePartitionsRevoked(revokedPartitions);
829: 
830:                     subscriptions.assignFromSubscribed(Collections.emptySet());
831: 
832:                     break;
833: 
834:                 case COOPERATIVE:
835:                     // only revoke those partitions that are not in the subscription anymore.
836:                     Set<TopicPartition> ownedPartitions = new HashSet<>(subscriptions.assignedPartitions());
837:                     revokedPartitions.addAll(ownedPartitions.stream()
838:                         .filter(tp -> !subscriptions.subscription().contains(tp.topic()))
839:                         .collect(Collectors.toSet()));
840: 
841:                     if (!revokedPartitions.isEmpty()) {
842:                         exception = rebalanceListenerInvoker.invokePartitionsRevoked(revokedPartitions);
843: 
844:                         ownedPartitions.removeAll(revokedPartitions);
845:                         subscriptions.assignFromSubscribed(ownedPartitions);
846:                     }
847: 
848:                     break;
849:             }
850:         }
851: 
852:         isLeader = false;
853:         subscriptions.resetGroupSubscription();
854:         joinPrepareTimer = null;
855:         autoCommitOffsetRequestFuture = null;
856:         timer.update();
857: 
858:         if (exception != null) {
859:             throw new KafkaException("User rebalance callback throws an error", exception);
860:         }
861:         return true;
862:     }
