955:     /**
956:      * Fetch the current committed offsets from the coordinator for a set of partitions.
957:      *
958:      * @param partitions The partitions to fetch offsets for
959:      * @return A map from partition to the committed offset or null if the operation timed out
960:      */
961:     public Map<TopicPartition, OffsetAndMetadata> fetchCommittedOffsets(final Set<TopicPartition> partitions,
962:                                                                         final Timer timer) {
963:         if (partitions.isEmpty()) return Collections.emptyMap();
964: 
965:         final Generation generationForOffsetRequest = generationIfStable();
966:         if (pendingCommittedOffsetRequest != null &&
967:             !pendingCommittedOffsetRequest.sameRequest(partitions, generationForOffsetRequest)) {
968:             // if we were waiting for a different request, then just clear it.
969:             pendingCommittedOffsetRequest = null;
970:         }
971: 
972:         long attempts = 0L;
973:         do {
974:             if (!ensureCoordinatorReady(timer)) return null;
975: 
976:             // contact coordinator to fetch committed offsets
977:             final RequestFuture<Map<TopicPartition, OffsetAndMetadata>> future;
978:             if (pendingCommittedOffsetRequest != null) {
979:                 future = pendingCommittedOffsetRequest.response;
980:             } else {
981:                 future = sendOffsetFetchRequest(partitions);
982:                 pendingCommittedOffsetRequest = new PendingCommittedOffsetRequest(partitions, generationForOffsetRequest, future);
983:             }
984:             client.poll(future, timer);
985: 
986:             if (future.isDone()) {
987:                 pendingCommittedOffsetRequest = null;
988: 
989:                 if (future.succeeded()) {
990:                     return future.value();
991:                 } else if (!future.isRetriable()) {
992:                     throw future.exception();
993:                 } else {
994:                     timer.sleep(retryBackoff.backoff(attempts++));
995:                 }
996:             } else {
997:                 return null;
998:             }
999:         } while (timer.notExpired());
1000:         return null;
1001:     }
