1046:     public RequestFuture<Void> commitOffsetsAsync(final Map<TopicPartition, OffsetAndMetadata> offsets, final OffsetCommitCallback callback) {
1047:         invokeCompletedOffsetCommitCallbacks();
1048: 
1049:         RequestFuture<Void> future = null;
1050:         if (offsets.isEmpty()) {
1051:             // No need to check coordinator if offsets is empty since commit of empty offsets is completed locally.
1052:             future = doCommitOffsetsAsync(offsets, callback);
1053:         } else if (!coordinatorUnknownAndUnreadyAsync()) {
1054:             // we need to make sure coordinator is ready before committing, since
1055:             // this is for async committing we do not try to block, but just try once to
1056:             // clear the previous discover-coordinator future, resend, or get responses;
1057:             // if the coordinator is not ready yet then we would just proceed and put that into the
1058:             // pending requests, and future poll calls would still try to complete them.
1059:             //
1060:             // the key here though is that we have to try sending the discover-coordinator if
1061:             // it's not known or ready, since this is the only place we can send such request
1062:             // under manual assignment (there we would not have heartbeat thread trying to auto-rediscover
1063:             // the coordinator).
1064:             future = doCommitOffsetsAsync(offsets, callback);
1065:         } else {
1066:             // we don't know the current coordinator, so try to find it and then send the commit
1067:             // or fail (we don't want recursive retries which can cause offset commits to arrive
1068:             // out of order). Note that there may be multiple offset commits chained to the same
1069:             // coordinator lookup request. This is fine because the listeners will be invoked in
1070:             // the same order that they were added. Note also that AbstractCoordinator prevents
1071:             // multiple concurrent coordinator lookup requests.
1072:             pendingAsyncCommits.incrementAndGet();
1073:             lookupCoordinator().addListener(new RequestFutureListener<>() {
1074:                 @Override
1075:                 public void onSuccess(Void value) {
1076:                     pendingAsyncCommits.decrementAndGet();
1077:                     doCommitOffsetsAsync(offsets, callback);
1078:                     client.pollNoWakeup();
1079:                 }
1080: 
1081:                 @Override
1082:                 public void onFailure(RuntimeException e) {
1083:                     pendingAsyncCommits.decrementAndGet();
1084:                     completedOffsetCommits.add(new OffsetCommitCompletion(callback, offsets,
1085:                             new RetriableCommitFailedException(e)));
1086:                 }
1087:             });
1088:         }
1089: 
1090:         // ensure the commit has a chance to be transmitted (without blocking on its completion).
1091:         // Note that commits are treated as heartbeats by the coordinator, so there is no need to
1092:         // explicitly allow heartbeats through delayed task execution.
1093:         client.pollNoWakeup();
1094:         return future;
1095:     }
