1475:     private RequestFuture<Map<TopicPartition, OffsetAndMetadata>> sendOffsetFetchRequest(Set<TopicPartition> partitions) {
1476:         Node coordinator = checkAndGetCoordinator();
1477:         if (coordinator == null)
1478:             return RequestFuture.coordinatorNotAvailable();
1479: 
1480:         log.debug("Fetching committed offsets for partitions: {}", partitions);
1481: 
1482:         // construct the request
1483:         List<OffsetFetchRequestData.OffsetFetchRequestTopics> topics = partitions.stream()
1484:             .collect(Collectors.groupingBy(TopicPartition::topic))
1485:             .entrySet()
1486:             .stream()
1487:             .map(entry -> new OffsetFetchRequestData.OffsetFetchRequestTopics()
1488:                 .setName(entry.getKey())
1489:                 .setPartitionIndexes(entry.getValue().stream()
1490:                     .map(TopicPartition::partition)
1491:                     .collect(Collectors.toList())))
1492:             .collect(Collectors.toList());
1493: 
1494:         OffsetFetchRequest.Builder requestBuilder = OffsetFetchRequest.Builder.forTopicNames(
1495:             new OffsetFetchRequestData()
1496:                 .setRequireStable(true)
1497:                 .setGroups(List.of(
1498:                     new OffsetFetchRequestData.OffsetFetchRequestGroup()
1499:                         .setGroupId(this.rebalanceConfig.groupId)
1500:                         .setTopics(topics))),
1501:             throwOnFetchStableOffsetsUnsupported);
1502: 
1503:         // send the request with a callback
1504:         return client.send(coordinator, requestBuilder)
1505:                 .compose(new OffsetFetchResponseHandler());
1506:     }
