497:     /**
498:      * Poll for coordinator events. This ensures that the coordinator is known and that the consumer
499:      * has joined the group (if it is using group management). This also handles periodic offset commits
500:      * if they are enabled.
501:      * <p>
502:      * Returns early if the timeout expires or if waiting on rejoin is not required
503:      *
504:      * @param timer Timer bounding how long this method can block
505:      * @param waitForJoinGroup Boolean flag indicating if we should wait until re-join group completes
506:      * @throws KafkaException if the rebalance callback throws an exception
507:      * @return true iff the operation succeeded
508:      */
509:     public boolean poll(Timer timer, boolean waitForJoinGroup) {
510:         doUpdateSubscriptionMetadataIfClusterMetadataChanged();
511: 
512:         invokeCompletedOffsetCommitCallbacks();
513: 
514:         if (subscriptions.hasAutoAssignedPartitions()) {
515:             if (protocol == null) {
516:                 throw new IllegalStateException("User configured " + ConsumerConfig.PARTITION_ASSIGNMENT_STRATEGY_CONFIG +
517:                     " to empty while trying to subscribe for group protocol to auto assign partitions");
518:             }
519:             // Always update the heartbeat last poll time so that the heartbeat thread does not leave the
520:             // group proactively due to application inactivity even if (say) the coordinator cannot be found.
521:             pollHeartbeat(timer.currentTimeMs());
522:             if (coordinatorUnknownAndUnreadySync(timer)) {
523:                 return false;
524:             }
525: 
526:             if (rejoinNeededOrPending()) {
527:                 // due to a race condition between the initial metadata fetch and the initial rebalance,
528:                 // we need to ensure that the metadata is fresh before joining initially. This ensures
529:                 // that we have matched the pattern against the cluster's topics at least once before joining.
530:                 if (subscriptions.hasPatternSubscription()) {
531:                     // For consumer group that uses pattern-based subscription, after a topic is created,
532:                     // any consumer that discovers the topic after metadata refresh can trigger rebalance
533:                     // across the entire consumer group. Multiple rebalances can be triggered after one topic
534:                     // creation if consumers refresh metadata at vastly different times. We can significantly
535:                     // reduce the number of rebalances caused by single topic creation by asking consumer to
536:                     // refresh metadata before re-joining the group as long as the refresh backoff time has
537:                     // passed.
538:                     if (this.metadata.timeToAllowUpdate(timer.currentTimeMs()) == 0) {
539:                         this.metadata.requestUpdate(true);
540:                     }
541: 
542:                     if (!client.ensureFreshMetadata(timer)) {
543:                         return false;
544:                     }
545: 
546:                     doUpdateSubscriptionMetadataIfClusterMetadataChanged();
547:                 }
548: 
549:                 // if not wait for join group, we would just use a timer of 0
550:                 if (!ensureActiveGroup(waitForJoinGroup ? timer : time.timer(0L))) {
551:                     // since we may use a different timer in the callee, we'd still need
552:                     // to update the original timer's current time after the call
553:                     timer.update(time.milliseconds());
554: 
555:                     return false;
556:                 }
557:             }
558:         } else {
559:             // For manually assigned partitions, we do not try to pro-actively lookup coordinator;
560:             // instead we only try to refresh metadata when necessary.
561:             // If connections to all nodes fail, wakeups triggered while attempting to send fetch
562:             // requests result in polls returning immediately, causing a tight loop of polls. Without
563:             // the wakeup, poll() with no channels would block for the timeout, delaying re-connection.
564:             // awaitMetadataUpdate() in ensureCoordinatorReady initiates new connections with configured backoff and avoids the busy loop.
565:             if (metadata.updateRequested() && !client.hasReadyNodes(timer.currentTimeMs())) {
566:                 client.awaitMetadataUpdate(timer);
567:             }
568: 
569:             // if there is pending coordinator requests, ensure they have a chance to be transmitted.
570:             client.pollNoWakeup();
571:         }
572: 
573:         doAutoCommitOffsetsAsyncIfEnabled(timer.currentTimeMs());
574:         return true;
575:     }
576: 
577:     /**
578:      * Return the time to the next needed invocation of {@link ConsumerNetworkClient#poll(Timer)}.
579:      * @param now current time in milliseconds
580:      * @return the maximum time in milliseconds the caller should wait before the next invocation of poll()
581:      */
582:     public long timeToNextPoll(long now) {
583:         if (!autoCommitEnabled)
584:             return timeToNextHeartbeat(now);
585: 
586:         return Math.min(nextAutoCommitTimer.remainingMs(), timeToNextHeartbeat(now));
587:     }
