714:     /**
715:      * Used by COOPERATIVE rebalance protocol only.
716:      *
717:      * Validate the assignments returned by the assignor such that no owned partitions are going to
718:      * be reassigned to a different consumer directly: if the assignor wants to reassign an owned partition,
719:      * it must first remove it from the new assignment of the current owner so that it is not assigned to any
720:      * member, and then in the next rebalance it can finally reassign those partitions not owned by anyone to consumers.
721:      */
722:     private void validateCooperativeAssignment(final Map<String, List<TopicPartition>> ownedPartitions,
723:                                                final Map<String, Assignment> assignments) {
724:         Set<TopicPartition> totalRevokedPartitions = new HashSet<>();
725:         SortedSet<TopicPartition> totalAddedPartitions = new TreeSet<>(COMPARATOR);
726:         for (final Map.Entry<String, Assignment> entry : assignments.entrySet()) {
727:             final Assignment assignment = entry.getValue();
728:             final Set<TopicPartition> addedPartitions = new HashSet<>(assignment.partitions());
729:             addedPartitions.removeAll(ownedPartitions.get(entry.getKey()));
730:             final Set<TopicPartition> revokedPartitions = new HashSet<>(ownedPartitions.get(entry.getKey()));
731:             revokedPartitions.removeAll(assignment.partitions());
732: 
733:             totalAddedPartitions.addAll(addedPartitions);
734:             totalRevokedPartitions.addAll(revokedPartitions);
735:         }
736: 
737:         // if there are overlap between revoked partitions and added partitions, it means some partitions
738:         // immediately gets re-assigned to another member while it is still claimed by some member
739:         totalAddedPartitions.retainAll(totalRevokedPartitions);
740:         if (!totalAddedPartitions.isEmpty()) {
741:             log.error("With the COOPERATIVE protocol, owned partitions cannot be " +
742:                 "reassigned to other members; however the assignor has reassigned partitions {} which are still owned " +
743:                 "by some members", totalAddedPartitions);
744: 
745:             throw new IllegalStateException("Assignor supporting the COOPERATIVE protocol violates its requirements");
746:         }
747:     }
