909:     /**
910:      * @throws KafkaException if the callback throws exception
911:      */
912:     @Override
913:     public boolean rejoinNeededOrPending() {
914:         if (!subscriptions.hasAutoAssignedPartitions())
915:             return false;
916: 
917:         // we need to rejoin if we performed the assignment and metadata has changed;
918:         // also for those owned-but-no-longer-existed partitions we should drop them as lost
919:         if (assignmentSnapshot != null && !assignmentSnapshot.matches(metadataSnapshot)) {
920:             final String fullReason = String.format("cached metadata has changed from %s at the beginning of the rebalance to %s",
921:                 assignmentSnapshot, metadataSnapshot);
922:             requestRejoinIfNecessary("cached metadata has changed", fullReason);
923:             return true;
924:         }
925: 
926:         // we need to join if our subscription has changed since the last join
927:         if (joinedSubscription != null && !joinedSubscription.equals(subscriptions.subscription())) {
928:             final String fullReason = String.format("subscription has changed from %s at the beginning of the rebalance to %s",
929:                 joinedSubscription, subscriptions.subscription());
930:             requestRejoinIfNecessary("subscription has changed", fullReason);
931:             return true;
932:         }
933: 
934:         return super.rejoinNeededOrPending();
935:     }
