1030:     // visible for testing
1031:     void invokeCompletedOffsetCommitCallbacks() {
1032:         if (asyncCommitFenced.get()) {
1033:             throw new FencedInstanceIdException("Get fenced exception for group.instance.id "
1034:                 + rebalanceConfig.groupInstanceId.orElse("unset_instance_id")
1035:                 + ", current member.id is " + memberId());
1036:         }
1037:         while (true) {
1038:             OffsetCommitCompletion completion = completedOffsetCommits.poll();
1039:             if (completion == null) {
1040:                 break;
1041:             }
1042:             completion.invoke();
1043:         }
