1206:     private boolean invokePendingAsyncCommits(Timer timer) {
1207:         if (inFlightAsyncCommits.get() == 0) {
1208:             return true;
1209:         }
1210: 
1211:         long attempts = 0L;
1212:         do {
1213:             ensureCoordinatorReady(timer);
1214:             client.poll(timer);
1215:             invokeCompletedOffsetCommitCallbacks();
1216: 
1217:             if (inFlightAsyncCommits.get() == 0) {
1218:                 return true;
1219:             }
1220: 
1221:             timer.sleep(retryBackoff.backoff(attempts++));
1222:         } while (timer.notExpired());
1223: 
1224:         return false;
1225:     }
