1227:     private RequestFuture<Void> autoCommitOffsetsAsync() {
1228:         Map<TopicPartition, OffsetAndMetadata> allConsumedOffsets = subscriptions.allConsumed();
1229:         log.debug("Sending asynchronous auto-commit of offsets {}", allConsumedOffsets);
1230: 
1231:         return commitOffsetsAsync(allConsumedOffsets, (offsets, exception) -> {
1232:             if (exception != null) {
1233:                 if (exception instanceof RetriableCommitFailedException) {
1234:                     log.debug("Asynchronous auto-commit of offsets {} failed due to retriable error.", offsets,
1235:                         exception);
1236:                     nextAutoCommitTimer.updateAndReset(rebalanceConfig.retryBackoffMs);
1237:                 } else {
1238:                     log.warn("Asynchronous auto-commit of offsets {} failed: {}", offsets, exception.getMessage());
1239:                 }
1240:             } else {
1241:                 log.debug("Completed asynchronous auto-commit of offsets {}", offsets);
1242:             }
1243:         });
1244:     }
