1353: 
1354:         @Override
1355:         public void handle(OffsetCommitResponse commitResponse, RequestFuture<Void> future) {
1356:             coordinatorMetrics.commitSensor.record(response.requestLatencyMs());
1357:             Set<String> unauthorizedTopics = new HashSet<>();
