1359:             for (OffsetCommitResponseData.OffsetCommitResponseTopic topic : commitResponse.data().topics()) {
1360:                 for (OffsetCommitResponseData.OffsetCommitResponsePartition partition : topic.partitions()) {
1361:                     TopicPartition tp = new TopicPartition(topic.name(), partition.partitionIndex());
1362:                     OffsetAndMetadata offsetAndMetadata = this.offsets.get(tp);
1363: 
1364:                     long offset = offsetAndMetadata.offset();
1365: 
1366:                     Errors error = Errors.forCode(partition.errorCode());
1367:                     if (error == Errors.NONE) {
1368:                         log.debug("Committed offset {} for partition {}", offset, tp);
1369:                     } else {
