1735:     /**
1736:      * Tests {@link AsyncKafkaConsumer#processBackgroundEvents(Future, Timer, Predicate) processBackgroundEvents}
1737:      * handles the case where the {@link Future} takes a bit of time to complete, but does within the timeout.
1738:      */
1739:     @Test
1740:     public void testProcessBackgroundEventsWithInitialDelay() throws Exception {
1741:         consumer = newConsumer();
1742:         Timer timer = time.timer(1000);
1743:         CompletableFuture<?> future = mock(CompletableFuture.class);
1744:         CountDownLatch latch = new CountDownLatch(3);
1745: 
1746:         // Mock our call to Future.get(timeout) so that it mimics a delay of 200 milliseconds. Keep in mind that
1747:         // the incremental timeout inside processBackgroundEvents is 100 seconds for each pass. Our first two passes
1748:         // will exceed the incremental timeout, but the third will return.
1749:         doAnswer(invocation -> {
1750:             latch.countDown();
1751: 
1752:             if (latch.getCount() > 0) {
1753:                 long timeout = invocation.getArgument(0, Long.class);
1754:                 timer.sleep(timeout);
1755:                 throw new java.util.concurrent.TimeoutException("Intentional timeout");
1756:             }
1757: 
1758:             future.complete(null);
1759:             return null;
1760:         }).when(future).get(any(Long.class), any(TimeUnit.class));
1761: 
1762:         consumer.processBackgroundEvents(future, timer, e -> false);
1763: 
1764:         // 800 is the 1000 ms timeout (above) minus the 200 ms delay for the two incremental timeouts/retries.
1765:         assertEquals(800, timer.remainingMs());
1766:     }
