823:     /**
824:      * poll implementation using {@link ApplicationEventHandler}.
825:      *  1. Poll for background events. If there's a fetch response event, process the record and return it. If it is
826:      *  another type of event, process it.
827:      *  2. Send fetches if needed.
828:      *  If the timeout expires, return an empty ConsumerRecord.
829:      *
830:      * @param timeout timeout of the poll loop
831:      * @return ConsumerRecord.  It can be empty if time timeout expires.
832:      *
833:      * @throws org.apache.kafka.common.errors.WakeupException if {@link #wakeup()} is called before or while this
834:      *             function is called
835:      * @throws org.apache.kafka.common.errors.InterruptException if the calling thread is interrupted before or while
836:      *             this function is called
837:      * @throws org.apache.kafka.common.errors.RecordTooLargeException if the fetched record is larger than the maximum
838:      *             allowable size
839:      * @throws org.apache.kafka.common.KafkaException for any other unrecoverable errors
840:      * @throws java.lang.IllegalStateException if the consumer is not subscribed to any topics or manually assigned any
841:      *             partitions to consume from or an unexpected error occurred
842:      * @throws org.apache.kafka.clients.consumer.OffsetOutOfRangeException if the fetch position of the consumer is
843:      *             out of range and no offset reset policy is configured.
844:      * @throws org.apache.kafka.common.errors.TopicAuthorizationException if the consumer is not authorized to read
845:      *             from a partition
846:      * @throws org.apache.kafka.common.errors.SerializationException if the fetched records cannot be deserialized
847:      * @throws org.apache.kafka.common.errors.UnsupportedAssignorException if the `group.remote.assignor` configuration
848:      *             is set to an assignor that is not available on the broker.
849:      */
850:     @Override
851:     public ConsumerRecords<K, V> poll(final Duration timeout) {
852:         Timer timer = time.timer(timeout);
853: 
854:         acquireAndEnsureOpen();
855:         try {
856:             kafkaConsumerMetrics.recordPollStart(timer.currentTimeMs());
857: 
858:             if (subscriptions.hasNoSubscriptionOrUserAssignment()) {
859:                 throw new IllegalStateException("Consumer is not subscribed to any topics or assigned any partitions");
860:             }
861: 
862:             do {
863:                 PollEvent event = new PollEvent(timer.currentTimeMs());
864:                 // Make sure to let the background thread know that we are still polling.
865:                 // This will trigger async auto-commits of consumed positions when hitting
866:                 // the interval time or reconciling new assignments
867:                 applicationEventHandler.add(event);
868:                 // Wait for reconciliation and auto-commit to be triggered, to ensure all commit requests
869:                 // retrieve the positions to commit before proceeding with fetching new records
870:                 ConsumerUtils.getResult(event.reconcileAndAutoCommit(), defaultApiTimeoutMs.toMillis());
871: 
872:                 // We must not allow wake-ups between polling for fetches and returning the records.
873:                 // If the polled fetches are not empty the consumed position has already been updated in the polling
874:                 // of the fetches. A wakeup between returned fetches and returning records would lead to never
875:                 // returning the records in the fetches. Thus, we trigger a possible wake-up before we poll fetches.
876:                 wakeupTrigger.maybeTriggerWakeup();
877: 
878:                 updateAssignmentMetadataIfNeeded(timer);
879:                 final Fetch<K, V> fetch = pollForFetches(timer);
880:                 if (!fetch.isEmpty()) {
881:                     // before returning the fetched records, we can send off the next round of fetches
882:                     // and avoid block waiting for their responses to enable pipelining while the user
883:                     // is handling the fetched records.
884:                     //
885:                     // NOTE: since the consumed position has already been updated, we must not allow
886:                     // wakeups or any other errors to be triggered prior to returning the fetched records.
887:                     sendPrefetches(timer);
888: 
889:                     if (fetch.records().isEmpty()) {
890:                         log.trace("Returning empty records from `poll()` "
891:                             + "since the consumer's position has advanced for at least one topic partition");
892:                     }
893: 
894:                     return interceptors.onConsume(new ConsumerRecords<>(fetch.records(), fetch.nextOffsets()));
895:                 }
896:                 // We will wait for retryBackoffMs
897:             } while (timer.notExpired());
898: 
899:             return ConsumerRecords.empty();
900:         } finally {
901:             kafkaConsumerMetrics.recordPollEnd(timer.currentTimeMs());
902:             release();
903:         }
904:     }
