933:     private void commitAsync(Optional<Map<TopicPartition, OffsetAndMetadata>> offsets, OffsetCommitCallback callback) {
934:         acquireAndEnsureOpen();
935:         try {
936:             AsyncCommitEvent asyncCommitEvent = new AsyncCommitEvent(offsets);
937:             lastPendingAsyncCommit = commit(asyncCommitEvent).whenComplete((committedOffsets, throwable) -> {
938:                 if (throwable == null) {
939:                     offsetCommitCallbackInvoker.enqueueInterceptorInvocation(committedOffsets);
940:                 }
941: 
942:                 if (callback == null) {
943:                     if (throwable != null) {
944:                         log.error("Offset commit with offsets {} failed", committedOffsets, throwable);
945:                     }
946:                     return;
947:                 }
948: 
949:                 offsetCommitCallbackInvoker.enqueueUserCallbackInvocation(callback, committedOffsets, (Exception) throwable);
950:             });
951:         } finally {
952:             release();
953:         }
954:     }
