956:     private CompletableFuture<Map<TopicPartition, OffsetAndMetadata>> commit(final CommitEvent commitEvent) {
957:         maybeThrowInvalidGroupIdException();
958:         offsetCommitCallbackInvoker.executeCallbacks();
959: 
960:         if (commitEvent.offsets().isPresent() && commitEvent.offsets().get().isEmpty()) {
961:             return CompletableFuture.completedFuture(null);
962:         }
963: 
964:         applicationEventHandler.add(commitEvent);
965: 
966:         // This blocks until the background thread retrieves allConsumed positions to commit if none were explicitly specified.
967:         // This operation will ensure that the offsets to commit are not affected by fetches which may start after this
968:         ConsumerUtils.getResult(commitEvent.offsetsReady(), defaultApiTimeoutMs.toMillis());
969:         return commitEvent.future();
970:     }
