1549:     private void leaveGroupOnClose(final Timer timer, final CloseOptions.GroupMembershipOperation membershipOperation) {
1550:         if (groupMetadata.get().isEmpty())
1551:             return;
1552: 
1553:         log.debug("Leaving the consumer group during consumer close");
1554:         try {
1555:             applicationEventHandler.addAndGet(new LeaveGroupOnCloseEvent(calculateDeadlineMs(timer), membershipOperation));
1556:             log.info("Completed leaving the group");
1557:         } catch (TimeoutException e) {
1558:             log.warn("Consumer attempted to leave the group but couldn't " +
1559:                 "complete it within {} ms. It will proceed to close.", timer.timeoutMs());
1560:         } finally {
1561:             timer.update();
1562:         }
1563:     }
