1630:     private void awaitPendingAsyncCommitsAndExecuteCommitCallbacks(Timer timer, boolean enableWakeup) {
1631:         if (lastPendingAsyncCommit == null) {
1632:             return;
1633:         }
1634: 
1635:         try {
1636:             final CompletableFuture<Void> futureToAwait = new CompletableFuture<>();
1637:             // We don't want the wake-up trigger to complete our pending async commit future,
1638:             // so create new future here. Any errors in the pending async commit will be handled
1639:             // by the async commit future / the commit callback - here, we just want to wait for it to complete.
1640:             lastPendingAsyncCommit.whenComplete((v, t) -> futureToAwait.complete(null));
1641:             if (enableWakeup) {
1642:                 wakeupTrigger.setActiveTask(futureToAwait);
1643:             }
1644:             ConsumerUtils.getResult(futureToAwait, timer);
1645:             lastPendingAsyncCommit = null;
1646:         } finally {
1647:             if (enableWakeup) {
1648:                 wakeupTrigger.clearTask();
1649:             }
1650:             timer.update();
1651:         }
1652:         offsetCommitCallbackInvoker.executeCallbacks();
1653:     }
