1776:     private Fetch<K, V> pollForFetches(Timer timer) {
1777:         long pollTimeout = isCommittedOffsetsManagementEnabled()
1778:                 ? Math.min(applicationEventHandler.maximumTimeToWait(), timer.remainingMs())
1779:                 : timer.remainingMs();
1780: 
1781:         // if data is available already, return it immediately
1782:         final Fetch<K, V> fetch = collectFetch();
1783:         if (!fetch.isEmpty()) {
1784:             return fetch;
1785:         }
1786: 
1787:         // send any new fetches (won't resend pending fetches)
1788:         sendFetches(timer);
1789: 
1790:         // We do not want to be stuck blocking in poll if we are missing some positions
1791:         // since the offset lookup may be backing off after a failure
1792: 
1793:         // NOTE: the use of cachedSubscriptionHasAllFetchPositions means we MUST call
1794:         // updateAssignmentMetadataIfNeeded before this method.
1795:         if (!cachedSubscriptionHasAllFetchPositions && pollTimeout > retryBackoffMs) {
1796:             pollTimeout = retryBackoffMs;
1797:         }
1798: 
1799:         log.trace("Polling for fetches with timeout {}", pollTimeout);
1800: 
1801:         Timer pollTimer = time.timer(pollTimeout);
1802:         wakeupTrigger.setFetchAction(fetchBuffer);
1803: 
1804:         // Wait a bit for some fetched data to arrive, as there may not be anything immediately available. Note the
1805:         // use of a shorter, dedicated "pollTimer" here which updates "timer" so that calling method (poll) will
1806:         // correctly handle the overall timeout.
1807:         try {
1808:             fetchBuffer.awaitNotEmpty(pollTimer);
1809:         } catch (InterruptException e) {
1810:             log.trace("Interrupt during fetch", e);
1811:             throw e;
1812:         } finally {
1813:             timer.update(pollTimer.currentTimeMs());
1814:             wakeupTrigger.clearTask();
1815:         }
1816: 
1817:         return collectFetch();
1818:     }
1819: 
1820:     /**
1821:      * Perform the "{@link FetchCollector#collectFetch(FetchBuffer) fetch collection}" step by reading raw data out
1822:      * of the {@link #fetchBuffer}, converting it to a well-formed {@link CompletedFetch}, validating that it and
1823:      * the internal {@link SubscriptionState state} are correct, and then converting it all into a {@link Fetch}
1824:      * for returning.
1825:      *
1826:      * <p/>
1827:      *
1828:      * This method will {@link ConsumerNetworkThread#wakeup() wake up the network thread} before returning. This is
1829:      * done as an optimization so that the <em>next round of data can be pre-fetched</em>.
1830:      */
1831:     private Fetch<K, V> collectFetch() {
1832:         final Fetch<K, V> fetch = fetchCollector.collectFetch(fetchBuffer);
1833: 
1834:         // Notify the network thread to wake up and start the next round of fetching.
1835:         applicationEventHandler.wakeupNetworkThread();
1836: 
1837:         return fetch;
1838:     }
