2002:     /**
2003:      * Acquire the light lock protecting this consumer from multithreaded access. Instead of blocking
2004:      * when the lock is not available, however, we just throw an exception (since multithreaded usage is not
2005:      * supported).
2006:      *
2007:      * @throws ConcurrentModificationException if another thread already has the lock
2008:      */
2009:     private void acquire() {
2010:         final Thread thread = Thread.currentThread();
2011:         final long threadId = thread.getId();
2012:         if (threadId != currentThread.get() && !currentThread.compareAndSet(NO_CURRENT_THREAD, threadId))
2013:             throw new ConcurrentModificationException("KafkaConsumer is not safe for multi-threaded access. " +
2014:                 "currentThread(name: " + thread.getName() + ", id: " + threadId + ")" +
2015:                 " otherThread(id: " + currentThread.get() + ")"
2016:             );
2017:         refCount.incrementAndGet();
2018:     }
