1513:     private void autoCommitOnClose(final Timer timer) {
1514:         if (groupMetadata.get().isEmpty())
1515:             return;
1516: 
1517:         if (autoCommitEnabled)
1518:             commitSyncAllConsumed(timer);
1519: 
1520:         applicationEventHandler.add(new CommitOnCloseEvent());
1521:     }
