1523:     private void runRebalanceCallbacksOnClose() {
1524:         if (groupMetadata.get().isEmpty())
1525:             return;
1526: 
1527:         int memberEpoch = groupMetadata.get().get().generationId();
1528: 
1529:         Set<TopicPartition> assignedPartitions = groupAssignmentSnapshot.get();
1530: 
1531:         if (assignedPartitions.isEmpty())
1532:             // Nothing to revoke.
1533:             return;
1534: 
1535:         SortedSet<TopicPartition> droppedPartitions = new TreeSet<>(TOPIC_PARTITION_COMPARATOR);
1536:         droppedPartitions.addAll(assignedPartitions);
1537: 
1538:         final Exception error;
1539: 
1540:         if (memberEpoch > 0)
1541:             error = rebalanceListenerInvoker.invokePartitionsRevoked(droppedPartitions);
1542:         else
1543:             error = rebalanceListenerInvoker.invokePartitionsLost(droppedPartitions);
1544: 
1545:         if (error != null)
1546:             throw ConsumerUtils.maybeWrapAsKafkaException(error);
1547:     }
