788:   private static void addToComposite(GradleProjectSettings settings, String buildRootProjectName, String buildPath) {
789:     GradleProjectSettings.CompositeBuild compositeBuild = settings.getCompositeBuild();
790:     if (compositeBuild == null) {
791:       compositeBuild = new GradleProjectSettings.CompositeBuild();
792:       compositeBuild.setCompositeDefinitionSource(CompositeDefinitionSource.IDE);
793:       settings.setCompositeBuild(compositeBuild);
