17: /**
18:  * Go through all `probe` and `also` metas in XMIR files, try to locate the
19:  * objects pointed by `probe` in Objectionary, and if found, register them in
20:  * the catalog.
21:  * More about the purpose of this Mojo is in
22:  * <a href="https://github.com/objectionary/eo/issues/1323">this issue</a>.
23:  *
24:  * @since 0.28.11
25:  */
26: @Mojo(
27:     name = "probe",
28:     defaultPhase = LifecyclePhase.PROCESS_SOURCES,
29:     threadSafe = true
30: )
31: public final class MjProbe extends MjSafe {
32: 
33:     /**
34:      * Objectionary.
35:      * @since 0.50
36:      * @checkstyle MemberNameCheck (5 lines)
37:      */
38:     @SuppressWarnings("PMD.ImmutableField")
39:     private Objectionary objectionary = new OyIndexed(
40:         new OyRemote(this.hash)
41:     );
42: 
43:     @Override
44:     public void exec() throws IOException {
45:         if (this.offline) {
46:             Logger.info(
47:                 this,
48:                 "No programs were probed because eo.offline flag is TRUE"
49:             );
50:         } else {
51:             this.probe();
52:         }
53:     }
54: 
55:     /**
56:      * Probe objects.
57:      */
58:     private void probe() {
59:         final Collection<TjForeign> tojos = this.scopedTojos().unprobed();
60:         if (tojos.isEmpty()) {
61:             if (this.scopedTojos().size() == 0) {
62:                 Logger.warn(this, "Nothing to probe, since there are no programs");
63:             } else {
64:                 Logger.info(
65:                     this,
66:                     "Nothing to probe, all %d programs checked already",
67:                     this.scopedTojos().size()
68:                 );
69:             }
70:         } else {
71:             final long start = System.currentTimeMillis();
72:             final Map<String, Boolean> probed = new ConcurrentHashMap<>(0);
73:             if (this.probed(tojos, probed) == 0) {
74:                 Logger.info(this, "No probes found in %d programs", tojos.size());
75:             } else {
76:                 Logger.info(
77:                     this, "Found %d probe(s) in %d program(s) in %[ms]s: %s",
78:                     probed.size(), tojos.size(),
79:                     System.currentTimeMillis() - start,
80:                     probed.keySet()
81:                 );
82:             }
83:         }
84:     }
85: 
86:     /**
87:      * Probe given tojos and return amount of probed objects.
88:      * @param tojos Tojos
89:      * @param probed Probed objects
90:      * @return Amount of probed objects
91:      */
92:     private int probed(final Collection<TjForeign> tojos, final Map<String, Boolean> probed) {
93:         return new Threaded<>(
94:             tojos,
95:             tojo -> {
96:                 final Path src = tojo.xmir();
97:                 final Collection<String> objects = new ListOf<>(new Probes(src));
98:                 if (!objects.isEmpty()) {
99:                     Logger.debug(this, "Probing object(s): %s", objects);
100:                 }
101:                 int count = 0;
102:                 for (final String object : objects) {
103:                     if (!this.objectionary.contains(object)) {
104:                         continue;
105:                     }
106:                     ++count;
107:                     this.scopedTojos().add(object).withDiscoveredAt(src);
108:                     probed.put(object, true);
109:                 }
110:                 tojo.withProbed(count);
111:                 return count;
112:             }
113:         ).total();
114:     }
