92:     private int allProbed(final Collection<TjForeign> tojos, final Map<String, Boolean> probed) {
93:         return new Threaded<>(
94:             tojos,
95:             tojo -> {
96:                 final Path src = tojo.xmir();
97:                 final Collection<String> allObjects = new ListOf<>(new Probes(src));
98:                 if (!allObjects.isEmpty()) {
99:                     Logger.debug(this, "Probing object(s): %s", allObjects);
100:                 }
