250:     @BuildStep
251:     @Record(ExecutionTime.RUNTIME_INIT)
252:     void handler(LaunchModeBuildItem launch,
253:             BuildProducer<NotFoundPageDisplayableEndpointBuildItem> displayableEndpoints,
254:             BuildProducer<RouteBuildItem> routes,
255:             BuildProducer<SystemPropertyBuildItem> systemProperties,
256:             OpenApiRecorder recorder,
257:             NonApplicationRootPathBuildItem nonApplicationRootPathBuildItem,
258:             OpenApiRuntimeConfig openApiRuntimeConfig,
259:             ShutdownContextBuildItem shutdownContext,
260:             SmallRyeOpenApiConfig openApiConfig,
261:             List<FilterBuildItem> filterBuildItems,
262:             ManagementInterfaceBuildTimeConfig managementBuildTimeConfig) {
263:         /*
264:          * <em>Ugly Hack</em>
265:          * In dev mode, we pass a classloader to load the up to date OpenAPI document.
266:          * This hack is required because using the TCCL would get an outdated version - the initial one.
267:          * This is because the worker thread on which the handler is called captures the TCCL at creation time
268:          * and does not allow updating it.
269:          *
270:          * This classloader must ONLY be used to load the OpenAPI document.
271:          *
272:          * In non dev mode, the TCCL is used.
273:          */
274:         if (launch.getLaunchMode() == LaunchMode.DEVELOPMENT) {
275:             recorder.setupClDevMode(shutdownContext);
276:         }
277: 
278:         Handler<RoutingContext> handler = recorder.handler(openApiRuntimeConfig);
279: 
280:         Consumer<Route> corsFilter = null;
281:         // Add CORS filter if the path is not attached to main root
282:         // as 'http-vertx' only adds CORS filter to http route path
283:         if (!nonApplicationRootPathBuildItem.isAttachedToMainRouter()) {
284:             for (FilterBuildItem filterBuildItem : filterBuildItems) {
285:                 if (filterBuildItem.getPriority() == FilterBuildItem.CORS) {
286:                     corsFilter = recorder.corsFilter(filterBuildItem.toFilter());
287:                     break;
288:                 }
289:             }
290:         }
291: 
292:         routes.produce(RouteBuildItem.newManagementRoute(openApiConfig.path(), MANAGEMENT_ENABLED)
293:                 .withRouteCustomizer(corsFilter)
294:                 .withRoutePathConfigKey("quarkus.smallrye-openapi.path")
295:                 .withRequestHandler(handler)
296:                 .displayOnNotFoundPage("Open API Schema document")
297:                 .asBlockingRoute()
298:                 .build());
299: 
300:         routes.produce(
301:                 RouteBuildItem.newManagementRoute(openApiConfig.path() + ".json", MANAGEMENT_ENABLED)
302:                         .withRouteCustomizer(corsFilter)
303:                         .withRequestHandler(handler)
304:                         .build());
305: 
306:         routes.produce(
307:                 RouteBuildItem.newManagementRoute(openApiConfig.path() + ".yaml", MANAGEMENT_ENABLED)
308:                         .withRouteCustomizer(corsFilter)
309:                         .withRequestHandler(handler)
310:                         .build());
311: 
312:         routes.produce(
313:                 RouteBuildItem.newManagementRoute(openApiConfig.path() + ".yml", MANAGEMENT_ENABLED)
314:                         .withRouteCustomizer(corsFilter)
315:                         .withRequestHandler(handler)
316:                         .build());
317: 
318:         // If management is enabled and swagger-ui is part of management, we need to add CORS so that swagger can hit the endpoint
319:         if (isManagement(managementBuildTimeConfig, openApiConfig, launch)) {
320:             Config c = ConfigProvider.getConfig();
321: 
322:             // quarkus.http.cors.enabled=true
323:             // quarkus.http.cors.origins
324:             Optional<Boolean> maybeCors = c.getOptionalValue("quarkus.http.cors.enabled", Boolean.class);
325:             if (!maybeCors.isPresent() || !maybeCors.get().booleanValue()) {
326:                 // We need to set quarkus.http.cors.enabled=true
327:                 systemProperties.produce(new SystemPropertyBuildItem("quarkus.http.cors.enabled", "true"));
328:             }
329: 
330:             String managementUrl = getManagementRoot(launch, nonApplicationRootPathBuildItem, openApiConfig,
331:                     managementBuildTimeConfig);
332: 
333:             List<String> origins = c.getOptionalValues("quarkus.http.cors.origins", String.class).orElse(new ArrayList<>());
334:             if (!origins.contains(managementUrl)) {
335:                 // We need to set quarkus.http.cors.origins
336:                 origins.add(managementUrl);
337:                 String originConfigValue = String.join(",", origins);
338:                 systemProperties.produce(new SystemPropertyBuildItem("quarkus.http.cors.origins", originConfigValue));
339:             }
340: 
341:         }
342:     }
