621:     private Map<String, List<String>> getRolesAllowedMethodReferences(OpenApiFilteredIndexViewBuildItem indexViewBuildItem) {
622:         IndexView index = indexViewBuildItem.getIndex();
623:         return SecurityConstants.ROLES_ALLOWED
624:                 .stream()
625:                 .map(index::getAnnotations)
626:                 .flatMap(Collection::stream)
627:                 .flatMap(t -> getMethods(t, index))
628:                 .collect(Collectors.toMap(
629:                         e -> createUniqueMethodReference(e.getKey().classInfo(), e.getKey().method()),
630:                         e -> List.of(e.getValue().value().asStringArray()),
631:                         (v1, v2) -> {
632:                             if (!Objects.equals(v1, v2)) {
633:                                 log.warnf("Dropping duplicate annotation, but the values were different; v1: %s, v2: %s", v1,
634:                                         v2);
635:                             }
636:                             return v1;
637:                         }));
638:     }
