654:     private List<String> getAuthenticatedMethodReferences(OpenApiFilteredIndexViewBuildItem indexViewBuildItem) {
655:         IndexView index = indexViewBuildItem.getIndex();
656:         return index
657:                 .getAnnotations(DotName.createSimple(Authenticated.class.getName()))
658:                 .stream()
659:                 .flatMap(t -> getMethods(t, index))
660:                 .map(e -> createUniqueMethodReference(e.getKey().classInfo(), e.getKey().method()))
661:                 .distinct()
662:                 .toList();
663:     }
