665:     private static Stream<Map.Entry<ClassAndMethod, AnnotationInstance>> getMethods(AnnotationInstance annotation,
666:             IndexView index) {
667:         if (annotation.target().kind() == Kind.METHOD) {
668:             MethodInfo method = annotation.target().asMethod();
669: 
670:             if (isValidOpenAPIMethodForAutoAdd(method)) {
671:                 return Stream.of(Map.entry(new ClassAndMethod(method.declaringClass(), method), annotation));
672:             }
673:         } else if (annotation.target().kind() == Kind.CLASS) {
674:             ClassInfo classInfo = annotation.target().asClass();
675:             List<MethodInfo> methods = getMethods(classInfo, index);
676:             return methods
677:                     .stream()
678:                     // drop methods that specify the annotation directly
679:                     .filter(method -> !method.hasDeclaredAnnotation(annotation.name()))
680:                     .filter(method -> isValidOpenAPIMethodForAutoAdd(method))
681:                     .map(method -> {
682:                         final ClassInfo resourceClass;
683: 
684:                         if (method.declaringClass().isInterface()) {
685:                             /*
686:                              * smallrye-open-api processes interfaces as the resource class as long as
687:                              * there is a concrete implementation available. Using the interface method's
688:                              * declaring class here allows us to match on the hash that will be set by
689:                              * #handleOperation during scanning.
690:                              */
691:                             resourceClass = method.declaringClass();
692:                         } else {
693:                             resourceClass = classInfo;
694:                         }
695: 
696:                         return Map.entry(new ClassAndMethod(resourceClass, method), annotation);
697:                     });
698:         }
699: 
700:         return Stream.empty();
701:     }
702: 
703:     private Map<String, ClassAndMethod> getClassNamesMethodReferences(
704:             OpenApiFilteredIndexViewBuildItem apiFilteredIndexViewBuildItem) {
705:         FilteredIndexView filteredIndex = apiFilteredIndexViewBuildItem.getIndex();
706:         List<AnnotationInstance> openapiAnnotations = new ArrayList<>();
707:         Set<DotName> allOpenAPIEndpoints = getAllOpenAPIEndpoints();
708:         for (DotName dotName : allOpenAPIEndpoints) {
709:             openapiAnnotations.addAll(filteredIndex.getAnnotations(dotName));
710:         }
711: 
712:         Map<String, ClassAndMethod> classNames = new HashMap<>();
713: 
714:         for (AnnotationInstance ai : openapiAnnotations) {
715:             if (ai.target().kind().equals(AnnotationTarget.Kind.METHOD)) {
716:                 MethodInfo method = ai.target().asMethod();
717:                 ClassInfo declaringClass = method.declaringClass();
718:                 Type[] params = method.parameterTypes().toArray(new Type[] {});
719: 
720:                 if (Modifier.isInterface(declaringClass.flags())) {
721:                     addMethodImplementationClassNames(method, params, filteredIndex
722:                             .getAllKnownImplementors(declaringClass.name()), classNames);
723:                 } else if (Modifier.isAbstract(declaringClass.flags())) {
724:                     addMethodImplementationClassNames(method, params, filteredIndex
725:                             .getAllKnownSubclasses(declaringClass.name()), classNames);
726:                 } else {
727:                     String ref = createUniqueMethodReference(declaringClass, method);
728:                     classNames.put(ref, new ClassAndMethod(declaringClass, method));
729:                 }
730:             }
731:         }
732:         return classNames;
733:     }
734: 
735:     void addMethodImplementationClassNames(MethodInfo method, Type[] params, Collection<ClassInfo> classes,
736:             Map<String, ClassAndMethod> classNames) {
737:         for (ClassInfo impl : classes) {
738:             MethodInfo implMethod = impl.method(method.name(), params);
739: 
740:             if (implMethod != null) {
741:                 classNames.put(createUniqueMethodReference(impl, implMethod),
742:                         new ClassAndMethod(impl, implMethod));
743:             }
744: 
745:             classNames.put(createUniqueMethodReference(impl, method),
746:                     new ClassAndMethod(impl, method));
747:         }
748:     }
749: 
750:     public static String createUniqueMethodReference(ClassInfo classInfo, MethodInfo methodInfo) {
751:         return "m" + classInfo.hashCode() + "_" + methodInfo.hashCode();
752:     }
753: 
754:     private static boolean isValidOpenAPIMethodForAutoAdd(MethodInfo method) {
755:         return isOpenAPIEndpoint(method) && !method.hasAnnotation(OPENAPI_SECURITY_REQUIREMENT)
756:                 && method.declaringClass().declaredAnnotation(OPENAPI_SECURITY_REQUIREMENT) == null;
757:     }
