850:     private void registerReflectionForApiResponseSchemaSerialization(BuildProducer<ReflectiveClassBuildItem> reflectiveClass,
851:             BuildProducer<ReflectiveHierarchyBuildItem> reflectiveHierarchy,
852:             Collection<AnnotationInstance> apiResponseAnnotationInstances) {
853:         for (AnnotationInstance apiResponseAnnotationInstance : apiResponseAnnotationInstances) {
854:             AnnotationValue contentAnnotationValue = apiResponseAnnotationInstance.value(OPENAPI_RESPONSE_CONTENT);
855:             if (contentAnnotationValue == null) {
856:                 continue;
857:             }
858: 
859:             AnnotationInstance[] contents = contentAnnotationValue.asNestedArray();
860:             for (AnnotationInstance content : contents) {
861:                 AnnotationValue annotationValue = content.value(OPENAPI_RESPONSE_SCHEMA);
862:                 if (annotationValue == null) {
863:                     continue;
864:                 }
865: 
866:                 AnnotationInstance schema = annotationValue.asNested();
867:                 String source = getClass().getSimpleName() + " > " + schema.target();
868: 
869:                 AnnotationValue schemaImplementationClass = schema.value(OPENAPI_SCHEMA_IMPLEMENTATION);
870:                 if (schemaImplementationClass != null) {
871:                     produceReflectiveHierarchy(reflectiveHierarchy, schemaImplementationClass.asClass(), source);
872:                 }
873: 
874:                 AnnotationValue schemaNotClass = schema.value(OPENAPI_SCHEMA_NOT);
875:                 if (schemaNotClass != null) {
876:                     reflectiveClass.produce(
877:                             ReflectiveClassBuildItem.builder(schemaNotClass.asString()).methods().fields().build());
878:                 }
879: 
880:                 produceReflectiveHierarchy(reflectiveHierarchy, schema.value(OPENAPI_SCHEMA_ONE_OF), source);
881:                 produceReflectiveHierarchy(reflectiveHierarchy, schema.value(OPENAPI_SCHEMA_ANY_OF), source);
882:                 produceReflectiveHierarchy(reflectiveHierarchy, schema.value(OPENAPI_SCHEMA_ALL_OF), source);
883:             }
884:         }
885:     }
