380:             BeanArchiveIndexBuildItem beanArchiveIndexBuildItem,
381:             BuildExclusionsBuildItem buildExclusionsBuildItem) {
382: 
383:         CompositeIndex compositeIndex = CompositeIndex.create(
384:                 combinedIndexBuildItem.getIndex(),
385:                 beanArchiveIndexBuildItem.getIndex());
386: 
387:         OpenApiConfig config = OpenApiConfig.fromConfig(ConfigProvider.getConfig());
388:         Set<DotName> buildTimeClassExclusions = buildExclusionsBuildItem.getExcludedDeclaringClasses()
389:                 .stream()
390:                 .map(DotName::createSimple)
391:                 .collect(Collectors.toSet());
392: 
393:         FilteredIndexView indexView = new FilteredIndexView(compositeIndex, config) {
394:             @Override
395:             public boolean accepts(DotName className) {
396:                 if (super.accepts(className)) {
397:                     return !buildTimeClassExclusions.contains(className);
398:                 }
399: 
400:                 return false;
401:             }
402:         };
403: 
404:         return new OpenApiFilteredIndexViewBuildItem(indexView);
405:     }
