545:     private boolean hasAutoEndpointSecurity(
546:             OpenApiFilteredIndexViewBuildItem indexViewBuildItem,
547:             LaunchModeBuildItem launchMode,
548:             SmallRyeOpenApiConfig config) {
549: 
550:         if (securityConfig(launchMode, config::autoAddSecurityRequirement)) {
551:             Map<String, List<String>> rolesAllowedMethods = Collections.emptyMap();
552:             List<String> authenticatedMethods = Collections.emptyList();
553: 
554:             rolesAllowedMethods = getRolesAllowedMethodReferences(indexViewBuildItem);
555: 
556:             for (String methodRef : getPermissionsAllowedMethodReferences(indexViewBuildItem)) {
557:                 rolesAllowedMethods.putIfAbsent(methodRef, List.of());
558:             }
559: 
560:             authenticatedMethods = getAuthenticatedMethodReferences(indexViewBuildItem);
561: 
562:             return !rolesAllowedMethods.isEmpty() || !authenticatedMethods.isEmpty();
563:         }
564: 
565:         return false;
566:     }
