892:     @BuildStep
893:     public void build(BuildProducer<FeatureBuildItem> feature,
894:             BuildProducer<GeneratedResourceBuildItem> resourceBuildItemBuildProducer,
895:             BuildProducer<NativeImageResourceBuildItem> nativeImageResources,
896:             BuildProducer<OpenApiDocumentBuildItem> openApiDocumentProducer,
897:             OpenApiFilteredIndexViewBuildItem openApiFilteredIndexViewBuildItem,
898:             Capabilities cap,
899:             List<AddToOpenAPIDefinitionBuildItem> openAPIBuildItems,
900:             HttpRootPathBuildItem httpRootPathBuildItem,
901:             SmallRyeOpenApiConfig smallRyeOpenApiConfig,
902:             OutputTargetBuildItem outputTargetBuildItem,
903:             List<IgnoreStaticDocumentBuildItem> ignoreStaticDocumentBuildItems) {
904: 
905:         ClassLoader loader = Thread.currentThread().getContextClassLoader();
906:         FilteredIndexView index = openApiFilteredIndexViewBuildItem.getIndex();
907:         Config config = ConfigProvider.getConfig();
908: 
909:         feature.produce(new FeatureBuildItem(Feature.SMALLRYE_OPENAPI));
910: 
911:         List<Pattern> urlIgnorePatterns = ignoreStaticDocumentBuildItems.stream()
912:                 .map(IgnoreStaticDocumentBuildItem::getUrlIgnorePattern)
913:                 .toList();
914: 
915:         SmallRyeOpenAPI.Builder builder = SmallRyeOpenAPI.builder()
916:                 .withConfig(config)
917:                 .withIndex(index)
918:                 .withApplicationClassLoader(loader)
919:                 .withScannerClassLoader(loader)
920:                 .enableModelReader(true)
921:                 .enableStandardStaticFiles(Boolean.FALSE.equals(smallRyeOpenApiConfig.ignoreStaticDocument()))
922:                 .withResourceLocator(path -> {
923:                     URL locator = loader.getResource(path);
924:                     if (locator == null || shouldIgnore(urlIgnorePatterns, locator.toString())) {
925:                         return null;
926:                     }
927:                     return locator;
928:                 })
929:                 .withCustomStaticFile(() -> loadAdditionalDocsModel(smallRyeOpenApiConfig, urlIgnorePatterns,
930:                         outputTargetBuildItem.getOutputDirectory()))
931:                 .enableAnnotationScan(shouldScanAnnotations(cap, index))
932:                 .withScannerFilter(getScannerFilter(cap, index))
933:                 .withContextRootResolver(getContextRootResolver(config, cap, httpRootPathBuildItem))
934:                 .withTypeConverter(getTypeConverter(index, cap))
935:                 .withOperationHandler(this::handleOperation)
936:                 .enableUnannotatedPathParameters(cap.isPresent(Capability.RESTEASY_REACTIVE))
937:                 .enableStandardFilter(false)
938:                 .withFilters(openAPIBuildItems.stream()
939:                         .map(AddToOpenAPIDefinitionBuildItem::getOASFilter)
940:                         .sorted(Comparator.comparing(filter -> filter.getClass().getName()))
941:                         .toList());
942: 
943:         getUserDefinedBuildtimeFilters(index).forEach(builder::addFilterName);
944: 
945:         // This should be the final filter to run
946:         builder.addFilter(new DefaultInfoFilter(config));
947: 
948:         SmallRyeOpenAPI openAPI = builder.build();
949: 
950:         Stream.of(Map.<String, Supplier<String>> entry("JSON", openAPI::toJSON),
951:                 Map.<String, Supplier<String>> entry("YAML", openAPI::toYAML))
952:                 .forEach(format -> {
953:                     String name = OpenApiConstants.BASE_NAME + format.getKey();
954:                     byte[] data = format.getValue().get().getBytes(StandardCharsets.UTF_8);
955:                     resourceBuildItemBuildProducer.produce(new GeneratedResourceBuildItem(name, data));
956:                     nativeImageResources.produce(new NativeImageResourceBuildItem(name));
957:                 });
958: 
959:         SmallRyeOpenAPI finalOpenAPI;
960:         SmallRyeOpenAPI storedOpenAPI;
961: 
962:         Supplier<SmallRyeOpenAPI.Builder> filterOnlyBuilder = () -> {
963:             var runtimeFilterBuilder = SmallRyeOpenAPI.builder()
964:                     .enableModelReader(false)
965:                     .enableStandardStaticFiles(false)
966:                     .enableAnnotationScan(false)
967:                     .enableStandardFilter(false)
968:                     .withInitialModel(openAPI.model());
969: 
970:             Optional.ofNullable(getAutoServerFilter(smallRyeOpenApiConfig, true, "Auto generated value"))
971:                     .ifPresent(runtimeFilterBuilder::addFilter);
972: 
973:             return runtimeFilterBuilder;
974:         };
975: 
976:         try {
977:             builder = filterOnlyBuilder.get();
978:             getUserDefinedRuntimeFilters(config, index).forEach(builder::addFilterName);
979:             storedOpenAPI = builder.build();
980:         } catch (Exception e) {
981:             // Try again without the user-defined runtime filters
982:             storedOpenAPI = filterOnlyBuilder.get().build();
983:         }
984: 
985:         finalOpenAPI = storedOpenAPI;
986: 
987:         smallRyeOpenApiConfig.storeSchemaDirectory().ifPresent(storageDir -> {
988:             try {
989:                 storeGeneratedSchema(storageDir, smallRyeOpenApiConfig.storeSchemaFileName(), outputTargetBuildItem,
990:                         finalOpenAPI.toJSON(), "json");
991:                 storeGeneratedSchema(storageDir, smallRyeOpenApiConfig.storeSchemaFileName(), outputTargetBuildItem,
992:                         finalOpenAPI.toYAML(), "yaml");
993:             } catch (IOException e) {
994:                 throw new UncheckedIOException(e);
995:             }
996:         });
997: 
998:         openApiDocumentProducer.produce(new OpenApiDocumentBuildItem(toOpenApiDocument(finalOpenAPI), finalOpenAPI));
999:     }
