1081:     private boolean isUsingVertxRoute(IndexView index) {
1082:         return !index.getAnnotations(VertxConstants.ROUTE).isEmpty() ||
1083:                 !index.getAnnotations(VertxConstants.ROUTE_BASE).isEmpty();
1084:     }
