428:     @BuildStep
429:     public BytecodeRecorderConstantDefinitionBuildItem pregenProxies(
430:             JpaModelBuildItem jpaModel,
431:             JpaModelIndexBuildItem indexBuildItem,
432:             TransformedClassesBuildItem transformedClassesBuildItem,
433:             List<PersistenceUnitDescriptorBuildItem> persistenceUnitDescriptorBuildItems,
434:             List<AdditionalJpaModelBuildItem> additionalJpaModelBuildItems,
435:             BuildProducer<GeneratedClassBuildItem> generatedClassBuildItemBuildProducer,
436:             LiveReloadBuildItem liveReloadBuildItem) {
437:         Set<String> managedClassAndPackageNames = new HashSet<>(jpaModel.getEntityClassNames());
438:         for (PersistenceUnitDescriptorBuildItem pud : persistenceUnitDescriptorBuildItems) {
439:             // Note: getManagedClassNames() can also return *package* names
440:             // See the source code of Hibernate ORM for proof:
441:             // org.hibernate.boot.archive.scan.internal.ScanResultCollector.isListedOrDetectable
442:             // is used for packages too, and it relies (indirectly) on getManagedClassNames().
443:             managedClassAndPackageNames.addAll(pud.getManagedClassNames());
444:         }
445: 
446:         for (AdditionalJpaModelBuildItem additionalJpaModelBuildItem : additionalJpaModelBuildItems) {
447:             managedClassAndPackageNames.add(additionalJpaModelBuildItem.getClassName());
448:         }
449: 
450:         PreGeneratedProxies proxyDefinitions = generatedProxies(managedClassAndPackageNames,
451:                 indexBuildItem.getIndex(), transformedClassesBuildItem,
452:                 generatedClassBuildItemBuildProducer, liveReloadBuildItem);
453: 
454:         // Make proxies available through a constant;
455:         // this is a hack to avoid introducing circular dependencies between build steps.
456:         //
457:         // If we just passed the proxy definitions to #build as a normal build item,
458:         // we would have the following dependencies:
459:         //
460:         // #pregenProxies => ProxyDefinitionsBuildItem => #build => BeanContainerListenerBuildItem
461:         // => Arc container init => BeanContainerBuildItem
462:         // => some RestEasy Reactive Method => BytecodeTransformerBuildItem
463:         // => build step that transforms bytecode => TransformedClassesBuildItem
464:         // => #pregenProxies
465:         //
466:         // Since the dependency from #preGenProxies to #build is only a static init thing
467:         // (#build needs to pass the proxy definitions to the recorder),
468:         // we get rid of the circular dependency by defining a constant
469:         // to pass the proxy definitions to the recorder.
470:         // That way, the dependency is only between #pregenProxies
471:         // and the build step that generates the bytecode of bytecode recorders.
472:         return new BytecodeRecorderConstantDefinitionBuildItem(PreGeneratedProxies.class, proxyDefinitions);
473:     }
