895:     private static void producePersistenceUnitDescriptorFromConfig(
896:             HibernateOrmConfig hibernateOrmConfig,
897:             String persistenceUnitName,
898:             HibernateOrmConfigPersistenceUnit persistenceUnitConfig,
899:             Set<String> modelClassesAndPackages,
900:             List<RecordableXmlMapping> xmlMappings,
901:             List<JdbcDataSourceBuildItem> jdbcDataSources,
902:             ApplicationArchivesBuildItem applicationArchivesBuildItem,
903:             LaunchMode launchMode,
904:             Capabilities capabilities,
905:             BuildProducer<SystemPropertyBuildItem> systemProperties,
906:             BuildProducer<NativeImageResourceBuildItem> nativeImageResources,
907:             BuildProducer<HotDeploymentWatchedFileBuildItem> hotDeploymentWatchedFiles,
908:             BuildProducer<PersistenceUnitDescriptorBuildItem> persistenceUnitDescriptors,
909:             BuildProducer<ReflectiveMethodBuildItem> reflectiveMethods,
910:             BuildProducer<UnremovableBeanBuildItem> unremovableBeans,
911:             Set<String> storageEngineCollector,
912:             List<DatabaseKindDialectBuildItem> dbKindMetadataBuildItems) {
913:         Optional<JdbcDataSourceBuildItem> jdbcDataSource = findJdbcDataSource(persistenceUnitName, persistenceUnitConfig,
914:                 jdbcDataSources);
915: 
916:         if (modelClassesAndPackages.isEmpty()) {
917:             LOG.warnf("Could not find any entities affected to the persistence unit '%s'.", persistenceUnitName);
918:         }
919: 
920:         QuarkusPersistenceUnitDescriptor descriptor = new QuarkusPersistenceUnitDescriptor(
921:                 persistenceUnitName, persistenceUnitName,
922:                 PersistenceUnitTransactionType.JTA,
923:                 // That's right, we're pushing both class names and package names
924:                 // to a method called "addClasses".
925:                 // It's a misnomer: while the method populates the set that backs getManagedClasses(),
926:                 // that method is also poorly named because it can actually return both class names
927:                 // and package names.
928:                 // See for proof:
929:                 // - how org.hibernate.boot.archive.scan.internal.ScanResultCollector.isListedOrDetectable
930:                 //   is used for packages too, even though it relies (indirectly) on getManagedClassNames().
931:                 // - the comment at org/hibernate/boot/model/process/internal/ScanningCoordinator.java:246:
932:                 //   "IMPL NOTE : "explicitlyListedClassNames" can contain class or package names..."
933:                 new ArrayList<>(modelClassesAndPackages),
934:                 new Properties(),
935:                 false);
936: 
937:         MultiTenancyStrategy multiTenancyStrategy = getMultiTenancyStrategy(persistenceUnitConfig.multitenant());
938: 
939:         collectDialectConfig(persistenceUnitName, persistenceUnitConfig,
940:                 dbKindMetadataBuildItems, jdbcDataSource, multiTenancyStrategy,
941:                 systemProperties, reflectiveMethods, descriptor.getProperties()::setProperty, storageEngineCollector);
942: 
943:         configureProperties(descriptor, persistenceUnitConfig, hibernateOrmConfig, false);
944: 
945:         configureSqlLoadScript(persistenceUnitName, persistenceUnitConfig, applicationArchivesBuildItem, launchMode,
946:                 nativeImageResources, hotDeploymentWatchedFiles, descriptor);
947: 
948:         Optional<FormatMapperKind> jsonMapper = jsonMapperKind(capabilities);
949:         Optional<FormatMapperKind> xmlMapper = xmlMapperKind(capabilities);
950:         jsonMapper.flatMap(FormatMapperKind::requiredBeanType)
951:                 .ifPresent(type -> unremovableBeans.produce(UnremovableBeanBuildItem.beanClassNames(type)));
952:         xmlMapper.flatMap(FormatMapperKind::requiredBeanType)
953:                 .ifPresent(type -> unremovableBeans.produce(UnremovableBeanBuildItem.beanClassNames(type)));
954:         persistenceUnitDescriptors.produce(
955:                 new PersistenceUnitDescriptorBuildItem(descriptor,
956:                         new RecordedConfig(
957:                                 jdbcDataSource.map(JdbcDataSourceBuildItem::getName),
958:                                 jdbcDataSource.map(JdbcDataSourceBuildItem::getDbKind),
959:                                 jdbcDataSource.flatMap(JdbcDataSourceBuildItem::getDbVersion),
960:                                 persistenceUnitConfig.dialect().dialect(),
961:                                 multiTenancyStrategy,
962:                                 hibernateOrmConfig.database().ormCompatibilityVersion(),
963:                                 persistenceUnitConfig.unsupportedProperties()),
964:                         persistenceUnitConfig.multitenantSchemaDatasource().orElse(null),
965:                         xmlMappings,
966:                         false,
967:                         isHibernateValidatorPresent(capabilities), jsonMapper, xmlMapper));
968:     }
