1086:     public static Map<String, Set<String>> getModelClassesAndPackagesPerPersistenceUnits(HibernateOrmConfig hibernateOrmConfig,
1087:             JpaModelBuildItem jpaModel, IndexView index, boolean enableDefaultPersistenceUnit) {
1088:         Map<String, Set<String>> modelClassesAndPackagesPerPersistenceUnits = new HashMap<>();
1089: 
1090:         boolean hasPackagesInQuarkusConfig = hasPackagesInQuarkusConfig(hibernateOrmConfig);
1091:         Collection<AnnotationInstance> packageLevelPersistenceUnitAnnotations = getPackageLevelPersistenceUnitAnnotations(
1092:                 index);
1093: 
1094:         Map<String, Set<String>> packageRules = new HashMap<>();
1095: 
1096:         if (hasPackagesInQuarkusConfig) {
1097:             // Config based packages have priorities over annotations.
1098:             // As long as there is one defined, annotations are ignored.
1099:             if (!packageLevelPersistenceUnitAnnotations.isEmpty()) {
1100:                 LOG.warn(
1101:                         "Mixing Quarkus configuration and @PersistenceUnit annotations to define the persistence units is not supported. Ignoring the annotations.");
1102:             }
1103: 
1104:             // handle the default persistence unit
1105:             if (enableDefaultPersistenceUnit) {
1106:                 if (!hibernateOrmConfig.defaultPersistenceUnit().packages().isPresent()) {
1107:                     throw new ConfigurationException("Packages must be configured for the default persistence unit.");
1108:                 }
1109: 
1110:                 for (String packageName : hibernateOrmConfig.defaultPersistenceUnit().packages().get()) {
1111:                     packageRules.computeIfAbsent(normalizePackage(packageName), p -> new HashSet<>())
1112:                             .add(PersistenceUnitUtil.DEFAULT_PERSISTENCE_UNIT_NAME);
1113:                 }
1114:             }
1115: 
1116:             // handle the named persistence units
1117:             for (Entry<String, HibernateOrmConfigPersistenceUnit> candidatePersistenceUnitEntry : hibernateOrmConfig
1118:                     .namedPersistenceUnits()
1119:                     .entrySet()) {
1120:                 String candidatePersistenceUnitName = candidatePersistenceUnitEntry.getKey();
1121: 
1122:                 Set<String> candidatePersistenceUnitPackages = candidatePersistenceUnitEntry.getValue().packages()
1123:                         .orElseThrow(() -> new ConfigurationException(String.format(Locale.ROOT,
1124:                                 "Packages must be configured for persistence unit '%s'.", candidatePersistenceUnitName)));
1125: 
1126:                 for (String packageName : candidatePersistenceUnitPackages) {
1127:                     packageRules.computeIfAbsent(normalizePackage(packageName), p -> new HashSet<>())
1128:                             .add(candidatePersistenceUnitName);
1129:                 }
1130:             }
1131:         } else if (!packageLevelPersistenceUnitAnnotations.isEmpty()) {
1132:             for (AnnotationInstance packageLevelPersistenceUnitAnnotation : packageLevelPersistenceUnitAnnotations) {
1133:                 String className = packageLevelPersistenceUnitAnnotation.target().asClass().name().toString();
1134:                 String packageName;
1135:                 if (className == null || className.isEmpty() || className.indexOf('.') == -1) {
1136:                     packageName = "";
1137:                 } else {
1138:                     packageName = normalizePackage(className.substring(0, className.lastIndexOf('.')));
1139:                 }
1140: 
1141:                 String persistenceUnitName = packageLevelPersistenceUnitAnnotation.value().asString();
1142:                 if (persistenceUnitName != null && !persistenceUnitName.isEmpty()) {
1143:                     packageRules.computeIfAbsent(packageName, p -> new HashSet<>())
1144:                             .add(persistenceUnitName);
1145:                 }
1146:             }
1147:         } else if (!hibernateOrmConfig.namedPersistenceUnits().isEmpty()) {
1148:             throw new ConfigurationException(
1149:                     "Multiple persistence units are defined but the entities are not mapped to them. You should either use the .packages Quarkus configuration property or package-level @PersistenceUnit annotations.");
1150:         } else {
1151:             // No .packages configuration, no package-level persistence unit annotations,
1152:             // and no named persistence units: all the entities will be associated with the default one
1153:             // so we don't need to split them
1154:             Set<String> allModelClassesAndPackages = new HashSet<>(jpaModel.getAllModelClassNames());
1155:             allModelClassesAndPackages.addAll(jpaModel.getAllModelPackageNames());
1156:             return Collections.singletonMap(PersistenceUnitUtil.DEFAULT_PERSISTENCE_UNIT_NAME, allModelClassesAndPackages);
1157:         }
1158: 
1159:         Set<String> modelClassesWithPersistenceUnitAnnotations = new TreeSet<>();
1160: 
1161:         for (String modelClassName : jpaModel.getAllModelClassNames()) {
1162:             ClassInfo modelClassInfo = index.getClassByName(DotName.createSimple(modelClassName));
1163:             Set<String> relatedModelClassNames = getRelatedModelClassNames(index, jpaModel.getAllModelClassNames(),
1164:                     modelClassInfo);
1165: 
1166:             if (modelClassInfo != null && (modelClassInfo.declaredAnnotation(ClassNames.QUARKUS_PERSISTENCE_UNIT) != null
1167:                     || modelClassInfo.declaredAnnotation(ClassNames.QUARKUS_PERSISTENCE_UNIT_REPEATABLE_CONTAINER) != null)) {
1168:                 modelClassesWithPersistenceUnitAnnotations.add(modelClassInfo.name().toString());
1169:             }
1170: 
1171:             for (Entry<String, Set<String>> packageRuleEntry : packageRules.entrySet()) {
1172:                 if (modelClassName.startsWith(packageRuleEntry.getKey())) {
1173:                     for (String persistenceUnitName : packageRuleEntry.getValue()) {
1174:                         modelClassesAndPackagesPerPersistenceUnits.putIfAbsent(persistenceUnitName, new HashSet<>());
1175:                         modelClassesAndPackagesPerPersistenceUnits.get(persistenceUnitName).add(modelClassName);
1176: 
1177:                         // also add the hierarchy to the persistence unit
1178:                         // we would need to add all the underlying model to it but adding the hierarchy
1179:                         // is necessary for Panache as we need to add PanacheEntity to the PU
1180:                         for (String relatedModelClassName : relatedModelClassNames) {
1181:                             modelClassesAndPackagesPerPersistenceUnits.get(persistenceUnitName).add(relatedModelClassName);
1182:                         }
1183:                     }
1184:                 }
1185:             }
1186:         }
1187: 
