684:     @BuildStep
685:     @Record(RUNTIME_INIT)
686:     public void multitenancy(HibernateOrmRecorder recorder,
687:             List<PersistenceUnitDescriptorBuildItem> persistenceUnitDescriptors,
688:             BuildProducer<SyntheticBeanBuildItem> syntheticBeans,
689:             BuildProducer<UnremovableBeanBuildItem> unremovableBeans) {
690:         boolean multitenancyEnabled = false;
691: 
692:         for (PersistenceUnitDescriptorBuildItem persistenceUnitDescriptor : persistenceUnitDescriptors) {
693:             String persistenceUnitConfigName = persistenceUnitDescriptor.getConfigurationName();
694:             var multitenancyStrategy = persistenceUnitDescriptor.getConfig().getMultiTenancyStrategy();
695:             switch (multitenancyStrategy) {
696:                 case NONE -> {
697:                 }
698:                 case DISCRIMINATOR -> multitenancyEnabled = true;
699:                 case DATABASE, SCHEMA -> {
700:                     multitenancyEnabled = true;
701: 
702:                     String multiTenancySchemaDataSource = persistenceUnitDescriptor.getMultiTenancySchemaDataSource();
703:                     Optional<String> datasource;
704:                     if (multitenancyStrategy == MultiTenancyStrategy.SCHEMA && multiTenancySchemaDataSource != null) {
705:                         LOG.warnf("Configuration property '%1$s' is deprecated. Use '%2$s' instead.",
706:                                 HibernateOrmRuntimeConfig.puPropertyKey(persistenceUnitConfigName,
707:                                         "multitenant-schema-datasource"),
708:                                 HibernateOrmRuntimeConfig.puPropertyKey(persistenceUnitConfigName, "datasource"));
709:                         datasource = Optional.of(multiTenancySchemaDataSource);
