711:                         datasource = persistenceUnitDescriptor.getConfig().getDataSource();
712:                     }
713: 
714:                     ExtendedBeanConfigurator configurator = SyntheticBeanBuildItem
715:                             .configure(DataSourceTenantConnectionResolver.class)
716:                             .scope(ApplicationScoped.class)
717:                             .types(TenantConnectionResolver.class)
718:                             .setRuntimeInit()
719:                             .defaultBean()
720:                             .unremovable()
