797:     private void handleHibernateORMWithNoPersistenceXml(
798:             HibernateOrmConfig hibernateOrmConfig,
799:             CombinedIndexBuildItem index,
800:             List<PersistenceXmlDescriptorBuildItem> descriptors,
801:             List<JdbcDataSourceBuildItem> jdbcDataSources,
802:             ApplicationArchivesBuildItem applicationArchivesBuildItem,
803:             LaunchMode launchMode,
804:             JpaModelBuildItem jpaModel,
805:             Capabilities capabilities,
806:             BuildProducer<SystemPropertyBuildItem> systemProperties,
807:             BuildProducer<NativeImageResourceBuildItem> nativeImageResources,
808:             BuildProducer<HotDeploymentWatchedFileBuildItem> hotDeploymentWatchedFiles,
809:             BuildProducer<PersistenceUnitDescriptorBuildItem> persistenceUnitDescriptors,
810:             BuildProducer<ReflectiveMethodBuildItem> reflectiveMethods,
811:             BuildProducer<UnremovableBeanBuildItem> unremovableBeans,
812:             List<DatabaseKindDialectBuildItem> dbKindMetadataBuildItems) {
813:         if (!descriptors.isEmpty()) {
814:             if (hibernateOrmConfig.isAnyNonPersistenceXmlPropertySet()) {
815:                 throw new ConfigurationException(
816:                         "A legacy persistence.xml file is present in the classpath, but Hibernate ORM is also configured through the Quarkus config file.\n"
817:                                 + "Legacy persistence.xml files and Quarkus configuration cannot be used at the same time.\n"
818:                                 + "To ignore persistence.xml files, set the configuration property"
819:                                 + " 'quarkus.hibernate-orm.persistence-xml.ignore' to 'true'.\n"
820:                                 + "To use persistence.xml files, remove all '" + HIBERNATE_ORM_CONFIG_PREFIX
821:                                 + "*' properties from the Quarkus config file.");
822:             } else {
823:                 // It's theoretically possible to use the Quarkus Hibernate ORM extension
824:                 // without setting any build-time configuration property,
825:                 // so the condition above might not catch all attempts to use persistence.xml and Quarkus-configured PUs
826:                 // at the same time.
827:                 // At that point, the only thing we can do is log something,
828:                 // so that hopefully people in that situation will notice that their Quarkus configuration is being ignored.
829:                 LOG.infof(
830:                         "A legacy persistence.xml file is present in the classpath. This file will be used to configure JPA/Hibernate ORM persistence units,"
831:                                 + " and any configuration of the Hibernate ORM extension will be ignored."
832:                                 + " To ignore persistence.xml files instead, set the configuration property"
833:                                 + " 'quarkus.hibernate-orm.persistence-xml.ignore' to 'true'.");
834:                 return;
835:             }
836:         }
837: 
838:         if (!hibernateOrmConfig.blocking()) {
839:             LOG.infof(
840:                     "Hibernate ORM was disabled explicitly by quarkus.hibernate-orm.blocking=false");
841:             return;
842:         }
843: 
844:         Optional<JdbcDataSourceBuildItem> defaultJdbcDataSource = jdbcDataSources.stream()
845:                 .filter(i -> i.isDefault())
846:                 .findFirst();
847:         boolean enableDefaultPersistenceUnit = (defaultJdbcDataSource.isPresent()
848:                 && hibernateOrmConfig.namedPersistenceUnits().isEmpty())
849:                 || hibernateOrmConfig.defaultPersistenceUnit().isAnyPropertySet();
850: 
851:         Map<String, Set<String>> modelClassesAndPackagesPerPersistencesUnits = getModelClassesAndPackagesPerPersistenceUnits(
852:                 hibernateOrmConfig, jpaModel, index.getIndex(), enableDefaultPersistenceUnit);
853:         Set<String> modelClassesAndPackagesForDefaultPersistenceUnit = modelClassesAndPackagesPerPersistencesUnits
854:                 .getOrDefault(PersistenceUnitUtil.DEFAULT_PERSISTENCE_UNIT_NAME, Collections.emptySet());
855: 
856:         Set<String> storageEngineCollector = new HashSet<>();
857: 
858:         if (enableDefaultPersistenceUnit) {
859:             producePersistenceUnitDescriptorFromConfig(
860:                     hibernateOrmConfig, PersistenceUnitUtil.DEFAULT_PERSISTENCE_UNIT_NAME,
861:                     hibernateOrmConfig.defaultPersistenceUnit(),
862:                     modelClassesAndPackagesForDefaultPersistenceUnit,
863:                     jpaModel.getXmlMappings(PersistenceUnitUtil.DEFAULT_PERSISTENCE_UNIT_NAME),
864:                     jdbcDataSources, applicationArchivesBuildItem, launchMode, capabilities,
865:                     systemProperties, nativeImageResources, hotDeploymentWatchedFiles, persistenceUnitDescriptors,
866:                     reflectiveMethods, unremovableBeans, storageEngineCollector, dbKindMetadataBuildItems);
867:         } else if (!modelClassesAndPackagesForDefaultPersistenceUnit.isEmpty()
868:                 && (!hibernateOrmConfig.defaultPersistenceUnit().datasource().isPresent()
869:                         || DataSourceUtil.isDefault(hibernateOrmConfig.defaultPersistenceUnit().datasource().get()))
870:                 && !defaultJdbcDataSource.isPresent()) {
871:             String persistenceUnitName = PersistenceUnitUtil.DEFAULT_PERSISTENCE_UNIT_NAME;
872:             String dataSourceName = DataSourceUtil.DEFAULT_DATASOURCE_NAME;
873:             throw PersistenceUnitUtil.unableToFindDataSource(persistenceUnitName, dataSourceName,
874:                     DataSourceUtil.dataSourceNotConfigured(dataSourceName));
875:         }
876: 
877:         for (Entry<String, HibernateOrmConfigPersistenceUnit> persistenceUnitEntry : hibernateOrmConfig.namedPersistenceUnits()
878:                 .entrySet()) {
879:             producePersistenceUnitDescriptorFromConfig(
880:                     hibernateOrmConfig, persistenceUnitEntry.getKey(), persistenceUnitEntry.getValue(),
881:                     modelClassesAndPackagesPerPersistencesUnits.getOrDefault(persistenceUnitEntry.getKey(),
882:                             Collections.emptySet()),
883:                     jpaModel.getXmlMappings(persistenceUnitEntry.getKey()),
884:                     jdbcDataSources, applicationArchivesBuildItem, launchMode, capabilities,
885:                     systemProperties, nativeImageResources, hotDeploymentWatchedFiles, persistenceUnitDescriptors,
886:                     reflectiveMethods, unremovableBeans, storageEngineCollector, dbKindMetadataBuildItems);
887:         }
888: 
889:         if (storageEngineCollector.size() > 1) {
890:             throw new ConfigurationException(
891:                     "The dialect storage engine is a global configuration property: it must be consistent across all persistence units.");
892:         }
893:     }
