972:             List<DatabaseKindDialectBuildItem> dbKindMetadataBuildItems,
973:             Optional<JdbcDataSourceBuildItem> jdbcDataSource,
974:             MultiTenancyStrategy multiTenancyStrategy,
975:             BuildProducer<SystemPropertyBuildItem> systemProperties,
976:             BuildProducer<ReflectiveMethodBuildItem> reflectiveMethods,
977:             BiConsumer<String, String> puPropertiesCollector,
