990: 
991:         setDialectAndStorageEngine(
992:                 persistenceUnitName,
993:                 dbKind,
994:                 dialect,
995:                 explicitDbMinVersion,
996:                 dbKindMetadataBuildItems,
997:                 persistenceUnitConfig.dialect().storageEngine(),
998:                 systemProperties,
999:                 puPropertiesCollector,
1000:                 storageEngineCollector);
1001: 
1002:         if ((dbKind.isPresent() && DatabaseKind.isPostgreSQL(dbKind.get())
1003:                 || (dialect.isPresent() && dialect.get().toLowerCase(Locale.ROOT).contains("postgres")))) {
1004:             // Workaround for https://hibernate.atlassian.net/browse/HHH-19063
