1426:     private boolean isModified(String entity, Set<String> changedClasses, IndexView index) {
1427:         if (changedClasses.contains(entity)) {
1428:             return true;
1429:         }
1430:         ClassInfo clazz = index.getClassByName(DotName.createSimple(entity));
1431:         if (clazz == null) {
1432:             //if it is not in the index, then it has not been modified
1433:             return false;
1434:         }
1435:         for (DotName i : clazz.interfaceNames()) {
1436:             if (isModified(i.toString(), changedClasses, index)) {
1437:                 return true;
1438:             }
1439:         }
1440:         DotName superName = clazz.superName();
1441:         if (superName != null) {
1442:             return isModified(superName.toString(), changedClasses, index);
1443:         }
1444:         return false;
1445:     }
