303: 	// TODO doesn't look correct
304: 	@SuppressWarnings("unchecked")
305: 	public boolean setPreference(String key, Object value, ApplicationMode mode) {
306: 		OsmandPreference<?> preference = registeredPreferences.get(key);
307: 		if (preference == null) {
308: 			return false;
309: 		}
310: 		if (preference == APPLICATION_MODE) {
311: 			if (value instanceof String appModeKey) {
312: 				ApplicationMode appMode = ApplicationMode.valueOfStringKey(appModeKey, null);
313: 				if (appMode != null) {
314: 					return setApplicationMode(appMode);
315: 				}
316: 			}
317: 		} else if (preference == DEFAULT_APPLICATION_MODE) {
318: 			if (value instanceof String appModeKey) {
319: 				ApplicationMode appMode = ApplicationMode.valueOfStringKey(appModeKey, null);
320: 				if (appMode != null) {
321: 					return DEFAULT_APPLICATION_MODE.set(appMode);
322: 				}
323: 			}
324: 		} else if (preference instanceof EnumStringPreference enumPref) {
325: 			if (value instanceof String) {
326: 				Enum<?> enumValue = enumPref.parseString((String) value);
327: 				if (enumValue != null) {
328: 					return enumPref.setModeValue(mode, enumValue);
329: 				}
330: 				return false;
331: 			} else if (value instanceof Enum) {
332: 				return enumPref.setModeValue(mode, value);
333: 			} else if (value instanceof Integer) {
334: 				int newVal = (Integer) value;
335: 				if (newVal >= 0 && newVal < enumPref.getValues().length) {
336: 					Enum<?> enumValue = enumPref.getValues()[newVal];
337: 					return enumPref.setModeValue(mode, enumValue);
338: 				}
339: 				return false;
340: 			}
341: 		} else if (preference instanceof ListStringPreference listStringPreference) {
342: 			if (value instanceof List<?> || (value == null && listStringPreference.isNullSupported(mode))) {
343: 				if (value == null) {
344: 					listStringPreference.setStringsListForProfile(mode, null);
345: 				} else {
346: 					List<?> list = (List<?>) value;
347: 					boolean isListOfString = list.stream().allMatch(element -> element instanceof String);
348: 					if (isListOfString) {
349: 						List<String> listOfString = (List<String>) list;
350: 						listStringPreference.setStringsListForProfile(mode, listOfString);
351: 					}
352: 				}
353: 			}
354: 			if (value instanceof String) {
355: 				return listStringPreference.setModeValue(mode, (String) value);
356: 			}
357: 		} else if (preference instanceof StringPreference stringPref) {
358: 			if (value instanceof String || (value == null && stringPref.isNullSupported(mode))) {
359: 				return stringPref.setModeValue(mode, (String) value);
360: 			}
361: 		} else {
362: 			if (value instanceof String) {
363: 				value = preference.parseString((String) value);
364: 			}
365: 			if (preference instanceof BooleanPreference) {
366: 				if (value instanceof Boolean) {
367: 					return ((BooleanPreference) preference).setModeValue(mode, (Boolean) value);
368: 				}
369: 			} else if (preference instanceof FloatPreference) {
370: 				if (value instanceof Float) {
371: 					return ((FloatPreference) preference).setModeValue(mode, (Float) value);
372: 				}
373: 			} else if (preference instanceof IntPreference) {
374: 				if (value instanceof Integer) {
375: 					return ((IntPreference) preference).setModeValue(mode, (Integer) value);
376: 				}
377: 			} else if (preference instanceof LongPreference) {
378: 				if (value instanceof Long) {
379: 					return ((LongPreference) preference).setModeValue(mode, (Long) value);
380: 				}
381: 			} else if (preference instanceof ContextMenuItemsPreference) {
382: 				if (value instanceof ContextMenuItemsSettings) {
383: 					return ((ContextMenuItemsPreference) preference).setModeValue(mode, (ContextMenuItemsSettings) value);
384: 				}
385: 			}
386: 		}
387: 		return false;
388: 	}
