478: 		ApplicationMode nextAppMode = getSwitchedAppMode(appMode, next);
479: 		if (appMode != nextAppMode && setApplicationMode(nextAppMode)) {
480: 			String pattern = ctx.getString(R.string.application_profile_changed);
481: 			String message = String.format(pattern, nextAppMode.toHumanString());
482: 			ctx.showShortToastMessage(message);
483: 			return true;
484: 		}
485: 		return false;
486: 	}
