488: 	public ApplicationMode getSwitchedAppMode(ApplicationMode selectedMode, boolean next) {
489: 		List<ApplicationMode> enabledModes = ApplicationMode.values(ctx);
490: 		int indexOfCurrent = enabledModes.indexOf(selectedMode);
491: 		int indexOfNext;
492: 		if (next) {
493: 			indexOfNext = indexOfCurrent < enabledModes.size() - 1 ? indexOfCurrent + 1 : 0;
494: 		} else {
495: 			indexOfNext = indexOfCurrent > 0 ? indexOfCurrent - 1 : enabledModes.size() - 1;
496: 		}
497: 		return enabledModes.get(indexOfNext);
498: 	}
