651: 		try {
652: 			ConnectivityManager mgr = (ConnectivityManager) ctx.getSystemService(Context.CONNECTIVITY_SERVICE);
653: 			NetworkInfo ni = mgr.getActiveNetworkInfo();
654: 			return ni != null && ni.getType() == ConnectivityManager.TYPE_WIFI;
655: 		} catch (Exception e) {
656: 			return false;
657: 		}
658: 	}
