660: 	private boolean isInternetConnected() {
661: 		try {
662: 			ConnectivityManager mgr = (ConnectivityManager) ctx.getSystemService(Context.CONNECTIVITY_SERVICE);
663: 			NetworkInfo active = mgr.getActiveNetworkInfo();
664: 			if (active == null) {
665: 				return false;
666: 			} else {
667: 				NetworkInfo.State state = active.getState();
668: 				return state != NetworkInfo.State.DISCONNECTED && state != NetworkInfo.State.DISCONNECTING;
669: 			}
670: 		} catch (Exception e) {
671: 			return false;
672: 		}
673: 	}
