889: 	public boolean enablePlugin(String pluginId, boolean enable) {
890: 		Set<String> set = getPlugins();
891: 		if (enable) {
892: 			set.remove("-" + pluginId);
893: 			set.add(pluginId);
894: 		} else {
895: 			set.remove(pluginId);
896: 			set.add("-" + pluginId);
897: 		}
898: 		StringBuilder serialization = new StringBuilder();
899: 		Iterator<String> it = set.iterator();
900: 		while (it.hasNext()) {
901: 			serialization.append(it.next());
902: 			if (it.hasNext()) {
903: 				serialization.append(",");
904: 			}
905: 		}
906: 		if (!serialization.toString().equals(PLUGINS.get())) {
907: 			return PLUGINS.set(serialization.toString());
908: 		}
909: 		return false;
910: 	}
