2153: 	@Nullable
2154: 	public ITileSource getTileSourceByName(String tileName, boolean warnWhenSelected) {
2155: 		if (tileName == null || tileName.length() == 0) {
2156: 			return null;
2157: 		}
2158: 		List<TileSourceTemplate> knownTemplates = TileSourceManager.getKnownSourceTemplates();
2159: 		File tPath = ctx.getAppPath(IndexConstants.TILES_INDEX_DIR);
2160: 		File dir = new File(tPath, tileName);
2161: 		if (!dir.exists()) {
2162: 			return checkAmongAvailableTileSources(dir, knownTemplates);
2163: 		} else if (tileName.endsWith(SQLITE_EXT)) {
2164: 			return new SQLiteTileSource(ctx, dir, knownTemplates);
2165: 		} else if (dir.isDirectory() && !dir.getName().startsWith(".")) {
2166: 			TileSourceTemplate t = TileSourceManager.createTileSourceTemplate(dir);
2167: 			if (warnWhenSelected && !t.isRuleAcceptable()) {
2168: 				ctx.showToastMessage(R.string.warning_tile_layer_not_downloadable, dir.getName());
2169: 			}
2170: 			if (!TileSourceManager.isTileSourceMetaInfoExist(dir)) {
2171: 				TileSourceTemplate ret = checkAmongAvailableTileSources(dir, knownTemplates);
2172: 				if (ret != null) {
2173: 					t = ret;
2174: 				}
2175: 			}
2176: 			return t;
2177: 		}
2178: 		return null;
2179: 	}
