2053: 		StringBuilder builder = new StringBuilder();
2054: 
2055: 		Iterator<String> iterator = pages.iterator();
2056: 		while (iterator.hasNext()) {
2057: 			boolean pageSeparatorAdded = false;
2058: 			String page = iterator.next();
2059: 			for (String id : page.split(WIDGET_SEPARATOR)) {
2060: 				if (WidgetType.isComplexWidget(id)) {
2061: 					pageSeparatorAdded = true;
2062: 					builder.append(id).append(PAGE_SEPARATOR);
2063: 				} else {
2064: 					pageSeparatorAdded = false;
2065: 					builder.append(id).append(WIDGET_SEPARATOR);
2066: 				}
2067: 			}
2068: 			if (iterator.hasNext() && !pageSeparatorAdded) {
2069: 				builder.append(PAGE_SEPARATOR);
2070: 			}
2071: 		}
2072: 		return builder.toString();
2073: 	}
