570: 	@NonNull
571: 	@Override
572: 	public synchronized Map<TravelSearchResult, List<TravelSearchResult>> getNavigationMap(@NonNull TravelArticle article) {
573: 		String lang = article.getLang();
574: 		String title = article.getTitle();
575: 		if (TextUtils.isEmpty(lang) || TextUtils.isEmpty(title)) {
576: 			return Collections.emptyMap();
577: 		}
578: 		String[] parts;
579: 		if (!TextUtils.isEmpty(article.getAggregatedPartOf())) {
580: 			String[] originalParts = article.getAggregatedPartOf().split(",");
581: 			if (originalParts.length > 1) {
582: 				parts = new String[originalParts.length];
583: 				for (int i = 0; i < originalParts.length; i++) {
584: 					parts[i] = originalParts[originalParts.length - i - 1];
585: 				}
586: 			} else {
587: 				parts = originalParts;
588: 			}
589: 		} else {
590: 			parts = null;
591: 		}
592: 		Map<String, List<TravelSearchResult>> navMap = new HashMap<>();
593: 		Set<String> headers = new LinkedHashSet<>();
594: 		Map<String, TravelSearchResult> headerObjs = new HashMap<>();
595: 		if (parts != null && parts.length > 0) {
596: 			headers.addAll(Arrays.asList(parts));
597: 			if (!Algorithms.isEmpty(article.isParentOf)) {
598: 				headers.add(title);
599: 			}
600: 		}
601: 
602: 		for (String header : headers) {
603: 			String parentLang = header.startsWith("en:") ? "en" : lang;
604: 			header = WikivoyageUtils.getTitleWithoutPrefix(header);
605: 			TravelArticle parentArticle = getParentArticleByTitle(header, parentLang);
606: 			if (parentArticle == null) {
607: 				continue;
608: 			}
609: 			navMap.put(header, new ArrayList<>());
610: 			String[] isParentOf = parentArticle.isParentOf.split(";");
611: 			for (String childTitle : isParentOf) {
612: 				if (!childTitle.isEmpty()) {
613: 					TravelSearchResult searchResult = new TravelSearchResult("", childTitle, null,
614: 							null, Collections.singletonList(parentLang));
615: 					List<TravelSearchResult> resultList = navMap.computeIfAbsent(header, k -> new ArrayList<>());
616: 					resultList.add(searchResult);
617: 					if (headers.contains(childTitle)) {
618: 						headerObjs.put(childTitle, searchResult);
619: 					}
620: 				}
621: 			}
622: 		}
623: 
624: 		Map<TravelSearchResult, List<TravelSearchResult>> res = new LinkedHashMap<>();
625: 		for (String header : headers) {
626: 			String parentLang = header.startsWith("en:") ? "en" : lang;
627: 			header = WikivoyageUtils.getTitleWithoutPrefix(header);
628: 			TravelSearchResult searchResult = headerObjs.get(header);
629: 			List<TravelSearchResult> results = navMap.get(header);
630: 			if (results != null) {
631: 				sortSearchResults(results, header);
632: 				TravelSearchResult emptyResult = new TravelSearchResult("", header, null,
633: 						null, Collections.singletonList(parentLang));
634: 				searchResult = searchResult != null ? searchResult : emptyResult;
635: 				res.put(searchResult, results);
636: 			}
637: 		}
638: 		return res;
639: 	}
