406: 	@NonNull
407: 	private synchronized List<TravelSearchResult> searchWithLang(@NonNull String searchQuery, @NonNull String appLang, int reqNumber) {
408: 		List<TravelSearchResult> res = new ArrayList<>();
409: 		Map<File, List<Amenity>> amenityMap = new HashMap<>();
410: 		SearchUICore searchUICore = app.getSearchUICore().getCore();
411: 		SearchSettings settings = searchUICore.getSearchSettings();
412: 		SearchPhrase phrase = searchUICore.getPhrase().generateNewPhrase(searchQuery, settings);
413: 		NameStringMatcher matcher = phrase.getFirstUnknownNameStringMatcher();
414: 		List<TravelSearchResult> empty = new ArrayList<>();
415: 
416: 		for (AmenityIndexRepository repo : getTravelRepositories()) {
417: 			if (requestNumber != reqNumber) {
418: 				return empty;
419: 			}
420: 			List<BinaryMapPoiReaderAdapter.PoiRegion> poiIndexes = repo.getReaderPoiIndexes();
421: 			QuadRect bbox = new QuadRect();
422: 			for (BinaryMapPoiReaderAdapter.PoiRegion poiRegion : poiIndexes) {
423: 				bbox.expand(poiRegion.getLeft31(), poiRegion.getTop31(), poiRegion.getRight31(), poiRegion.getBottom31());
424: 			}
425: 			SearchRequest<Amenity> searchRequest = BinaryMapIndexReader.buildSearchPoiRequest(0, 0, searchQuery,
426: 					(int) bbox.left, (int) bbox.right, (int) bbox.top, (int) bbox.bottom, getSearchFilter(ROUTE_ARTICLE), new ResultMatcher<Amenity>() {
427: 						@Override
428: 						public boolean publish(Amenity object) {
429: 							List<String> otherNames = object.getOtherNames(false);
430: 							String localeName = object.getName(appLang);
431: 							return matcher.matches(localeName) || matcher.matches(otherNames);
432: 						}
433: 
434: 						@Override
435: 						public boolean isCancelled() {
436: 							return requestNumber != reqNumber;
437: 						}
438: 					}, null);
439: 
440: 			List<Amenity> amenities = repo.searchPoiByName(searchRequest);
441: 			if (requestNumber != reqNumber) {
442: 				return empty;
443: 			}
444: 			if (!Algorithms.isEmpty(amenities)) {
445: 				amenityMap.put(repo.getFile(), amenities);
446: 			}
447: 		}
448: 		if (!Algorithms.isEmpty(amenityMap)) {
449: 			boolean appLangEn = "en".equals(appLang);
450: 			TLongSet uniqueIds = new TLongHashSet();
451: 			for (Entry<File, List<Amenity>> entry : amenityMap.entrySet()) {
452: 				File file = entry.getKey();
453: 				for (Amenity amenity : entry.getValue()) {
454: 					long routeId = Algorithms.parseLongSilently(amenity.getRouteId().replace("Q", ""), -1);
455: 					if (!uniqueIds.add(routeId)) {
456: 						continue;
457: 					}
458: 					Set<String> nameLangs = getLanguages(amenity);
459: 					if (nameLangs.contains(appLang) || Algorithms.isEmpty(appLang)) {
460: 						TravelArticle article = readArticle(file, amenity, appLang);
461: 						ArrayList<String> langs = new ArrayList<>(nameLangs);
462: 						Collections.sort(langs, (l1, l2) -> {
463: 							if (l1.equals(appLang)) {
464: 								l1 = "1";
465: 							}
466: 							if (l2.equals(appLang)) {
467: 								l2 = "1";
468: 							}
469: 							if (!appLangEn) {
470: 								if (l1.equals("en")) {
471: 									l1 = "2";
472: 								}
473: 								if (l2.equals("en")) {
474: 									l2 = "2";
475: 								}
476: 							}
477: 							return l1.compareTo(l2);
478: 						});
479: 						TravelSearchResult r = new TravelSearchResult(article, langs);
480: 						res.add(r);
481: 					}
482: 				}
483: 			}
484: 			sortSearchResults(res, searchQuery);
485: 		}
486: 		return res;
487: 	}
