489: 	@NonNull
490: 	private Set<String> getLanguages(@NonNull Amenity amenity) {
491: 		Set<String> langs = new HashSet<>();
492: 		String descrStart = Amenity.DESCRIPTION + ":";
493: 		String partStart = Amenity.IS_PART + ":";
494: 		for (String infoTag : amenity.getAdditionalInfoKeys()) {
495: 			if (infoTag.startsWith(descrStart)) {
496: 				if (infoTag.length() > descrStart.length()) {
497: 					langs.add(infoTag.substring(descrStart.length()));
498: 				}
499: 			} else if (infoTag.startsWith(partStart)) {
500: 				if (infoTag.length() > partStart.length()) {
501: 					langs.add(infoTag.substring(partStart.length()));
502: 				}
503: 			}
504: 		}
505: 		return langs;
506: 	}
