508: 	private void sortSearchResults(@NonNull List<TravelSearchResult> results, @NonNull String searchQuery) {
509: 		results.sort(new SearchResultComparator(searchQuery, collator));
510: 	}
511: 
512: 	private static class SearchResultComparator implements Comparator<TravelSearchResult> {
513: 		private final Collator collator;
514: 		private final String searchQuery;
515: 		private final String searchQueryLC;
516: 
517: 
518: 		public SearchResultComparator(@NonNull String searchQuery, @NonNull Collator collator) {
519: 			this.searchQuery = searchQuery;
520: 			this.collator = collator;
521: 			searchQueryLC = searchQuery.toLowerCase();
522: 		}
523: 
524: 		@Override
525: 		public int compare(@NonNull TravelSearchResult sr1, @NonNull TravelSearchResult sr2) {
526: 			for (ResultCompareStep step : ResultCompareStep.values()) {
527: 				int res = step.compare(sr1, sr2, this);
528: 				if (res != 0) {
529: 					return res;
530: 				}
531: 			}
532: 			return 0;
533: 		}
534: 
535: 	}
536: 
537: 	private enum ResultCompareStep {
538: 		MACH_TITLE,
539: 		CONTAINS_OF_TITLE,
540: 		OTHER;
541: 
542: 		// -1 - means 1st is less (higher list position) than 2nd
543: 		public int compare(@NonNull TravelSearchResult sr1, @NonNull TravelSearchResult sr2,
544: 						   @NonNull SearchResultComparator c) {
545: 			String articleTitle1 = sr1.getArticleTitle();
546: 			String articleTitle2 = sr2.getArticleTitle();
547: 			boolean sr1Comparison = !c.collator.equals(articleTitle1, c.searchQuery.trim());
548: 			boolean sr2Comparison = !c.collator.equals(articleTitle2, c.searchQuery.trim());
549: 			switch (this) {
550: 				case MACH_TITLE:
551: 					return Boolean.compare(sr1Comparison, sr2Comparison);
552: 				case CONTAINS_OF_TITLE:
553: 					boolean title1contains = articleTitle1.toLowerCase().contains(c.searchQueryLC);
554: 					boolean title2contains = articleTitle2.toLowerCase().contains(c.searchQueryLC);
555: 					return -Boolean.compare(title1contains, title2contains);
556: 				case OTHER:
557: 					int comp = c.collator.compare(articleTitle1, articleTitle2);
558: 					return (comp != 0) ? comp : c.collator.compare(sr1.isPartOf, sr2.isPartOf);
559: 			}
560: 			return 0;
561: 		}
562: 	}
