662: 	private void startLoadingImagesTask() {
663: 		if (galleryController == null) {
664: 			return;
665: 		}
666: 
667: 		onlinePhotoCards = new ArrayList<>();
668: 		LatLon latLon = getLatLon();
669: 		Map<String, String> params = getAdditionalCardParams();
670: 
671: 		PhotoCacheManager cacheManager = new PhotoCacheManager(app);
672: 		WikiHelper.WikiTagData wikiTagData = WikiHelper.INSTANCE.extractWikiTagData(params);
673: 		String wikidataId = wikiTagData.getWikidataId();
674: 		String wikiCategory = wikiTagData.getWikiCategory();
675: 		String wikiTitle = wikiTagData.getWikiTitle();
676: 		String rawKey = PhotoCacheManager.buildRawKey(wikidataId, wikiCategory, wikiTitle);
677: 
678: 		if (galleryController.isCurrentHolderEquals(latLon, params)) {
679: 			imageCardListener.onFinish(galleryController.getCurrentCardsHolder());
680: 		} else if(!app.getSettings().hasInternetConnection()){
681: 			loadFromCache(cacheManager, rawKey, params, wikiTagData, latLon);
682: 		} else {
683: 			stopLoadingImagesTask();
684: 			galleryController.clearHolder();
685: 			getImageCardsTask = new GetImageCardsTask(mapActivity, getLatLon(),
686: 					getAdditionalCardParams(), imageCardListener,
687: 					response -> savePhotoListToCache(cacheManager, rawKey, response));
688: 			execute(getImageCardsTask);
689: 		}
690: 	}
