692: 	private void savePhotoListToCache(@NonNull PhotoCacheManager cacheManager, @NonNull String rawKey, @NonNull String response){
693: 		if (!Algorithms.hasRouteId(response)) {
694: 			CacheWriteTask cacheWriteTask = new CacheWriteTask(cacheManager, rawKey, response);
695: 			execute(cacheWriteTask);
696: 		}
697: 	}
