699: 	private void loadFromCache(@NonNull PhotoCacheManager cacheManager, @NonNull String rawKey,
700: 	                           @NonNull Map<String, String> params, @NonNull WikiHelper.WikiTagData wikiTagData,
701: 	                           @NonNull LatLon latLon){
702: 		if (cacheManager.exists(rawKey)) {
703: 			imageCardListener.onTaskStarted();
704: 			CacheReadTask cacheReadTask = new CacheReadTask(cacheManager, rawKey, json -> {
705: 				if (!Algorithms.hasRouteId(json)) {
706: 					ImageCardsHolder holder = new ImageCardsHolder(latLon, params);
707: 					List<WikiImage> wikimediaImageList = WikiCoreHelper.getImagesFromJson(json, wikiTagData.getWikiImages());
708: 					for (WikiImage wikiImage : wikimediaImageList) {
709: 						holder.addCard(WIKIMEDIA, new WikiImageCard(mapActivity, wikiImage));
710: 					}
711: 					imageCardListener.onFinish(holder);
712: 				} else {
713: 					imageCardListener.onFinish(null);
