1120: 			AlertDialog.Builder dlg = new AlertDialog.Builder(context);
1121: 			dlg.setNegativeButton(R.string.shared_string_cancel, null);
1122: 			dlg.setItems(items, (dialog, which) -> {
1123: 				intent.setData(Uri.parse(dataPrefix + items[which]));
1124: 				AndroidUtils.startActivityIfSafe(context, intent);
