1141: 	protected CollapsableView getLocationCollapsableView(Map<Integer, String> locationData) {
1142: 		LinearLayout llv = buildCollapsableContentView(mapActivity, true, true);
1143: 		for (Map.Entry<Integer, String> line : locationData.entrySet()) {
1144: 			TextViewEx button = buildButtonInCollapsableView(mapActivity, false, false);
1145: 			SpannableStringBuilder ssb = new SpannableStringBuilder();
1146: 			if (line.getKey() == OsmAndFormatter.UTM_FORMAT) {
1147: 				ssb.append("UTM: ");
1148: 				ssb.setSpan(new ForegroundColorSpan(getColor(R.color.text_color_secondary_light)), 0, 4, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
1149: 			} else if (line.getKey() == OsmAndFormatter.MGRS_FORMAT) {
1150: 				ssb.append("MGRS: ");
1151: 				ssb.setSpan(new ForegroundColorSpan(getColor(R.color.text_color_secondary_light)), 0, 5, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
1152: 			} else if (line.getKey() == OsmAndFormatter.OLC_FORMAT) {
1153: 				ssb.append("OLC: ");
1154: 				ssb.setSpan(new ForegroundColorSpan(getColor(R.color.text_color_secondary_light)), 0, 4, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
