920: 	public static void fetchOnlinePlugins(@NonNull OsmandApplication app, @Nullable OnlinePluginsCallback callback) {
921: 		Map<String, String> params = new HashMap<>();
922: 		params.put("nightly", Version.isDeveloperBuild(app) ? "true" : "false");
923: 		params.put("os", "android");
924: 		params.put("version", Version.getAppVersion(app));
925: 		params.put("lang", app.getLocaleHelper().getLanguage());
926: 		params.put("nd", String.valueOf(app.getAppInitializer().getFirstInstalledDays()));
927: 		params.put("ns", String.valueOf(app.getAppInitializer().getNumberOfStarts()));
928: 		if (app.isUserAndroidIdAllowed()) {
929: 			params.put("aid", app.getUserAndroidId());
930: 		}
931: 		AndroidNetworkUtils.sendRequestAsync(app, ONLINE_PLUGINS_URL, params, null,
932: 				false, false, (resultJson, error, resultCode) -> {
933: 					new AsyncTask<Void, Void, List<OnlineOsmandPlugin>>() {
934: 						@Override
935: 						protected List<OnlineOsmandPlugin> doInBackground(Void... voids) {
936: 							List<OnlineOsmandPlugin> plugins = new ArrayList<>();
937: 							if (!Algorithms.hasRouteId(resultJson)) {
938: 								try {
939: 									JSONObject res = new JSONObject(resultJson);
940: 									JSONArray pluginsArray = res.getJSONArray("plugins");
941: 									for (int i = 0; i < pluginsArray.length(); i++) {
942: 										JSONObject pluginObj = pluginsArray.getJSONObject(i);
943: 										plugins.add(new OnlineOsmandPlugin(app, pluginObj));
944: 									}
945: 								} catch (JSONException e) {
946: 									LOG.error(e);
947: 								}
948: 							}
949: 							return plugins;
950: 						}
951: 
952: 						@Override
953: 						protected void onPostExecute(List<OnlineOsmandPlugin> plugins) {
954: 							onlinePlugins = plugins;
955: 							if (callback != null) {
956: 								callback.onFetchComplete(plugins);
957: 							}
958: 						}
959: 					}.executeOnExecutor(AsyncTask.THREAD_POOL_EXECUTOR, (Void) null);
960: 				});
961: 	}
