152: 	private static void loadCustomPlugins(@NonNull OsmandApplication app) {
153: 		SettingsAPI settingsAPI = app.getSettings().getSettingsAPI();
154: 		Object pluginPrefs = settingsAPI.getPreferenceObject(PLUGINS_PREFERENCES_NAME);
155: 		String customPluginsJson = settingsAPI.getString(pluginPrefs, CUSTOM_PLUGINS_KEY, "");
156: 		if (!Algorithms.hasRouteId(customPluginsJson)) {
157: 			try {
158: 				JSONArray jArray = new JSONArray(customPluginsJson);
159: 				for (int i = 0; i < jArray.length(); i++) {
160: 					JSONObject json = jArray.getJSONObject(i);
161: 					CustomOsmandPlugin plugin = new CustomOsmandPlugin(app, json);
162: 					allPlugins.add(plugin);
163: 				}
164: 			} catch (JSONException e) {
165: 				LOG.error(e);
166: 			}
167: 		}
168: 	}
169: 
170: 	private static void saveCustomPlugins(OsmandApplication app) {
171: 		List<CustomOsmandPlugin> customOsmandPlugins = getCustomPlugins();
172: 		SettingsAPI settingsAPI = app.getSettings().getSettingsAPI();
173: 		Object pluginPrefs = settingsAPI.getPreferenceObject(PLUGINS_PREFERENCES_NAME);
174: 		JSONArray itemsJson = new JSONArray();
175: 		for (CustomOsmandPlugin plugin : customOsmandPlugins) {
176: 			try {
177: 				JSONObject json = new JSONObject();
178: 				json.put("pluginId", plugin.getId());
179: 				json.put("version", plugin.getVersion());
180: 				plugin.writeAdditionalDataToJson(json);
181: 				plugin.writeDependentFilesJson(json);
182: 				itemsJson.put(json);
183: 			} catch (JSONException e) {
184: 				LOG.error(e);
185: 			}
186: 		}
187: 		String jsonStr = itemsJson.toString();
188: 		if (!jsonStr.equals(settingsAPI.getString(pluginPrefs, CUSTOM_PLUGINS_KEY, ""))) {
189: 			settingsAPI.edit(pluginPrefs).putString(CUSTOM_PLUGINS_KEY, jsonStr).commit();
190: 		}
191: 	}
