230: 	private static boolean updateMarketPlugin(@NonNull OsmandApplication app,
231: 	                                          @NonNull OsmandPlugin plugin) {
232: 		boolean marketEnabled = Version.isMarketEnabled();
233: 		boolean available = plugin.isAvailable(app);
234: 		boolean paid = plugin.isPaid();
235: 		boolean processed = false;
236: 		// for test reasons
237: 		//if ((Version.isDeveloperVersion(app) || !Version.isProductionVersion(app)) && !paid) {
238: 		//	marketEnabled = false;
239: 		//}
240: 		if (available || (!marketEnabled && !paid)) {
241: 			plugin.setInstallURL(null);
242: 			processed = true;
243: 		} else if (marketEnabled) {
244: 			plugin.setInstallURL(Version.getUrlWithUtmRef(app, plugin.getComponentId1()));
245: 			processed = true;
246: 		}
247: 		return processed;
248: 	}
