266: 	public static boolean enablePluginIfNeeded(@Nullable Activity activity,
267: 	                                           @NonNull OsmandApplication app,
268: 	                                           @Nullable OsmandPlugin plugin,
269: 	                                           boolean enable) {
270: 		if (plugin != null) {
271: 			boolean stateChanged = enable != plugin.isEnabled();
272: 			boolean canChangeState = !enable || !plugin.isLocked();
273: 			if (stateChanged && canChangeState) {
274: 				return enablePlugin(activity, app, plugin, enable);
275: 			}
276: 		}
277: 		return false;
278: 	}
