280: 	public static boolean enablePlugin(@Nullable Activity activity,
281: 	                                   @NonNull OsmandApplication app,
282: 	                                   @NonNull OsmandPlugin plugin,
283: 	                                   boolean enable) {
284: 		if (enable) {
285: 			if (!plugin.init(app, activity)) {
286: 				plugin.setEnabled(false);
287: 				return false;
288: 			} else {
289: 				plugin.setEnabled(true);
290: 			}
291: 		} else {
292: 			plugin.disable(app);
293: 			plugin.setEnabled(false);
294: 		}
295: 		app.getSettings().enablePlugin(plugin.getId(), enable);
296: 		app.getMapButtonsHelper().updateActionTypes();
297: 		if (activity != null) {
298: 			if (activity instanceof MapActivity) {
299: 				MapActivity mapActivity = (MapActivity) activity;
300: 				plugin.updateLayers(mapActivity, mapActivity);
301: 				MapLayers mapLayers = app.getOsmandMap().getMapLayers();
302: 				mapLayers.getMapInfoLayer().recreateAllControls(mapActivity);
303: 				mapActivity.getDashboard().refreshDashboardFragments();
304: 
305: 				DashFragmentData fragmentData = plugin.getCardFragment();
306: 				if (!enable && fragmentData != null) {
307: 					FragmentManager fm = mapActivity.getSupportFragmentManager();
308: 					Fragment fragment = fm.findFragmentByTag(fragmentData.tag);
309: 					if (fragment != null) {
310: 						fm.beginTransaction().remove(fragment).commitAllowingStateLoss();
311: 					}
312: 				}
313: 			}
314: 
315: 			if (plugin.isMarketPlugin() || plugin.isPaid()) {
316: 				if (plugin.shouldShowInstallDialog()) {
317: 					plugin.showInstallDialog(activity);
318: 				} else if (plugin.shouldShowDisableDialog()) {
319: 					plugin.showDisableDialog(activity);
320: 				}
321: 			}
322: 		}
323: 		return true;
324: 	}
