531: 		changesManager.collectChangesFiles(app.getAppPath(LIVE_INDEX_DIR), BINARY_MAP_INDEX_EXT, files);
532: 
533: 		Collections.sort(files, Algorithms.getFileVersionComparator());
534: 		List<String> warnings = new ArrayList<>();
