540: 				cachedOsmandIndexes.readFromFile(indCache);
541: 			} catch (Exception e) {
542: 				log.error(e.getMessage(), e);
543: 			}
544: 		}
545: 		File liveDir = app.getAppPath(LIVE_INDEX_DIR);
546: 		depthContours = false;
