178: 		DisplayMetrics dm = new DisplayMetrics();
179: 		AndroidUtils.getDisplay(app).getMetrics(dm);
180: 		// Only 8 MB (from 16 Mb whole mem) available for images : image 64K * 128 = 8 MB (8 bit), 64 - 16 bit, 32 - 32 bit
181: 		// at least 3*9?
182: 		float tiles = (dm.widthPixels / 256 + 2) * (dm.heightPixels / 256 + 2) * 3;
183: 		log.info("Bitmap tiles to load in memory : " + tiles);
184: 		bitmapTilesCache.setMaxCacheSize((int) (tiles));
