508: 	public List<String> indexingMaps(@Nullable IProgress progress,
509: 			@NonNull List<File> filesToReindex) {
510: 		long val = System.currentTimeMillis();
511: 		ArrayList<File> files = new ArrayList<>();
512: 		File appPath = app.getAppPath(null);
513: 		File roadsPath = app.getAppPath(ROADS_INDEX_DIR);
514: 		roadsPath.mkdirs();
515: 
516: 		FileUtils.collectFiles(app.getAppInternalPath(HIDDEN_DIR), BINARY_MAP_INDEX_EXT, files);
517: 		FileUtils.collectFiles(appPath, BINARY_MAP_INDEX_EXT, files);
518: 		renameRoadsFiles(files, roadsPath);
519: 		FileUtils.collectFiles(roadsPath, BINARY_MAP_INDEX_EXT, files);
520: 		if (Version.isPaidVersion(app)) {
521: 			FileUtils.collectFiles(app.getAppPath(WIKI_INDEX_DIR), BINARY_MAP_INDEX_EXT, files);
522: 			FileUtils.collectFiles(app.getAppPath(TRAVEL_GUIDE_INDEX_DIR), BINARY_TRAVEL_GUIDE_MAP_INDEX_EXT, files);
523: 		}
524: 		if (PluginsHelper.hasActive(SRTMPlugin.class) || InAppPurchaseUtils.isContourLinesAvailable(app)) {
525: 			FileUtils.collectFiles(app.getAppPath(SRTM_INDEX_DIR), BINARY_MAP_INDEX_EXT, files);
526: 		}
527: 		if (PluginsHelper.hasActive(NauticalMapsPlugin.class) || InAppPurchaseUtils.isDepthContoursAvailable(app)) {
528: 			FileUtils.collectFiles(app.getAppPath(NAUTICAL_INDEX_DIR), BINARY_DEPTH_MAP_INDEX_EXT, files);
529: 		}
530: 
531: 		changesManager.collectChangesFiles(app.getAppPath(LIVE_INDEX_DIR), BINARY_MAP_INDEX_EXT, files);
532: 
533: 		Collections.sort(files, Algorithms.getFileVersionComparator());
534: 		List<String> warnings = new ArrayList<>();
535: 		renderer.clearAllResources();
536: 		CachedOsmandIndexes cachedOsmandIndexes = new CachedOsmandIndexes();
537: 		File indCache = app.getAppPath(INDEXES_CACHE);
538: 		if (indCache.exists()) {
539: 			try {
540: 				cachedOsmandIndexes.readFromFile(indCache);
541: 			} catch (Exception e) {
542: 				log.error(e.getMessage(), e);
543: 			}
544: 		}
545: 		File liveDir = app.getAppPath(LIVE_INDEX_DIR);
546: 		depthContours = false;
547: 		File worldBasemapStd = null;
548: 		File worldBasemapDetailed = null;
549: 		File worldBasemapMini = null;
550: 		for (File f : files) {
551: 			if (f.getName().equals("World_basemap.obf")) {
552: 				worldBasemapStd = f;
553: 			}
554: 			if (f.getName().startsWith("World_basemap_mini")) {
555: 				worldBasemapMini = f;
556: 			}
557: 			if (f.getName().startsWith("World_basemap_detailed")) {
558: 				worldBasemapDetailed = f;
559: 			}
560: 		}
561: 
562: 		if (worldBasemapDetailed != null) {
563: 			if (worldBasemapStd != null) {
564: 				files.remove(worldBasemapStd);
565: 			}
566: 			if (worldBasemapMini != null) {
567: 				files.remove(worldBasemapMini);
568: 			}
569: 
570: 		} else if (worldBasemapStd != null && worldBasemapMini != null) {
571: 			files.remove(worldBasemapMini);
572: 		}
573: 
574: 		DateFormat dateFormat = getDateFormat();
575: 		for (File f : files) {
576: 			String fileName = f.getName();
577: 			if (progress != null) {
578: 				progress.startTask(app.getString(R.string.indexing_map) + " " + fileName, -1);
579: 			}
580: 			try {
581: 				BinaryMapIndexReader mapReader = null;
582: 				boolean reindex = filesToReindex.contains(f);
583: 				try {
584: 					mapReader = cachedOsmandIndexes.getReader(f, !reindex);
585: 					if (mapReader.getVersion() != BINARY_MAP_VERSION) {
586: 						mapReader = null;
587: 					}
588: 				} catch (IOException e) {
589: 					log.error(String.format("File %s could not be read", fileName), e);
590: 				}
591: 				boolean travelGuideMap = WikipediaPlugin.containsTravelGuideExtension(fileName);
592: 				boolean srtmMap = SrtmDownloadItem.containsSrtmExtension(fileName);
593: 				if (mapReader == null || (!Version.isPaidVersion(app) && travelGuideMap)) {
594: 					warnings.add(MessageFormat.format(app.getString(R.string.version_index_is_not_supported), fileName)); //$NON-NLS-1$
595: 				} else {
596: 					if (mapReader.isBasemap()) {
597: 						basemapFileNames.put(fileName, fileName);
598: 					}
599: 					long dateCreated = mapReader.getDateCreated();
600: 					if (dateCreated == 0) {
601: 						dateCreated = f.lastModified();
602: 					}
603: 					if (f.getParentFile().getName().equals(liveDir.getName())) {
604: 						boolean toUse = changesManager.index(f, dateCreated, mapReader);
605: 						if (!toUse) {
606: 							try {
607: 								mapReader.close();
608: 							} catch (IOException e) {
609: 								log.error(e.getMessage(), e);
610: 							}
611: 							continue;
612: 						}
613: 					} else if (!travelGuideMap && !srtmMap) {
614: 						changesManager.indexMainMap(f, dateCreated);
615: 						if (reindex) {
616: 							for (ResourceListener l : resourceListeners) {
617: 								l.onReaderIndexed(mapReader);
618: 							}
619: 						}
620: 					}
621: 					indexFileNames.put(fileName, dateFormat.format(dateCreated));
622: 					indexFiles.put(fileName, f);
623: 					if (!depthContours && fileName.toLowerCase().startsWith("depth_")) {
624: 						depthContours = true;
625: 					}
626: 					renderer.initializeNewResource(f, mapReader);
627: 					BinaryMapReaderResource resource = new BinaryMapReaderResource(f, mapReader);
628: 					boolean hasTravelObf = resource.getFileName().endsWith(BINARY_TRAVEL_GUIDE_MAP_INDEX_EXT);
629: 					if (mapReader.containsPoiData()) {
630: 						AmenityIndexRepositoryBinary amenityResource = new AmenityIndexRepositoryBinary(f, resource, app);
631: 						amenitySearcher.addAmenityRepository(fileName, amenityResource);
632: 						if (hasTravelObf) {
633: 							// reuse until new BinaryMapReaderResourceType.TRAVEL_GPX
634: 							travelRepositories.put(resource.getFileName(), amenityResource);
635: 						}
636: 					}
637: 					fileReaders.put(fileName, resource);
638: 					if (hasTravelObf) {
639: 						// travel files should be indexed separately (so it's possible to turn on / off)
640: 						continue;
641: 					}
642: 					if (!mapReader.getRegionNames().isEmpty()) {
643: 						RegionAddressRepositoryBinary rarb = new RegionAddressRepositoryBinary(this, resource);
644: 						addressMap.put(fileName, rarb);
645: 					}
646: 					if (mapReader.hasTransportData()) {
647: 						transportRepositories.put(fileName, resource);
648: 					}
649: 					// disable osmc for routing temporarily due to some bugs
650: 					if (mapReader.containsRouteData() && (!f.getParentFile().equals(liveDir) ||
651: 							app.getSettings().USE_OSM_LIVE_FOR_ROUTING.get())) {
652: 						resource.setUseForRouting(true);
653: 					}
654: 					if (mapReader.hasTransportData() && (!f.getParentFile().equals(liveDir) ||
655: 							app.getSettings().USE_OSM_LIVE_FOR_PUBLIC_TRANSPORT.get())) {
656: 						resource.setUseForPublicTransport(true);
657: 					}
658: 				}
659: 			} catch (SQLiteException e) {
660: 				log.error("Exception reading " + f.getAbsolutePath(), e);
661: 				warnings.add(MessageFormat.format(app.getString(R.string.version_index_is_not_supported), fileName));
662: 			} catch (OutOfMemoryError oome) {
663: 				log.error("Exception reading " + f.getAbsolutePath(), oome);
664: 				warnings.add(MessageFormat.format(app.getString(R.string.version_index_is_big_for_memory), fileName));
665: 			}
666: 		}
667: 		Map<PoiCategory, Map<String, PoiType>> toAddPoiTypes = new HashMap<>();
668: 		for (AmenityIndexRepository repo : amenitySearcher.getAmenityRepositories()) {
669: 			Map<String, List<String>> categories = ((AmenityIndexRepositoryBinary) repo).getDeltaPoiCategories();
670: 			if (!categories.isEmpty()) {
671: 				for (Map.Entry<String, List<String>> entry : categories.entrySet()) {
672: 					PoiCategory poiCategory = app.getPoiTypes().getPoiCategoryByName(entry.getKey(), true);
673: 					if (!toAddPoiTypes.containsKey(poiCategory)) {
674: 						toAddPoiTypes.put(poiCategory, new TreeMap<>());
675: 					}
676: 					Map<String, PoiType> poiTypes = toAddPoiTypes.get(poiCategory);
677: 					if (poiTypes != null) {
