215: 			for (PoiFilter pf : pc.getPoiFilters()) {
216: 				if (pf.getKeyName().equals(name)) {
217: 					return pf;
218: 				}
219: 				// search in poi additional
220: 				if (!skipAdditional) {
221: 					for (PoiType type : pf.getPoiTypes()) {
222: 						if (type.getKeyName().equals(name)) {
223: 							return type;
224: 						}
225: 						AbstractPoiType foundType = findInAdds(type.getPoiAdditionals(), name);
226: 						if (foundType != null) {
227: 							return foundType;
228: 						}
229: 					}
230: 				}
231: 			}
232: 			PoiType pt = pc.getPoiTypeByKeyName(name);
233: 			if (pt != null && !pt.isReference()) {
234: 				return pt;
235: 			}
236: 		}
237: 		return null;
238: 	}
