623: 	private PoiType buildPoiAdditionalReference(PoiType poiAdditional, AbstractPoiType parent, List<PoiType> textPoiAdditionals) {
624: 		PoiCategory lastCategory = null;
625: 		PoiFilter lastFilter = null;
626: 		PoiType lastType = null;
627: 		PoiType ref = null;
628: 		String keyName = poiAdditional.getKeyName();
629: 		String iconNameAttribute = poiAdditional.getIconNameInternal();
630: 		if (parent instanceof PoiCategory) {
631: 			lastCategory = (PoiCategory) parent;
632: 			ref = new PoiType(this, lastCategory, null, keyName, iconNameAttribute);
633: 		} else if (parent instanceof PoiFilter) {
634: 			lastFilter = (PoiFilter) parent;
635: 			ref = new PoiType(this, lastFilter.getPoiCategory(), lastFilter, keyName, iconNameAttribute);
636: 		} else if (parent instanceof PoiType) {
637: 			lastType = (PoiType) parent;
638: 			ref = new PoiType(this, lastType.getCategory(), lastType.getFilter(), keyName, iconNameAttribute);
639: 		}
640: 		if (ref == null) {
641: 			return null;
642: 		}
643: 		if (poiAdditional.isReference()) {
644: 			ref.setReferenceType(poiAdditional.getReferenceType());
645: 		} else {
646: 			ref.setReferenceType(poiAdditional);
647: 		}
648: 		ref.setBaseLangType(poiAdditional.getBaseLangType());
649: 		ref.setLang(poiAdditional.getLang());
650: 		ref.setAdditional(lastType != null ? lastType :
651: 				(lastFilter != null ? lastFilter : lastCategory));
652: 		ref.setTopVisible(poiAdditional.isTopVisible());
653: 		ref.setText(poiAdditional.isText());
654: 		ref.setOrder(poiAdditional.getOrder());
655: 		ref.setHidden(poiAdditional.isHidden());
656: 		ref.setOsmTag(poiAdditional.getOsmTag());
657: 		ref.setNotEditableOsm(poiAdditional.isNotEditableOsm());
