240: 	private AbstractPoiType findInAdds(List<PoiType> adds, String name) {
241: 		for (PoiType additional : adds) {
242: 			if (additional.getKeyName().equals(name)) {
243: 				return additional;
244: 			}
245: 			AbstractPoiType foundType = findInAdds(additional.getPoiAdditionals(), name);
246: 			if (foundType != null) {
247: 				return foundType;
248: 			}
249: 		}
250: 		return null;
251: 	}
