268: 			if (pt.isReference()) {
269: 				continue;
270: 			}
271: 			if (pt.getBaseLangType() != null) {
272: 				continue;
273: 			}
274: 			if (skipNonEditable && pt.isNotEditableOsm()) {
275: 				continue;
276: 			}
277: 			translation.put(pt.getKeyName().replace('_', ' ').toLowerCase(), pt);
278: 			translation.put(pt.getTranslation().toLowerCase(), pt);
279: 		}
