282: 	public List<AbstractPoiType> getAllTypesTranslatedNames(StringMatcher matcher) {
283: 		List<AbstractPoiType> tm = new ArrayList<AbstractPoiType>();
284: 		for (int i = 0; i < categories.size(); i++) {
285: 			PoiCategory pc = categories.get(i);
286: 			if (pc == getOtherMapCategory()) {
287: 				continue;
288: 			}
289: 			addIf(tm, pc, matcher);
290: 			for (PoiFilter pt : pc.getPoiFilters()) {
291: 				addIf(tm, pt, matcher);
292: 			}
293: 			for (PoiType pt : pc.getPoiTypes()) {
294: 				if (pt.isReference()) {
295: 					continue;
296: 				}
297: 				addIf(tm, pt, matcher);
298: 			}
299: 		}
300: 
301: 		return tm;
302: 	}
