304: 	private void addIf(List<AbstractPoiType> tm, AbstractPoiType pc, StringMatcher matcher) {
305: 		if (matcher.matches(pc.getTranslation()) || matcher.matches(pc.getKeyName().replace('_', ' '))) {
306: 			tm.add(pc);
307: 		}
308: 		List<PoiType> additionals = pc.getPoiAdditionals();
309: 		if (additionals != null) {
310: 			for (PoiType a : additionals) {
311: 				addIf(tm, a, matcher);
312: 			}
313: 		}
314: 	}
