406: 	public void initFromInputStream(InputStream is) {
407: 		long time = System.currentTimeMillis();
408: 		List<PoiType> referenceTypes = new ArrayList<>();
409: 		final Map<String, PoiType> allTypes = new LinkedHashMap<>();
410: 		final Map<String, List<PoiType>> categoryPoiAdditionalMap = new LinkedHashMap<>();
411: 		final Map<AbstractPoiType, Set<String>> abstractTypeAdditionalCategories = new LinkedHashMap<>();
412: 		final Map<String, PoiType> poiTypesByTag = new LinkedHashMap<>();
413: 		final Map<String, String> deprecatedTags = new LinkedHashMap<>();
414: 		final Map<String, String> poiAdditionalCategoryIconNames = new LinkedHashMap<>();
415: 		final List<PoiType> textPoiAdditionals = new ArrayList<>();
416: 
417: 		List<PoiCategory> categoriesList = new ArrayList<>();
418: 		try {
419: 			XmlPullParser parser = PlatformUtil.newXMLPullParser();
420: 			int tok;
421: 			parser.setInput(is, "UTF-8");
422: 			PoiCategory lastCategory = null;
423: 			Set<String> lastCategoryPoiAdditionalsCategories = new TreeSet<>();
424: 			PoiFilter lastFilter = null;
425: 			Set<String> lastFilterPoiAdditionalsCategories = new TreeSet<>();
426: 			PoiType lastType = null;
427: 			Set<String> lastTypePoiAdditionalsCategories = new TreeSet<>();
428: 			String lastPoiAdditionalCategory = null;
429: 			PoiCategory localOtherMapCategory = new PoiCategory(this, OTHER_MAP_CATEGORY, categoriesList.size());
430: 			categoriesList.add(localOtherMapCategory);
431: 			while ((tok = parser.next()) != XmlPullParser.END_DOCUMENT) {
432: 				if (tok == XmlPullParser.START_TAG) {
433: 					String name = parser.getName();
434:                     switch (name) {
435:                         case "poi_category" -> {
436:                             lastCategory = new PoiCategory(this, parser.getAttributeValue("", "name"), categoriesList.size());
437:                             lastCategory.setTopVisible(Boolean.parseBoolean(parser.getAttributeValue("", "top")));
438:                             lastCategory.setNotEditableOsm("true".equals(parser.getAttributeValue("", "no_edit")));
439:                             lastCategory.setDefaultTag(parser.getAttributeValue("", "default_tag"));
440:                             if (!Algorithms.hasItems(parser.getAttributeValue("", "poi_additional_category"))) {
441:                                 Collections.addAll(lastCategoryPoiAdditionalsCategories, parser.getAttributeValue("", "poi_additional_category").split(","));
442:                             }
443:                             if (!Algorithms.hasItems(parser.getAttributeValue("", "excluded_poi_additional_category"))) {
444:                                 lastCategory.addExcludedPoiAdditionalCategories(parser.getAttributeValue("", "excluded_poi_additional_category").split(","));
445:                                 lastCategory.getExcludedPoiAdditionalCategories().forEach(lastCategoryPoiAdditionalsCategories::remove);
446:                             }
447:                             categoriesList.add(lastCategory);
448:                         }
449:                         case "poi_filter" -> {
450:                             String keyName = parser.getAttributeValue("", "name");
451:                             String iconName = parser.getAttributeValue("", "icon");
452:                             PoiFilter tp = new PoiFilter(this, lastCategory, keyName, iconName);
453:                             tp.setTopVisible(Boolean.parseBoolean(parser.getAttributeValue("", "top")));
454:                             lastFilter = tp;
455:                             lastFilterPoiAdditionalsCategories.addAll(lastCategoryPoiAdditionalsCategories);
456:                             if (!Algorithms.hasItems(parser.getAttributeValue("", "poi_additional_category"))) {
457:                                 Collections.addAll(lastFilterPoiAdditionalsCategories, parser.getAttributeValue("", "poi_additional_category").split(","));
458:                             }
459:                             if (!Algorithms.hasItems(parser.getAttributeValue("", "excluded_poi_additional_category"))) {
460:                                 lastFilter.addExcludedPoiAdditionalCategories(parser.getAttributeValue("", "excluded_poi_additional_category").split(","));
461:                                 lastFilter.getExcludedPoiAdditionalCategories().forEach(lastFilterPoiAdditionalsCategories::remove);
462:                             }
463:                             if (lastCategory != null) {
464:                                 lastCategory.addPoiType(tp);
465:                             }
466:                         }
467:                         case "poi_reference" -> {
468:                             String keyName = parser.getAttributeValue("", "name");
469:                             String iconName = parser.getAttributeValue("", "icon");
470:                             PoiType tp = new PoiType(this, lastCategory, lastFilter, keyName, iconName);
471:                             referenceTypes.add(tp);
472:                             tp.setReferenceType(tp);
473:                             if (lastFilter != null) {
474:                                 lastFilter.addPoiType(tp);
475:                             }
476:                             if (lastCategory != null) {
477:                                 lastCategory.addPoiType(tp);
478:                             }
479:                         }
480:                         case "poi_additional" -> {
481:                             if (lastCategory == null) {
482:                                 lastCategory = localOtherMapCategory;
483:                             }
484:                             PoiType baseType = parsePoiAdditional(parser, lastCategory, lastFilter, lastType, null, null,
485:                                     lastPoiAdditionalCategory, textPoiAdditionals);
486:                             if ("true".equals(parser.getAttributeValue("", "lang"))) {
487:                                 for (String lng : MapRenderingTypes.langs) {
488:                                     parsePoiAdditional(parser, lastCategory, lastFilter, lastType, lng, baseType,
489:                                             lastPoiAdditionalCategory, textPoiAdditionals);
490:                                     if (baseType.isTopIndex()) {
491:                                         topIndexPoiAdditional.put(TOP_INDEX_ADDITIONAL_PREFIX + baseType.getKeyName() + ":" + lng, baseType);
492:                                     }
493:                                 }
494:                                 parsePoiAdditional(parser, lastCategory, lastFilter, lastType, "en", baseType,
495:                                         lastPoiAdditionalCategory, textPoiAdditionals);
496:                                 if (baseType.isTopIndex()) {
497:                                     topIndexPoiAdditional.put(TOP_INDEX_ADDITIONAL_PREFIX + baseType.getKeyName() + ":en", baseType);
498:                                 }
499:                             }
500:                             if (lastPoiAdditionalCategory != null) {
501:                                 List<PoiType> categoryAdditionals = categoryPoiAdditionalMap.computeIfAbsent(lastPoiAdditionalCategory, k -> new ArrayList<>());
502:                                 categoryAdditionals.add(baseType);
503:                             }
504:                             if (baseType.isTopIndex()) {
505:                                 topIndexPoiAdditional.put(TOP_INDEX_ADDITIONAL_PREFIX + baseType.getKeyName(), baseType);
506:                             }
507:                         }
508:                         case "poi_additional_category" -> {
509:                             if (lastPoiAdditionalCategory == null) {
510:                                 lastPoiAdditionalCategory = parser.getAttributeValue("", "name");
511:                                 String icon = parser.getAttributeValue("", "icon");
512:                                 if (!Algorithms.hasRouteId(icon)) {
513:                                     poiAdditionalCategoryIconNames.put(lastPoiAdditionalCategory, icon);
514:                                 }
515:                             }
516:                         }
517:                         case "poi_type" -> {
518:                             if (lastCategory == null) {
519:                                 lastCategory = localOtherMapCategory;
520:                             }
521:                             if (!Algorithms.hasItems(parser.getAttributeValue("", "deprecated_of"))) {
522:                                 String vl = parser.getAttributeValue("", "name");
523:                                 String target = parser.getAttributeValue("", "deprecated_of");
524:                                 deprecatedTags.put(vl, target);
525:                             } else {
526:                                 lastType = parsePoiType(allTypes, parser, lastCategory, lastFilter, null, null);
527:                                 if ("true".equals(parser.getAttributeValue("", "lang"))) {
528:                                     for (String lng : MapRenderingTypes.langs) {
529:                                         parsePoiType(allTypes, parser, lastCategory, lastFilter, lng, lastType);
530:                                     }
531:                                 }
532:                                 lastTypePoiAdditionalsCategories.addAll(lastCategoryPoiAdditionalsCategories);
533:                                 lastTypePoiAdditionalsCategories.addAll(lastFilterPoiAdditionalsCategories);
534:                                 if (!Algorithms.hasItems(parser.getAttributeValue("", "poi_additional_category"))) {
535:                                     Collections.addAll(lastTypePoiAdditionalsCategories, parser.getAttributeValue("", "poi_additional_category").split(","));
536:                                 }
537:                                 if (!Algorithms.hasItems(parser.getAttributeValue("", "excluded_poi_additional_category"))) {
538:                                     lastType.addExcludedPoiAdditionalCategories(parser.getAttributeValue("", "excluded_poi_additional_category").split(","));
539:                                     lastType.getExcludedPoiAdditionalCategories().forEach(lastTypePoiAdditionalsCategories::remove);
540:                                 }
541:                             }
542:                         }
543:                         case "poi_types" -> {
544:                             // just ignore the root tag of poi_types.xml
545:                         }
546:                         default -> log.warn("Unknown start tag encountered: " + name);
547:                     }
548:                 } else if (tok == XmlPullParser.END_TAG) {
549:                     String name = parser.getName();
550:                     switch (name) {
551:                         case "poi_filter" -> {
552:                             if (!lastFilterPoiAdditionalsCategories.isEmpty()) {
553:                                 abstractTypeAdditionalCategories.put(lastFilter, lastFilterPoiAdditionalsCategories);
554:                                 lastFilterPoiAdditionalsCategories = new TreeSet<>();
555:                             }
556:                             lastFilter = null;
557:                         }
558:                         case "poi_type" -> {
559:                             if (!lastTypePoiAdditionalsCategories.isEmpty()) {
560:                                 abstractTypeAdditionalCategories.put(lastType, lastTypePoiAdditionalsCategories);
561:                                 lastTypePoiAdditionalsCategories = new TreeSet<>();
562:                             }
563:                             lastType = null;
564:                         }
565:                         case "poi_category" -> {
566:                             if (!lastCategoryPoiAdditionalsCategories.isEmpty()) {
567:                                 abstractTypeAdditionalCategories.put(lastCategory, lastCategoryPoiAdditionalsCategories);
568:                                 lastCategoryPoiAdditionalsCategories = new TreeSet<>();
569:                             }
570:                             lastCategory = null;
571:                         }
572:                         case "poi_additional_category" -> lastPoiAdditionalCategory = null;
573: 	                    default -> {
574: 		                    if (!name.equals("poi_additional") && !name.equals("poi_reference") && !name.equals("poi_types")) {
575: 			                    log.warn("Unknown end tag encountered: " + name);
576: 		                    }
577: 	                    }
578:                     }
579: 				}
580: 			}
581: 
582: 			is.close();
583: 		} catch (IOException | XmlPullParserException e) {
584: 			log.error("Unexpected error", e); //$NON-NLS-1$
585: 			e.printStackTrace();
586: 			throw new RuntimeException(e);
587: 		} catch (RuntimeException e) {
588: 			log.error("Unexpected error", e); //$NON-NLS-1$
589: 			e.printStackTrace();
590: 			throw e;
591: 		}
592: 		for (PoiType gt : referenceTypes) {
593: 			PoiType pt = allTypes.get(gt.getKeyName());
594: 			if (pt == null || pt.getOsmTag() == null) {
