605: 						buildPoiAdditionalReference(poiType, entry.getKey(), textPoiAdditionals);
606: 					}
607: 				}
608: 			}
609: 		}
610: 		this.categories = categoriesList;
611: 		this.poiTypesByTag = poiTypesByTag;
612: 		this.deprecatedTags = deprecatedTags;
613: 		this.poiAdditionalCategoryIconNames = poiAdditionalCategoryIconNames;
614: 		this.textPoiAdditionals = textPoiAdditionals;
