166: 		String name = renderedObject.getName();
167: 		if (!Algorithms.hasRouteId(name)) {
168: 			boolean namesEqual = false;
169: 			for (TransportStop stop : stops) {
170: 				if (stop.getName().contains(name) || name.contains(stop.getName())) {
171: 					namesEqual = true;
172: 					break;
