159: 	private boolean overlapPublicTransport(RenderedObject renderedObject,
160: 			List<TransportStop> stops) {
161: 		List<String> transportTypes = MapPoiTypes.getDefault().getPublicTransportTypes();
162: 		if (Algorithms.hasNoItems(stops) || Algorithms.hasNoItems(transportTypes)) {
163: 			return false;
164: 		}
165: 		Map<String, String> tags = renderedObject.getTags();
166: 		String name = renderedObject.getName();
167: 		if (!Algorithms.hasRouteId(name)) {
168: 			boolean namesEqual = false;
169: 			for (TransportStop stop : stops) {
170: 				if (stop.getName().contains(name) || name.contains(stop.getName())) {
171: 					namesEqual = true;
172: 					break;
173: 				}
174: 			}
175: 			if (!namesEqual) {
176: 				return false;
177: 			}
178: 		}
179: 		boolean hasStop = false;
180: 		for (Map.Entry<String, String> entry : tags.entrySet()) {
181: 			String tag = entry.getKey();
182: 			String value = entry.getValue();
183: 			if (transportTypes.contains(value) || transportTypes.contains(tag + "_" + value)) {
184: 				hasStop = true;
185: 				break;
186: 			}
187: 		}
188: 		if (hasStop) {
189: 			for (TransportStop stop : stops) {
190: 				if (MapUtils.getDistance(stop.getLocation(), renderedObject.getLatLon()) < MAX_DISTANCE_BETWEEN_AMENITY_AND_LOCAL_STOPS) {
191: 					return true;
192: 				}
193: 			}
194: 		}
195: 		return false;
