316: 	private void refreshPoiFiltersOrder(@NonNull ApplicationMode appMode,
317: 			List<PoiUIFilter> filters) {
318: 		Map<String, Integer> orders = getPoiFiltersOrder(appMode);
319: 		List<PoiUIFilter> existedFilters = new ArrayList<>();
320: 		List<PoiUIFilter> newFilters = new ArrayList<>();
321: 		if (orders != null) {
322: 			//set up orders from settings
323: 			for (PoiUIFilter filter : filters) {
324: 				Integer order = orders.get(filter.getFilterId());
325: 				if (order != null) {
326: 					filter.setOrder(order);
327: 					existedFilters.add(filter);
328: 				} else {
329: 					newFilters.add(filter);
330: 				}
331: 			}
332: 			//make order values without spaces
333: 			Collections.sort(existedFilters);
334: 			for (int i = 0; i < existedFilters.size(); i++) {
335: 				existedFilters.get(i).setOrder(i);
336: 			}
337: 			//set up maximum orders for new poi filters
338: 			Collections.sort(newFilters);
339: 			for (PoiUIFilter filter : newFilters) {
340: 				filter.setOrder(existedFilters.size());
341: 				existedFilters.add(filter);
342: 			}
343: 		} else {
344: 			for (PoiUIFilter filter : filters) {
345: 				filter.setOrder(PoiUIFilter.INVALID_ORDER);
346: 			}
347: 		}
348: 	}
