161: 	public PoiUIFilter getFilterById(String filterId, boolean includeDeleted) {
162: 		if (filterId == null) {
163: 			return null;
164: 		}
165: 		for (PoiUIFilter filter : getTopDefinedPoiFilters(includeDeleted)) {
166: 			if (filter.getFilterId().equals(filterId)) {
167: 				return filter;
168: 			}
