182: 			AbstractPoiType lt = app.getPoiTypes().getAnyPoiAdditionalTypeByKey(typeId);
183: 			if (lt != null) {
184: 				PoiUIFilter lf = new PoiUIFilter(lt, app, "");
185: 				return addTopPoiFilter(lf);
