302: 	private void initPoiUIFiltersState(@NonNull ApplicationMode appMode) {
303: 		List<PoiUIFilter> allFilters = new ArrayList<>();
304: 		allFilters.addAll(getTopDefinedPoiFilters());
305: 		allFilters.addAll(getSearchPoiFilters());
306: 
307: 		refreshPoiFiltersActivation(appMode, allFilters);
308: 		refreshPoiFiltersOrder(appMode, allFilters);
309: 
310: 		//set up the biggest order to custom filter
