416: 	public boolean createPoiFilter(@NonNull PoiUIFilter filter, boolean forHistory) {
417: 		PoiFilterDbHelper helper = openDbHelper();
418: 		List<PoiUIFilter> standardFilters = getTopStandardFilters();
419: 		if (standardFilters == null || helper == null) {
420: 			return false;
421: 		}
422: 		helper.deleteFilter(helper.getWritableDatabase(), filter, true);
423: 
424: 		Set<PoiUIFilter> filtersToRemove = new HashSet<>();
425: 		for (PoiUIFilter f : standardFilters) {
426: 			if (Objects.equals(f.getFilterId(), filter.getFilterId())) {
427: 				filtersToRemove.add(f);
428: 			}
429: 		}
430: 		setTopStandardFilters(standardFilters = CollectionUtils.removeAllFromList(standardFilters, filtersToRemove));
431: 		boolean res = helper.addFilter(filter, helper.getWritableDatabase(), false, forHistory);
432: 		if (res) {
433: 			addTopPoiFilter(filter);
434: 			Collections.sort(standardFilters);
435: 		}
436: 		helper.close();
437: 		return res;
438: 	}
