630: 	public int calculateCurrentRoute(@NonNull Location currentLocation, double posTolerance,
631: 	                                 @NonNull List<Location> routeNodes, int currentRoute,
632: 	                                 boolean updateAndNotify) {
633: 		while (currentRoute + 1 < routeNodes.size()) {
634: 			double dist = currentLocation.distanceTo(routeNodes.get(currentRoute));
635: 			if (currentRoute > 0) {
636: 				dist = RoutingHelperUtils.getOrthogonalDistance(currentLocation, routeNodes.get(currentRoute - 1),
637: 						routeNodes.get(currentRoute));
638: 			}
639: 			boolean processed = false;
640: 			// if we are still too far try to proceed many points
641: 			// if not then look ahead only 3 in order to catch sharp turns
642: 			boolean longDistance = dist >= 250;
643: 			int newCurrentRoute = RoutingHelperUtils.lookAheadFindMinOrthogonalDistance(currentLocation, routeNodes, currentRoute, longDistance ? 15 : 8);
644: 			double newDist = RoutingHelperUtils.getOrthogonalDistance(currentLocation, routeNodes.get(newCurrentRoute),
645: 					routeNodes.get(newCurrentRoute + 1));
646: 			if (longDistance) {
647: 				if (newDist < dist) {
648: 					if (ENABLE_LOG_POS_PROCESSED) {
649: 						log.debug("Processed by distance : (new) " + newDist + " (old) " + dist); //$NON-NLS-1$//$NON-NLS-2$
650: 					}
651: 					processed = true;
652: 				}
653: 			} else if (newDist < dist || newDist < posTolerance / 8) {
654: 				// newDist < posTolerance / 8 - 4-8 m (avoid distance 0 till next turn)
655: 				if (dist > posTolerance) {
656: 					processed = true;
657: 					if (ENABLE_LOG_POS_PROCESSED) {
658: 						log.debug("Processed by distance : " + newDist + " " + dist); //$NON-NLS-1$//$NON-NLS-2$
659: 					}
660: 				} else {
661: 					if (currentLocation.hasBearing() && !deviceHasBearing) {
662: 						deviceHasBearing = true;
663: 					}
664: 					// lastFixedLocation.bearingTo -  gives artefacts during u-turn, so we avoid for devices with bearing
665: 					if ((currentRoute > 0 || newCurrentRoute > 0) &&
666: 							(currentLocation.hasBearing() || (!deviceHasBearing && lastFixedLocation != null))) {
667: 						float bearingToRoute = currentLocation.bearingTo(routeNodes.get(currentRoute));
668: 						float bearingRouteNext = routeNodes.get(newCurrentRoute).bearingTo(routeNodes.get(newCurrentRoute + 1));
669: 						float bearingMotion = currentLocation.hasBearing() ? currentLocation.getBearing() : lastFixedLocation
670: 								.bearingTo(currentLocation);
671: 						double diff = Math.abs(MapUtils.degreesDiff(bearingMotion, bearingToRoute));
672: 						double diffToNext = Math.abs(MapUtils.degreesDiff(bearingMotion, bearingRouteNext));
673: 						if (diff > diffToNext) {
674: 							if (ENABLE_LOG_POS_PROCESSED) {
675: 								log.debug("Processed point bearing deltas : " + diff + " " + diffToNext);
676: 							}
677: 							processed = true;
678: 						}
679: 					}
680: 				}
681: 			}
682: 			if (processed) {
683: 				// that node already passed
684: 				currentRoute = newCurrentRoute + 1;
685: 				if (updateAndNotify) {
686: 					route.updateCurrentRoute(newCurrentRoute + 1);
687: 					app.getNotificationHelper().refreshNotification(NotificationType.NAVIGATION);
688: 					fireRoutingDataUpdateEvent();
689: 				}
690: 			} else {
691: 				break;
692: 			}
693: 		}
694: 		return currentRoute;
695: 	}
