750: 				fragmentsHelper.dismissSecondSplashScreen();
751: 			}
752: 			applyScreenOrientation();
753: 		}
754: 
755: 		settings.MAP_SCREEN_ORIENTATION.addListener(mapScreenOrientationSettingListener);
756: 		settings.USE_SYSTEM_SCREEN_TIMEOUT.addListener(useSystemScreenTimeoutListener);
757: 
758: 		extendedMapActivity.onResume(this);
