1384: 					int drawerWidth = AndroidUtils.dpToPx(this, 280);
1385: 					int screenWidth = AndroidUtils.getScreenWidth(this);
1386: 					boolean isLayoutRtl = AndroidUtils.isLayoutRtl(app);
1387: 					if ((!isLayoutRtl && event.getRawX() > drawerWidth)
1388: 							|| (isLayoutRtl && event.getRawX() <= screenWidth - drawerWidth)) {
1389: 						closeDrawer();
1390: 					}
1391: 				}
1392: 			}
1393: 		}
1394: 		return super.dispatchTouchEvent(event);
1395: 	}
