816: 	public void readLocationToShow() {
817: 		showMapControls();
818: 		OsmandMapTileView mapView = getMapView();
819: 		LatLon currentLatLon = new LatLon(mapView.getLatitude(), mapView.getLongitude());
820: 		LatLon latLonToShow = settings.getAndClearMapLocationToShow();
821: 		PointDescription mapLabelToShow = settings.getAndClearMapLabelToShow(latLonToShow);
822: 		Object toShow = settings.getAndClearObjectToShow();
823: 		boolean editToShow = settings.getAndClearEditObjectToShow();
824: 		int status = settings.isRouteToPointNavigateAndClear();
825: 		String searchRequestToShow = settings.getAndClearSearchRequestToShow();
826: 		if (status != 0 || searchRequestToShow != null || latLonToShow != null) {
827: 			fragmentsHelper.dismissSettingsScreens();
828: 		}
829: 		if (status != 0) {
830: 			// always enable and follow and let calculate it (i.e.GPS is not accessible in a garage)
831: 			Location location = new Location("map");
832: 			location.setLatitude(mapView.getLatitude());
833: 			location.setLongitude(mapView.getLongitude());
834: 			getMapActions().enterRoutePlanningModeGivenGpx(null, null, null, true, true);
835: 			if (dashboardOnMap.isVisible()) {
836: 				dashboardOnMap.hideDashboard();
837: 			}
838: 		}
839: 		if (trackDetailsMenu.isVisible()) {
840: 			trackDetailsMenu.show();
841: 		}
842: 		if (searchRequestToShow != null) {
843: 			fragmentsHelper.showQuickSearch(searchRequestToShow);
844: 		}
845: 		if (latLonToShow != null) {
846: 			if (dashboardOnMap.isVisible()) {
847: 				dashboardOnMap.hideDashboard();
848: 			}
849: 			// remember if map should come back to isMapLinkedToLocation=true
850: 			getMapViewTrackingUtilities().setMapLinkedToLocation(false);
851: 			if (mapLabelToShow != null && !mapLabelToShow.contextMenuDisabled()) {
852: 				mapContextMenu.setMapCenter(latLonToShow);
853: 				mapContextMenu.setCenterMarker(true);
854: 
855: 				RotatedTileBox tb = mapView.getRotatedTileBox();
856: 				LatLon prevCenter = tb.getCenterLatLon();
857: 
858: 				double border = 0.8;
859: 				int tbw = (int) (tb.getPixWidth() * border);
860: 				int tbh = (int) (tb.getPixHeight() * border);
861: 				tb.setPixelDimensions(tbw, tbh);
862: 
863: 				tb.setLatLonCenter(latLonToShow.getLatitude(), latLonToShow.getLongitude());
864: 
865: 				int zoom = settings.hasMapZoomToShow() ? settings.getMapZoomToShow() : ZOOM_LABEL_DISPLAY;
866: 				tb.setZoom(zoom);
867: 				while (!tb.containsLatLon(prevCenter.getLatitude(), prevCenter.getLongitude()) && tb.getZoom() > zoom - MAX_ZOOM_OUT_STEPS) {
868: 					tb.setZoom(tb.getZoom() - 1);
869: 				}
870: 				boolean containsPrevious = tb.containsLatLon(prevCenter.getLatitude(), prevCenter.getLongitude());
871: 				mapContextMenu.setMapZoom(containsPrevious ? tb.getZoom() : zoom);
872: 
873: 				if (toShow instanceof GpxDisplayItem) {
874: 					trackDetailsMenu.setGpxItem((GpxDisplayItem) toShow);
875: 					trackDetailsMenu.show();
876: 				} else if (mapRouteInfoMenu.isVisible()) {
877: 					mapContextMenu.showMinimized(latLonToShow, mapLabelToShow, toShow);
878: 					mapRouteInfoMenu.updateMenu();
879: 					MapRouteInfoMenu.showLocationOnMap(this, latLonToShow.getLatitude(), latLonToShow.getLongitude());
880: 				} else if (toShow instanceof GpxFile) {
881: 					hideContextAndRouteInfoMenues();
882: 					GpxFile gpxFile = (GpxFile) toShow;
883: 					SelectedGpxFile selectedGpxFile;
884: 					if (gpxFile.isShowCurrentTrack()) {
885: 						selectedGpxFile = app.getSavingTrackHelper().getCurrentTrack();
886: 					} else {
887: 						GpxSelectionParams params = GpxSelectionParams.newInstance()
888: 								.showOnMap().selectedAutomatically().saveSelection();
889: 						selectedGpxFile = app.getSelectedGpxHelper().selectGpxFile(gpxFile, params);
890: 					}
891: 
892: 					TrackAppearanceFragment.showInstance(this, selectedGpxFile, null);
893: 				} else if (toShow instanceof QuadRect) {
894: 					QuadRect qr = (QuadRect) toShow;
