1225: 	public static void launchMapActivityMoveToTop(@NonNull Context activity,
1226: 	                                              @Nullable Bundle prevIntentParams,
1227: 	                                              @Nullable Uri intentData,
1228: 	                                              @Nullable Bundle intentParams) {
1229: 		if (activity instanceof MapActivity) {
1230: 			if (((MapActivity) activity).getDashboard().isVisible()) {
1231: 				((MapActivity) activity).getDashboard().hideDashboard();
1232: 			}
1233: 			((MapActivity) activity).readLocationToShow();
1234: 		} else {
1235: 			int additionalFlags = 0;
1236: 			if (activity instanceof Activity) {
1237: 				Intent intent = ((Activity) activity).getIntent();
1238: 				if (intent != null) {
1239: 					prevActivityIntent = new Intent(intent);
1240: 					if (prevIntentParams != null) {
1241: 						prevActivityIntent.putExtra(INTENT_PARAMS, prevIntentParams);
1242: 						prevActivityIntent.putExtras(prevIntentParams);
1243: 					}
1244: 					prevActivityIntent.putExtra(INTENT_KEY_PARENT_MAP_ACTIVITY, true);
1245: 				} else {
1246: 					prevActivityIntent = null;
1247: 				}
1248: 			} else {
1249: 				prevActivityIntent = null;
1250: 				additionalFlags = Intent.FLAG_ACTIVITY_NEW_TASK;
1251: 			}
1252: 
1253: 			Intent newIntent = new Intent(activity, ((OsmandApplication) activity.getApplicationContext())
1254: 					.getAppCustomization().getMapActivity());
1255: 			newIntent.addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT | Intent.FLAG_ACTIVITY_CLEAR_TOP | additionalFlags);
1256: 			if (intentData != null) {
1257: 				newIntent.setAction(Intent.ACTION_VIEW);
1258: 				newIntent.setData(intentData);
1259: 			}
1260: 			if (intentParams != null) {
1261: 				newIntent.putExtra(INTENT_PARAMS, intentParams);
1262: 				newIntent.putExtras(intentParams);
1263: 			}
1264: 			AndroidUtils.startActivityIfSafe(activity, newIntent);
1265: 		}
1266: 	}
