1372: 	public boolean dispatchTouchEvent(MotionEvent event) {
1373: 		if (lockHelper.isScreenLocked()) {
1374: 			return lockHelper.getLockGestureDetector(this).onTouchEvent(event);
1375: 		}
1376: 
1377: 		if (event.getAction() == MotionEvent.ACTION_DOWN || event.getAction() == MotionEvent.ACTION_MOVE) {
1378: 			lockHelper.resetLockTimerIfNeeded();
1379: 		}
1380: 
1381: 		if (settings.DO_NOT_USE_ANIMATIONS.get()) {
1382: 			if (event.getAction() == MotionEvent.ACTION_DOWN) {
1383: 				if (drawerLayout.isDrawerOpen(GravityCompat.START)) {
1384: 					int drawerWidth = AndroidUtils.dpToPx(this, 280);
1385: 					int screenWidth = AndroidUtils.getScreenWidth(this);
1386: 					boolean isLayoutRtl = AndroidUtils.isLayoutRtl(app);
1387: 					if ((!isLayoutRtl && event.getRawX() > drawerWidth)
1388: 							|| (isLayoutRtl && event.getRawX() <= screenWidth - drawerWidth)) {
1389: 						closeDrawer();
1390: 					}
1391: 				}
1392: 			}
1393: 		}
1394: 		return super.dispatchTouchEvent(event);
1395: 	}
