912: 			// Mask STOPs closer to the start than to the end of the routing segment if it is within 50m of start, but do not mask STOPs mapped directly on start/end (likely intersection node)
913: 			double d2Start = distance(startPointInd, ind);
914: 			double d2End = distance(ind, endPointInd);
