2199: 	public Map<String, String> getTileSourceEntries(boolean sqlite) {
2200: 		Map<String, String> map = new LinkedHashMap<String, String>();
2201: 		File dir = ctx.getAppPath(IndexConstants.TILES_INDEX_DIR);
2202: 		if (dir != null && dir.canRead()) {
2203: 			File[] files = dir.listFiles();
2204: 			if (files != null) {
2205: 				Arrays.sort(files, (f1, f2) -> {
2206: 					if (f1.lastModified() > f2.lastModified()) {
2207: 						return -1;
2208: 					} else if (f1.lastModified() == f2.lastModified()) {
2209: 						return 0;
2210: 					}
2211: 					return 1;
2212: 				});
2213: 				for (File f : files) {
2214: 					String fileName = f.getName();
2215: 					if (fileName.endsWith(SQLITE_EXT)) {
2216: 						if (sqlite) {
2217: 							map.put(fileName, getTileSourceTitle(fileName));
2218: 						}
2219: 					} else if (f.isDirectory() && !fileName.equals(IndexConstants.TEMP_SOURCE_TO_LOAD)
2220: 							&& !fileName.startsWith(".")) {
2221: 						map.put(fileName, fileName);
2222: 					}
2223: 				}
2224: 			}
2225: 		}
2226: 		for (TileSourceTemplate l : TileSourceManager.getKnownSourceTemplates()) {
2227: 			if (!l.isHidden()) {
2228: 				map.put(l.getName(), l.getName());
2229: 			} else {
2230: 				map.remove(l.getName());
2231: 			}
2232: 		}
2233: 		return map;
2234: 	}
