389: 	public static boolean intersects(@NonNull QuadTree<QuadRect> boundIntersections, @NonNull QuadRect visibleRect, boolean insert) {
390: 		List<QuadRect> result = new ArrayList<>();
391: 		boundIntersections.queryInBox(new QuadRect(visibleRect), result);
392: 		for (QuadRect rect : result) {
393: 			if (QuadRect.intersects(rect, visibleRect)) {
394: 				return true;
