405: 		double leftLongitude = latlonRect.left;
406: 		double bottomLatitude = latlonRect.bottom;
407: 		double rightLongitude = latlonRect.right;
408: 		// double lat = 0;
409: 		// double lon = 0;
410: 		// this is buggy lat/lon should be 0 but in that case
411: 		// it needs to be fixed in case there is no route points in the view bbox
412: 		double lat = topLatitude - bottomLatitude + 0.1;
413: 		double lon = rightLongitude - leftLongitude + 0.1;
414: 		return new QuadRect(leftLongitude - lon, topLatitude + lat, rightLongitude + lon, bottomLatitude - lat);
