458: 	private boolean shouldAutoZoom(@NonNull Location location, long autoZoomFrequency) {
459: 		if (!settings.AUTO_ZOOM_MAP.get() || !location.hasSpeed()) {
460: 			return false;
461: 		}
462: 
463: 		long now = System.currentTimeMillis();
464: 		boolean isUserZoomed = lastTimeManualZooming > lastTimeAutoZooming;
465: 		return isUserZoomed
466: 				? now - lastTimeManualZooming > Math.max(settings.AUTO_FOLLOW_ROUTE.get() * 1000, AUTO_ZOOM_DEFAULT_CHANGE_ZOOM)
467: 				: now - lastTimeAutoZooming > autoZoomFrequency;
468: 	}
