474: 	public void backToLocationImpl(int zoom, boolean forceZoom) {
475: 		if (mapView != null) {
476: 			OsmAndLocationProvider locationProvider = app.getLocationProvider();
477: 			Location lastKnownLocation = locationProvider.getLastKnownLocation();
478: 			Location lastStaleKnownLocation = locationProvider.getLastStaleKnownLocation();
479: 			Location location = lastKnownLocation != null ? lastKnownLocation : lastStaleKnownLocation;
480: 			if (!isMapLinkedToLocation()) {
481: 				if (location != null) {
482: 					animateBackToLocation(location, zoom, forceZoom);
483: 				} else {
484: 					setMapLinkedToLocation(true);
485: 				}
486: 				mapView.refreshMap();
487: 			}
488: 			if (location == null) {
489: 				//Hardy, 2019-12-15: Inject A-GPS data if backToLocationImpl fails with no fix:
490: 				if (app.getSettings().isInternetConnectionAvailable(true)) {
491: 					locationProvider.redownloadAGPS();
492: 					app.showToastMessage(app.getString(R.string.unknown_location) + "\n\n" + app.getString(R.string.agps_data_last_downloaded, (new SimpleDateFormat("yyyy-MM-dd  HH:mm")).format(app.getSettings().AGPS_DATA_LAST_TIME_DOWNLOADED.get())));
493: 				} else {
494: 					app.showToastMessage(R.string.unknown_location);
495: 				}
496: 			}
497: 		}
498: 	}
