500: 	private void animateBackToLocation(@NonNull Location location, int zoom, boolean forceZoom) {
501: 		AnimateDraggingMapThread thread = mapView.getAnimatedDraggingThread();
502: 		int targetZoom;
503: 		float targetZoomFloatPart;
504: 		if (mapView.getZoom() < zoom && (forceZoom || app.getSettings().AUTO_ZOOM_MAP.get())) {
505: 			targetZoom = zoom;
506: 			targetZoomFloatPart = 0;
507: 		} else {
508: 			targetZoom = mapView.getZoom();
509: 			targetZoomFloatPart = mapView.getZoomFloatPart();
510: 		}
511: 		Runnable startAnimationCallback = () -> {
512: 			movingToMyLocation = true;
513: 			if (!isMapLinkedToLocation) {
514: 				setMapLinkedToLocation(true);
515: 			}
516: 		};
517: 		Runnable finishAnimationCallback = () -> movingToMyLocation = false;
518: 		thread.startMoving(location.getLatitude(), location.getLongitude(), targetZoom, targetZoomFloatPart,
519: 				false, true, startAnimationCallback, finishAnimationCallback);
520: 	}
