105: 	public static List<ApplicationMode> values(@NonNull OsmandApplication app) {
106: 		if (customizationListener == null) {
107: 			customizationListener = () -> cachedFilteredValues = new ArrayList<>();
108: 			app.getAppCustomization().addListener(customizationListener);
109: 		}
110: 		if (cachedFilteredValues.isEmpty()) {
111: 			OsmandSettings settings = app.getSettings();
112: 			if (listener == null) {
113: 				listener = change -> cachedFilteredValues = new ArrayList<>();
114: 				settings.AVAILABLE_APP_MODES.addListener(listener);
115: 			}
116: 			String available = settings.AVAILABLE_APP_MODES.get();
117: 			cachedFilteredValues = new ArrayList<>();
118: 			for (ApplicationMode v : values) {
119: 				if (available.contains(v.getStringKey() + ",") || v == DEFAULT) {
120: 					cachedFilteredValues.add(v);
121: 				}
122: 			}
123: 		}
124: 		return cachedFilteredValues;
125: 	}
