526: 	private static void initCustomModes(OsmandApplication app) {
527: 		OsmandSettings settings = app.getSettings();
528: 		for (String appModeKey : settings.getCustomAppModesKeys()) {
529: 			Object profilePreferences = settings.getProfilePreferences(appModeKey);
530: 			String parent = settings.PARENT_APP_MODE.getValue(profilePreferences, null);
531: 			int order = settings.APP_MODE_ORDER.getValue(profilePreferences, values.size());
532: 
533: 			ApplicationModeBuilder builder = createCustomMode(valueOfStringKey(parent, CAR), appModeKey, app);
534: 			builder.setOrder(order);
535: 			builder.customReg();
536: 		}
537: 	}
