547: 	private static void updateAppModesOrder() {
548: 		for (int i = 0; i < values.size(); i++) {
549: 			ApplicationMode mode = values.get(i);
550: 			if (mode.getOrder() != i) {
551: 				mode.setOrder(i);
552: 			}
553: 		}
554: 	}
