571: 	public static ApplicationMode saveProfile(ApplicationModeBuilder builder, OsmandApplication app) {
572: 		ApplicationMode mode = valueOfStringKey(builder.applicationMode.stringKey, null);
573: 		if (mode != null) {
574: 			mode.setParentAppMode(builder.applicationMode.parentAppMode);
575: 			mode.setIconResName(builder.iconResName);
576: 			mode.setUserProfileName(builder.userProfileName);
577: 			mode.setRoutingProfile(builder.routingProfile);
578: 			mode.setRouteService(builder.routeService);
579: 			mode.setIconColor(builder.iconColor);
580: 			mode.setCustomIconColor(builder.customIconColor);
581: 			mode.setLocationIcon(builder.locationIcon);
582: 			mode.setNavigationIcon(builder.navigationIcon);
583: 			mode.setOrder(builder.order);
584: 			mode.setVersion(builder.version);
585: 			mode.setViewAngleVisibility(builder.viewAngle);
586: 			mode.setLocationRadius(builder.locationRadius);
587: 		} else {
588: 			mode = builder.customReg();
589: 			WidgetsAvailabilityHelper.initRegVisibility(app);
590: 		}
591: 		reorderAppModes();
592: 		saveCustomAppModesToSettings(app);
593: 		return mode;
594: 	}
