601: 		boolean announceFavorites = settings.ANNOUNCE_NEARBY_FAVORITES.getModeValue(appMode);
602: 
603: 		if ((type == FAVORITES || all)) {
604: 			List<LocationPointWrapper> array = clearAndGetArray(locationPoints, FAVORITES);
605: 			if (showFavorites) {
606: 				findLocationPoints(route, FAVORITES, array, app.getFavoritesHelper().getVisibleFavouritePoints(),
607: 						announceFavorites);
608: 				sortList(array);
609: 			}
610: 		}
611: 		if ((type == ALARMS || all)) {
612: 			List<LocationPointWrapper> array = clearAndGetArray(locationPoints, ALARMS);
613: 			if (route.getAppMode() != null) {
614: 				calculateAlarms(route, array, appMode);
615: 				sortList(array);
