368: 	@Override
369: 	public void onSensorChanged(SensorEvent event) {
370: 		// Attention : sensor produces a lot of events & can hang the system
371: 		if (inUpdateValue) {
372: 			return;
373: 		}
374: 		synchronized (this) {
375: 			if (!sensorRegistered) {
376: 				return;
377: 			}
378: 			inUpdateValue = true;
379: 			try {
380: 				float val = 0;
381: 				switch (event.sensor.getType()) {
382: 					case Sensor.TYPE_ACCELEROMETER:
383: 						System.arraycopy(event.values, 0, mGravs, 0, 3);
384: 						break;
385: 					case Sensor.TYPE_MAGNETIC_FIELD:
386: 						System.arraycopy(event.values, 0, mGeoMags, 0, 3);
387: 						break;
388: 					case Sensor.TYPE_ORIENTATION:
389: 					case Sensor.TYPE_ROTATION_VECTOR:
390: 						val = event.values[0];
391: 						break;
392: 					default:
393: 						return;
394: 				}
395: 				OsmandSettings settings = app.getSettings();
396: 				if (event.sensor.getType() == Sensor.TYPE_ACCELEROMETER || event.sensor.getType() == Sensor.TYPE_MAGNETIC_FIELD) {
397: 					boolean success = SensorManager.getRotationMatrix(mRotationM, null, mGravs, mGeoMags);
398: 					if (!success) {
399: 						return;
400: 					}
401: 					float[] orientation = SensorManager.getOrientation(mRotationM, new float[3]);
402: 					val = (float) Math.toDegrees(orientation[0]);
403: 				} else if (event.sensor.getType() == Sensor.TYPE_ROTATION_VECTOR) {
404: 					SensorManager.getRotationMatrixFromVector(mRotationM, event.values);
405: 					float[] orientation = SensorManager.getOrientation(mRotationM, new float[3]);
406: 					val = (float) Math.toDegrees(orientation[0]);
407: 				}
408: 				val = calcScreenOrientationCorrection(val);
409: 				val = calcGeoMagneticCorrection(val);
410: 
411: 				float valRad = (float) (val / 180f * Math.PI);
412: 				lastValSin = (float) Math.sin(valRad);
413: 				lastValCos = (float) Math.cos(valRad);
414: 				// lastHeadingCalcTime = System.currentTimeMillis();
415: 				boolean filter = settings.USE_KALMAN_FILTER_FOR_COMPASS.get();
416: 				if (filter) {
417: 					filterCompassValue();
418: 				} else {
419: 					avgValSin = lastValSin;
420: 					avgValCos = lastValCos;
421: 				}
422: 
423: 				heading = getAngle(avgValSin, avgValCos);
424: 				updateCompassVal();
425: 			} finally {
426: 				inUpdateValue = false;
427: 			}
428: 		}
429: 	}
430: 
431: 	private float calcGeoMagneticCorrection(float val) {
432: 		net.osmand.Location l = getLastKnownLocation();
433: 		if (previousCorrectionValue == 360 && l != null) {
434: 			GeomagneticField gf = new GeomagneticField((float) l.getLatitude(), (float) l.getLongitude(), (float) l.getAltitude(),
435: 					System.currentTimeMillis());
436: 			previousCorrectionValue = gf.getDeclination();
437: 		}
438: 		if (previousCorrectionValue != 360) {
439: 			val += previousCorrectionValue;
440: 		}
441: 		return val;
442: 	}
443: 
444: 	private float calcScreenOrientationCorrection(float val) {
445: 		if (currentScreenOrientation == 1) {
446: 			val += 90;
447: 		} else if (currentScreenOrientation == 2) {
448: 			val += 180;
449: 		} else if (currentScreenOrientation == 3) {
450: 			val -= 90;
451: 		}
452: 		return val;
453: 	}
454: 
455: 	private void filterCompassValue() {
456: 		if (heading == null && previousCompassIndA == 0) {
457: 			Arrays.fill(previousCompassValuesA, lastValSin);
458: 			Arrays.fill(previousCompassValuesB, lastValCos);
459: 			avgValSin = lastValSin;
460: 			avgValCos = lastValCos;
461: 		} else {
462: 			if (USE_KALMAN_FILTER) {
463: 				avgValSin = KALMAN_COEFFICIENT * lastValSin + avgValSin * (1 - KALMAN_COEFFICIENT);
464: 				avgValCos = KALMAN_COEFFICIENT * lastValCos + avgValCos * (1 - KALMAN_COEFFICIENT);
465: 			} else {
466: 				int l = previousCompassValuesA.length;
467: 				previousCompassIndA = (previousCompassIndA + 1) % l;
468: 				previousCompassIndB = (previousCompassIndB + 1) % l;
469: 				// update average
470: 				avgValSin = avgValSin + (-previousCompassValuesA[previousCompassIndA] + lastValSin) / l;
471: 				previousCompassValuesA[previousCompassIndA] = lastValSin;
472: 				avgValCos = avgValCos + (-previousCompassValuesB[previousCompassIndB] + lastValCos) / l;
473: 				previousCompassValuesB[previousCompassIndB] = lastValCos;
474: 			}
475: 		}
476: 	}
