545: 			r.setSpeed(l.getSpeed());
546: 		}
547: 		if (l.hasAltitude()) {
548: 			r.setAltitude(l.getAltitude());
549: 		}
550: 		if (l.hasBearing()) {
551: 			r.setBearing(l.getBearing());
