431: 	private float calcGeoMagneticCorrection(float val) {
432: 		net.osmand.Location l = getLastKnownLocation();
433: 		if (previousCorrectionValue == 360 && l != null) {
434: 			GeomagneticField gf = new GeomagneticField((float) l.getLatitude(), (float) l.getLongitude(), (float) l.getAltitude(),
435: 					System.currentTimeMillis());
436: 			previousCorrectionValue = gf.getDeclination();
437: 		}
438: 		if (previousCorrectionValue != 360) {
439: 			val += previousCorrectionValue;
440: 		}
441: 		return val;
442: 	}
443: 
444: 	private float calcScreenOrientationCorrection(float val) {
445: 		if (currentScreenOrientation == 1) {
446: 			val += 90;
447: 		} else if (currentScreenOrientation == 2) {
448: 			val += 180;
449: 		} else if (currentScreenOrientation == 3) {
450: 			val -= 90;
451: 		}
452: 		return val;
453: 	}
