539: 		if (VERSION.SDK_INT >= VERSION_CODES.O) {
540: 			if (inputLocation.hasVerticalAccuracy()) {
541: 				outputLocation.setVerticalAccuracy(inputLocation.getVerticalAccuracyMeters());
542: 			}
543: 		}
544: 		if (inputLocation.hasSpeed()) {
545: 			outputLocation.setSpeed(inputLocation.getSpeed());
546: 		}
547: 		if (inputLocation.hasAltitude()) {
548: 			outputLocation.setAltitude(inputLocation.getAltitude());
549: 		}
550: 		if (inputLocation.hasBearing()) {
551: 			outputLocation.setBearing(inputLocation.getBearing());
