345: 	public String getDestinationName(String lang, boolean transliterate, boolean direction) {
346: 		if (names != null) {
347: 			int[] nameKeys = names.keys();
348: 			Map<String, Integer> tagPriorities = new HashMap<>();
349: 			int tagPriority = 1;
350: 			if (!Algorithms.isEmpty(lang)) {
351: 				tagPriorities.put("destination:lang:" + lang + (direction ? ":forward" : ":backward"), tagPriority++);
352: 			}
353: 			tagPriorities.put("destination:" + (direction ? "forward" : "backward"), tagPriority++);
354: 			if (!Algorithms.isEmpty(lang)) {
355: 				tagPriorities.put("destination:lang:" + lang, tagPriority++);
356: 			}
357: 			tagPriorities.put("destination", tagPriority);
358: 
359: 			int highestPriorityNameKey = -1;
360: 			int highestPriority = Integer.MAX_VALUE;
361: 			for (int nameKey : nameKeys) {
362: 				if (region.routeEncodingRules.size() > nameKey) {
363: 					String tag = region.routeEncodingRules.get(nameKey).getTag();
364: 					Integer priority = tagPriorities.get(tag);
365: 					if (priority != null && priority < highestPriority) {
366: 						highestPriority = priority;
367: 						highestPriorityNameKey = nameKey;
368: 					}
369: 				}
370: 			}
371: 			if (highestPriorityNameKey > 0) {
372: 				String name = names.get(highestPriorityNameKey);
373: 				return transliterate ? TransliterationHelper.transliterate(name) : name;
374: 			}
