551: 	public static float parseSpeed(String v, float def) {
552: 		if (v.equals("none")) {
553: 			return RouteDataObject.NONE_MAX_SPEED;
554: 		} else {
555: 			int i = Algorithms.findFirstNumberEndIndex(v);
556: 			if (i > 0) {
557: 				float f = Float.parseFloat(v.substring(0, i));
558: 				f /= 3.6; // km/h -> m/s
559: 				if (v.contains("mph")) {
560: 					f *= 1.6;
561: 				}
562: 				return f;
563: 			}
564: 		}
565: 		return def;
566: 	}
