568: 	public static float parseLength(String v, float def) {
569: 		float f = 0;
570: 		// 14'10" 14 - inches, 10 feet
571: 		int i = Algorithms.findFirstNumberEndIndex(v);
572: 		if (i > 0) {
573: 			f += Float.parseFloat(v.substring(0, i));
574: 			String pref = v.substring(i, v.length()).trim();
575: 			float add = 0;
576: 			for (int ik = 0; ik < pref.length(); ik++) {
577: 				if (Algorithms.isDigit(pref.charAt(ik)) || pref.charAt(ik) == '.' || pref.charAt(ik) == '-') {
578: 					int first = Algorithms.findFirstNumberEndIndex(pref.substring(ik));
579: 					if (first != -1) {
580: 						add = parseLength(pref.substring(ik), 0);
581: 						pref = pref.substring(0, ik);
582: 					}
583: 					break;
584: 				}
585: 			}
586: 			if (pref.contains("km")) {
587: 				f *= 1000;
588: 			}
589: 			if (pref.contains("\"") || pref.contains("in")) {
590: 				f *= 0.0254;
591: 			} else if (pref.contains("\'") || pref.contains("ft") || pref.contains("feet")) {
