219: 	/**
220: 	 * @see <a href="http://alienryderflex.com/polygon/">Determining Whether A Point Is Inside A Complex Polygon</a>
221: 	 * @param point
222: 	 * @param polygon
223: 	 * @return true if the point is in the area of the polygon
224: 	 */
225: 	public static boolean isPointInsidePolygon(LatLon point,
226: 	                                           List<LatLon> polygon) {
227: 		double px = point.getLongitude();
228: 		double py = point.getLatitude();
229: 		boolean oddNodes = false;
230: 		for (int i = 0, j = polygon.size() - 1; i < polygon.size(); j = i++) {
231: 			double x1 = polygon.get(i).getLongitude();
232: 			double y1 = polygon.get(i).getLatitude();
233: 			double x2 = polygon.get(j).getLongitude();
234: 			double y2 = polygon.get(j).getLatitude();
235: 			if ((y1 < py && y2 >= py
236: 					|| y2 < py && y1 >= py)
237: 					&& (x1 <= px || x2 <= px)) {
238: 				if (x1 + (py - y1) / (y2 - y1) * (x2 - x1) < px) {
239: 					oddNodes = !oddNodes;
240: 				}
241: 			}
242: 		}
243: 		return oddNodes;
244: 	}
