455: 	public static int findFirstNumberEndIndex(String value) {
456: 		int i = 0;
457: 		if (value.length() > 0 && value.charAt(0) == '-') {
458: 			i++;
459: 		}
460: 		int state = 0; // 0 - no number, 1 - 1st digits, 2 - dot, 3 - last digits
461: 		while (i < value.length() && (isDigit(value.charAt(i)) || (value.charAt(i) == '.'))) {
462: 			if (value.charAt(i) == '.') {
463: 				if (state == 2) {
464: 					return i - 1;
465: 				}
466: 				if (state != 1) {
467: 					return -1;
468: 				}
469: 				state = 2;
470: 			} else {
471: 				if (state == 2) {
472: 					// last digits 
473: 					state = 3;
474: 				} else if (state == 0) {
475: 					// first digits started
476: 					state = 1;
477: 				}
478: 
479: 			}
480: 			i++;
481: 		}
482: 		if (state == 2) {
483: 			// invalid number like 40. correct to -> '40'
484: 			return i - 1;
485: 		}
486: 		if (state == 0) {
487: 			return -1;
488: 		}
489: 		return i;
490: 	}
