565: 	public static int readInt(InputStream in) throws IOException {
566: 		int ch1 = in.read();
567: 		int ch2 = in.read();
568: 		int ch3 = in.read();
569: 		int ch4 = in.read();
570: 		if ((ch1 | ch2 | ch3 | ch4) < 0)
571: 			throw new EOFException();
572: 		return ((ch1 << 24) + (ch2 << 16) + (ch3 << 8) + ch4);
573: 	}
