620: 			// Use a long to avoid rollovers on #ffXXXXXX
621: 			if (colorString.length() == 4) {
622: 				colorString = "#" +
623: 						colorString.charAt(1) + colorString.charAt(1) +
624: 						colorString.charAt(2) + colorString.charAt(2) +
625: 						colorString.charAt(3) + colorString.charAt(3);
626: 			}
627: 			long color = Long.parseLong(colorString.substring(1), 16);
628: 			if (colorString.length() == 7) {
629: 				// Set the alpha value
630: 				color |= 0x00000000ff000000;
631: 			} else if (colorString.length() != 9) {
632: 				throw new IllegalArgumentException("Unknown color " + colorString); //$NON-NLS-1$
633: 			}
634: 			return (int) color;
635: 		}
