1091: 
1092: 		// Given an input percentage (0.0-1.0) this will produce a colour from a "wide rainbow"
1093: 		// from purple (low) to red(high).  This is useful for producing value-based colourations (e.g., altitude)
1094: 
1095: 		double a = (1. - percent) * 5.;
1096: 		int X = (int) Math.floor(a);
1097: 		int Y = (int) (Math.floor(255 * (a - X)));
1098: 		switch (X) {
1099: 			case 0: return 0xFFFF0000 + (Y << 8);
1100: 			case 1: return 0xFF00FF00 + ((255 - Y) << 16);
1101: 			case 2: return 0xFF00FF00 + Y;
1102: 			case 3: return 0xFF0000FF + ((255 - Y) << 8);
1103: 			case 4: return 0xFF0000FF + (Y << 16);
1104: 		}
1105: 		return 0xFFFF00FF;
1106: 	}
