455: 	private void filterCompassValue() {
456: 		if (heading == null && previousCompassIndA == 0) {
457: 			Arrays.fill(previousCompassValuesA, lastValSin);
458: 			Arrays.fill(previousCompassValuesB, lastValCos);
459: 			avgValSin = lastValSin;
460: 			avgValCos = lastValCos;
461: 		} else {
462: 			if (USE_KALMAN_FILTER) {
463: 				avgValSin = KALMAN_COEFFICIENT * lastValSin + avgValSin * (1 - KALMAN_COEFFICIENT);
464: 				avgValCos = KALMAN_COEFFICIENT * lastValCos + avgValCos * (1 - KALMAN_COEFFICIENT);
465: 			} else {
466: 				int l = previousCompassValuesA.length;
467: 				previousCompassIndA = (previousCompassIndA + 1) % l;
468: 				previousCompassIndB = (previousCompassIndB + 1) % l;
469: 				// update average
470: 				avgValSin = avgValSin + (-previousCompassValuesA[previousCompassIndA] + lastValSin) / l;
