162: 	public void resumeAllUpdates() {
163: 		LOG.info(">>>> resumeAllUpdates");
164: 
165: 		registerOrUnregisterCompassListener(true);
166: 
167: 		if (app.getSettings().isInternetConnectionAvailable()) {
168: 			if (System.currentTimeMillis() - app.getSettings().AGPS_DATA_LAST_TIME_DOWNLOADED.get() > AGPS_TO_REDOWNLOAD) {
169: 				// force an updated check for internet connectivity here before destroying A-GPS-data
170: 				if (app.getSettings().isInternetConnectionAvailable(true)) {
171: 					redownloadAGPS();
172: 				}
173: 			}
174: 		}
175: 
176: 		if (isLocationPermissionAvailable(app)) {
177: 			LocationManager locationService = (LocationManager) app.getSystemService(LOCATION_SERVICE);
178: 			registerGpsStatusListener(locationService);
179: 			try {
180: 				locationServiceHelper.requestLocationUpdates(new LocationCallback() {
181: 					@Override
182: 					public void onLocationResult(@NonNull List<net.osmand.Location> locations) {
183: 						net.osmand.Location location = null;
184: 						if (!locations.isEmpty()) {
185: 							location = locations.get(locations.size() - 1);
186: 							if (useOnlyGPS() && location.hasAccuracy() &&
187: 									location.getAccuracy() > ACCURACY_FOR_GPX_AND_ROUTING) {
188: 								// fused provider could return network locations
189: 								return;
190: 							}
191: 							lastTimeGPSLocationFixed = System.currentTimeMillis();
192: 						}
193: 						if (!locationSimulation.isRouteAnimating()) {
194: 							setLocation(location);
195: 						}
196: 					}
197: 				});
198: 			} catch (SecurityException e) {
199: 				// Location service permission not granted
200: 			} catch (IllegalArgumentException e) {
201: 				// GPS location provider not available
202: 			}
203: 			// try to always ask for network provide : it is faster way to find location
204: 			if (locationServiceHelper.isNetworkLocationUpdatesSupported()) {
205: 				locationServiceHelper.requestNetworkLocationUpdates(new LocationCallback() {
206: 					@Override
207: 					public void onLocationResult(@NonNull List<net.osmand.Location> locations) {
208: 						if (!locations.isEmpty() && !useOnlyGPS() && !locationSimulation.isRouteAnimating()) {
209:  							setLocation(locations.get(locations.size() - 1));
210: 						}
211: 					}
212: 				});
213: 			}
214: 		}
215: 	}
