301: 	public synchronized void registerOrUnregisterCompassListener(boolean register) {
302: 		if (sensorRegistered && !register) {
303: 			Log.d(PlatformUtil.TAG, "Disable sensor");
304: 			((SensorManager) app.getSystemService(Context.SENSOR_SERVICE)).unregisterListener(this);
305: 			sensorRegistered = false;
306: 			heading = null;
307: 		} else if (!sensorRegistered && register) {
308: 			Log.d(PlatformUtil.TAG, "Enable sensor");
309: 			SensorManager sensorMgr = (SensorManager) app.getSystemService(Context.SENSOR_SERVICE);
310: 			if (app.getSettings().USE_MAGNETIC_FIELD_SENSOR_COMPASS.get() || !hasOrientationSensor(sensorMgr)) {
311: 				Sensor s = sensorMgr.getDefaultSensor(Sensor.TYPE_ACCELEROMETER);
312: 				if (s == null || !sensorMgr.registerListener(this, s, SensorManager.SENSOR_DELAY_UI)) {
313: 					Log.e(PlatformUtil.TAG, "Sensor accelerometer could not be enabled");
314: 				}
315: 				s = sensorMgr.getDefaultSensor(Sensor.TYPE_MAGNETIC_FIELD);
316: 				if (s == null || !sensorMgr.registerListener(this, s, SensorManager.SENSOR_DELAY_UI)) {
317: 					Log.e(PlatformUtil.TAG, "Sensor magnetic field could not be enabled");
318: 				}
319: 			} else {
320: 				Sensor s = sensorMgr.getDefaultSensor(Sensor.TYPE_ORIENTATION);
321: 				if (s == null || !sensorMgr.registerListener(this, s, SensorManager.SENSOR_DELAY_UI)) {
322: 					Log.e(PlatformUtil.TAG, "Sensor orientation could not be enabled.");
323: 					s = sensorMgr.getDefaultSensor(Sensor.TYPE_ROTATION_VECTOR);
324: 					if (s == null || !sensorMgr.registerListener(this, s, SensorManager.SENSOR_DELAY_UI)) {
325: 						Log.e(PlatformUtil.TAG, "Sensor rotation could not be enabled.");
326: 					}
327: 				}
328: 			}
329: 			sensorRegistered = true;
330: 		}
331: 	}
