528: 	public static net.osmand.Location convertLocation(Location location, OsmandApplication app) {
529: 		if (location == null) {
530: 			return null;
531: 		}
532: 		net.osmand.Location routeObject = new net.osmand.Location(location.getProvider());
533: 		routeObject.setLatitude(location.getLatitude());
534: 		routeObject.setLongitude(location.getLongitude());
535: 		routeObject.setTime(location.getTime());
536: 		if (location.hasAccuracy()) {
537: 			routeObject.setAccuracy(location.getAccuracy());
538: 		}
539: 		if (VERSION.SDK_INT >= VERSION_CODES.O) {
540: 			if (location.hasVerticalAccuracy()) {
541: 				routeObject.setVerticalAccuracy(location.getVerticalAccuracyMeters());
542: 			}
543: 		}
544: 		if (location.hasSpeed()) {
545: 			routeObject.setSpeed(location.getSpeed());
546: 		}
547: 		if (location.hasAltitude()) {
548: 			routeObject.setAltitude(location.getAltitude());
549: 		}
550: 		if (location.hasBearing()) {
551: 			routeObject.setBearing(location.getBearing());
552: 		}
553: 		if (location.hasAltitude() && app != null) {
554: 			double alt = location.getAltitude();
555: 			GeoidAltitudeCorrection geo = app.getResourceManager().getGeoidAltitudeCorrection();
556: 			if (geo != null) {
557: 				alt -= geo.getGeoidHeight(location.getLatitude(), location.getLongitude());
558: 				routeObject.setAltitude(alt);
559: 			}
560: 		}
561: 		return routeObject;
562: 	}
