565: 	private void scheduleCheckIfGpsLost(net.osmand.Location location) {
566: 		RoutingHelper routingHelper = app.getRoutingHelper();
567: 		if (location != null && routingHelper.isFollowingMode() && routingHelper.getLeftDistance() > 0
568: 				&& simulatePosition == null) {
569: 			long fixTime = location.getTime();
570: 			app.runInUIThreadAndCancelPrevious(LOST_LOCATION_MSG_ID, () -> {
571: 				net.osmand.Location lastKnown = getLastKnownLocation();
572: 				if (lastKnown != null && lastKnown.getTime() > fixTime) {
573: 					// false positive case, still strange how we got here with removeMessages
574: 					return;
575: 				}
576: 				gpsSignalLost = true;
577: 				if (routingHelper.isFollowingMode() && routingHelper.getLeftDistance() > 0
578: 						&& simulatePosition == null) {
579: 					routingHelper.getVoiceRouter().gpsLocationLost();
580: 					setLocation(null);
581: 				}
582: 			}, LOST_LOCATION_CHECK_DELAY);
583: 			app.runInUIThreadAndCancelPrevious(START_SIMULATE_LOCATION_MSG_ID, () -> {
584: 				net.osmand.Location lastKnown = getLastKnownLocation();
585: 				if (lastKnown != null && lastKnown.getTime() > fixTime) {
586: 					// false positive case, still strange how we got here with removeMessages
587: 					return;
588: 				}
589: 				// Speed 120kmh, 2 seconds -> 60 m
590: 				List<RouteSegmentResult> tunnel = routingHelper.getUpcomingTunnel(UPCOMING_TUNNEL_DISTANCE);
591: 				if (tunnel != null) {
592: 					simulatePosition = new SimulationProvider(location, tunnel);
593: 					simulatePosition.startSimulation();
594: 					simulatePositionImpl();
595: 				}
596: 			}, START_LOCATION_SIMULATION_DELAY);
597: 		}
598: 	}
