582: 		if (!dashboardOnMap.isVisible()) {
583: 			if (RenderInitErrorBottomSheet.shouldShow(settings, this)) {
584: 				SecondSplashScreenFragment.SHOW = false;
585: 				RenderInitErrorBottomSheet.showInstance(fragmentManager);
