595: 			} else if (HugerockPromoFragment.shouldShow(app)) {
596: 				SecondSplashScreenFragment.SHOW = false;
597: 				HugerockPromoFragment.showInstance(fragmentManager);
598: 			} else if (HMDPromoFragment.shouldShow(app)) {
599: 				SecondSplashScreenFragment.SHOW = false;
600: 				HMDPromoFragment.showInstance(fragmentManager);
601: 			}
602: 		}
603: 
604: 		boolean showStorageMigrationScreen = false;
605: 		if (fragmentsHelper.getFragment(WhatsNewDialogFragment.TAG) == null || WhatsNewDialogFragment.wasNotShown()) {
606: 			if (fragmentsHelper.getFragment(SharedStorageWarningFragment.TAG) == null && SharedStorageWarningFragment.dialogShowRequired(app)) {
607: 				showStorageMigrationScreen = true;
608: 				SecondSplashScreenFragment.SHOW = false;
609: 				SharedStorageWarningFragment.showInstance(getSupportFragmentManager(), true);
610: 			}
611: 		}
612: 
613: 		getMyApplication().getNotificationHelper().refreshNotifications();
614: 		// fixing bug with action bar appearing on android 2.3.3
615: 		if (getSupportActionBar() != null) {
616: 			getSupportActionBar().hide();
617: 		}
618: 
619: 		// for voice navigation. Lags behind routingAppMode changes, hence repeated under onCalculationFinish()
620: 		ApplicationMode routingAppMode = getRoutingHelper().getAppMode();
621: 		if (routingAppMode != null && settings.AUDIO_MANAGER_STREAM.getModeValue(routingAppMode) != null) {
622: 			setVolumeControlStream(settings.AUDIO_MANAGER_STREAM.getModeValue(routingAppMode));
623: 		}
624: 
625: 		applicationModeListener = prevAppMode -> app.runInUIThread(() -> {
626: 			if (settings.APPLICATION_MODE.get() != prevAppMode) {
627: 				settings.setLastKnownMapRotation(prevAppMode, getMapRotateTarget());
628: 				settings.setLastKnownMapElevation(prevAppMode, getMapElevationAngle());
629: 				updateApplicationModeSettings();
630: 			}
631: 		});
632: 		settings.APPLICATION_MODE.addListener(applicationModeListener);
633: 		updateApplicationModeSettings(!app.getPoiFilters().isShowingAnyPoi());
634: 
635: 
636: 		// if destination point was changed try to recalculate route
637: 		TargetPointsHelper targets = app.getTargetPointsHelper();
638: 		RoutingHelper routingHelper = app.getRoutingHelper();
639: 		if (routingHelper.isFollowingMode()
640: 				&& (!Algorithms.objectEquals(targets.getPointToNavigate().getLatLon(), routingHelper.getFinalLocation()) || !Algorithms
641: 				.objectEquals(targets.getIntermediatePointsLatLonNavigation(), routingHelper.getIntermediatePoints()))) {
642: 			targets.updateRouteAndRefresh(true);
643: 		}
644: 		app.getLocationProvider().resumeAllUpdates();
645: 
646: 		OsmandMapTileView mapView = getMapView();
647: 		if (settings.isLastKnownMapLocation()) {
648: 			LatLon l = settings.getLastKnownMapLocation();
649: 			mapView.setLatLon(l.getLatitude(), l.getLongitude());
650: 			mapView.setHeight(settings.getLastKnownMapHeight());
651: 			mapView.setZoomWithFloatPart(settings.getLastKnownMapZoom(), settings.getLastKnownMapZoomFloatPart());
652: 			mapView.initMapRotationByCompassMode();
653: 		}
654: 
655: 		settings.MAP_ACTIVITY_ENABLED = true;
656: 		LOG.info(">>>> MAP_ACTIVITY_ENABLED = true");
657: 
658: 		mapView.showAndHideMapPosition();
659: 
660: 		readLocationToShow();
661: 
662: 		PluginsHelper.checkInstalledMarketPlugins(app, this);
663: 		PluginsHelper.onMapActivityResume(this);
664: 
665: 		intentHelper.parseContentIntent();
666: 		mapView.refreshMap(true);
667: 
668: 		if (mapViewWithLayers != null) {
669: 			mapViewWithLayers.onResume();
670: 		}
671: 		app.getLauncherShortcutsHelper().updateLauncherShortcuts();
672: 		app.getDownloadThread().setUiActivity(this);
673: 
674: 		boolean routeWasFinished = routingHelper.isRouteWasFinished();
675: 		if (routeWasFinished && !DestinationReachedFragment.wasShown()) {
676: 			DestinationReachedFragment.show(this);
677: 		}
678: 
679: 		routingHelper.addListener(this);
680: 		app.getMapMarkersHelper().addListener(this);
681: 
682: 		if (System.currentTimeMillis() - time > 50) {
683: 			LOG.error("onResume for MapActivity took " + (System.currentTimeMillis() - time) + " ms");
684: 		}
685: 
686: 		boolean showOsmAndWelcomeScreen = true;
687: 		Intent intent = getIntent();
688: 		if (intent != null && intent.hasExtra(FirstUsageWizardFragment.SHOW_OSMAND_WELCOME_SCREEN)) {
689: 			showOsmAndWelcomeScreen = intent.getBooleanExtra(FirstUsageWizardFragment.SHOW_OSMAND_WELCOME_SCREEN, true);
690: 		}
691: 		boolean showWelcomeScreen = ((app.getAppInitializer().isFirstTime() && Version.isDeveloperVersion(app)) || !app.getResourceManager().isAnyMapInstalled())
692: 				&& settings.SHOW_OSMAND_WELCOME_SCREEN.get()
693: 				&& showOsmAndWelcomeScreen && !showStorageMigrationScreen;
694: 
695: 		if (!showWelcomeScreen && !MapPermissionsResultCallback.permissionDone && !app.getAppInitializer().isFirstTime()) {
696: 			if (!permissionsResultCallback.permissionAsked) {
697: 				if (app.isExternalStorageDirectoryReadOnly() && !showStorageMigrationScreen
698: 						&& fragmentManager.findFragmentByTag(SharedStorageWarningFragment.TAG) == null
699: 						&& fragmentManager.findFragmentByTag(SettingsScreenType.DATA_STORAGE.fragmentName) == null) {
700: 					if (AndroidUtils.hasPermission(this, Manifest.permission.WRITE_EXTERNAL_STORAGE)) {
701: 						Bundle args = new Bundle();
702: 						args.putBoolean(FIRST_USAGE, true);
703: 						BaseSettingsFragment.showInstance(this, SettingsScreenType.DATA_STORAGE, null, args, null);
704: 					} else {
