1029: 		settings.MAP_SCREEN_ORIENTATION.removeListener(mapScreenOrientationSettingListener);
1030: 		settings.USE_SYSTEM_SCREEN_TIMEOUT.removeListener(useSystemScreenTimeoutListener);
1031: 		if (!app.getRoutingHelper().isRouteWasFinished()) {
