491: 	private static void initModesParams(@NonNull OsmandApplication app) {
492: 		OsmandSettings settings = app.getSettings();
493: 		if (iconNameListener == null) {
494: 			iconNameListener = change -> {
495: 				List<ApplicationMode> modes = new ArrayList<>(allPossibleValues());
496: 				for (ApplicationMode mode : modes) {
497: 					mode.updateAppModeIcon();
498: 				}
499: 			};
500: 			settings.ICON_RES_NAME.addListener(iconNameListener);
501: 		}
502: 		for (ApplicationMode mode : allPossibleValues()) {
503: 			mode.app = app;
504: 			mode.updateAppModeIcon();
505: 		}
506: 
507: 		if (settings.APP_MODE_ORDER.isSetForMode(PUBLIC_TRANSPORT) && !settings.APP_MODE_ORDER.isSetForMode(TRAIN)) {
508: 			TRAIN.setOrder(PUBLIC_TRANSPORT.getOrder() + 1);
509: 		}
510: 		if (settings.APP_MODE_ORDER.isSetForMode(PEDESTRIAN)) {
511: 			if (!settings.APP_MODE_ORDER.isSetForMode(TRUCK)) {
512: 				TRUCK.setOrder(PEDESTRIAN.getOrder() + 1);
513: 			}
514: 			if (!settings.APP_MODE_ORDER.isSetForMode(MOTORCYCLE)) {
515: 				MOTORCYCLE.setOrder(PEDESTRIAN.getOrder() + 1);
516: 			}
517: 			if (!settings.APP_MODE_ORDER.isSetForMode(MOPED)) {
518: 				MOPED.setOrder(PEDESTRIAN.getOrder() + 1);
519: 			}
520: 		}
521: 		if (settings.APP_MODE_ORDER.isSetForMode(SKI) && !settings.APP_MODE_ORDER.isSetForMode(HORSE)) {
522: 			HORSE.setOrder(SKI.getOrder() + 1);
523: 		}
524: 	}
