539: 	public static void reorderAppModes() {
540: 		Comparator<ApplicationMode> comparator = (mode1, mode2) -> Integer.compare(mode1.getOrder(), mode2.getOrder());
541: 		Collections.sort(values, comparator);
542: 		Collections.sort(defaultValues, comparator);
543: 		Collections.sort(cachedFilteredValues, comparator);
544: 		updateAppModesOrder();
545: 	}
