556: 	private static void saveCustomAppModesToSettings(OsmandApplication app) {
557: 		OsmandSettings settings = app.getSettings();
558: 		StringBuilder stringBuilder = new StringBuilder();
559: 		Iterator<ApplicationMode> it = getCustomValues().iterator();
560: 		while (it.hasNext()) {
561: 			stringBuilder.append(it.next().getStringKey());
562: 			if (it.hasNext()) {
563: 				stringBuilder.append(",");
564: 			}
565: 		}
566: 		if (!stringBuilder.toString().equals(settings.CUSTOM_APP_MODES_KEYS.get())) {
567: 			settings.CUSTOM_APP_MODES_KEYS.set(stringBuilder.toString());
568: 		}
569: 	}
