662: 			Set<ApplicationMode> selectedModes = new LinkedHashSet<>(values(app));
663: 
664: 			StringBuilder builder = new StringBuilder(DEFAULT.getStringKey() + ",");
665: 			if (selected) {
666: 				selectedModes.add(appMode);
667: 			} else {
668: 				selectedModes.remove(appMode);
669: 				if (settings.APPLICATION_MODE.get() == appMode) {
670: 					settings.APPLICATION_MODE.resetToDefault();
671: 				}
672: 			}
673: 			for (ApplicationMode mode : selectedModes) {
674: 				builder.append(mode.getStringKey()).append(",");
675: 			}
676: 			settings.AVAILABLE_APP_MODES.set(builder.toString());
677: 			return true;
678: 		}
679: 		return false;
