124:     private static void computeDistanceAndBearing(double lat1, double lon1,
125:         double lat2, double lon2, float[] results) {
126:         // Based on http://www.ngs.noaa.gov/PUBS_LIB/inverse.pdf
127:         // using the "Inverse Formula" (section 4)
128:         int MAXITERS = 20;
129:         // Convert lat/long to radians
130:         lat1 *= Math.PI / 180.0;
131:         lat2 *= Math.PI / 180.0;
132:         lon1 *= Math.PI / 180.0;
133:         lon2 *= Math.PI / 180.0;
134: 
135:         double a = 6378137.0; // WGS84 major axis
136:         double b = 6356752.3142; // WGS84 semi-major axis
137:         double f = (a - b) / a;
138:         double aSqMinusBSqOverBSq = (a * a - b * b) / (b * b);
139: 
140:         double L = lon2 - lon1;
141:         double A = 0.0;
142:         double U1 = Math.atan((1.0 - f) * Math.tan(lat1));
143:         double U2 = Math.atan((1.0 - f) * Math.tan(lat2));
144: 
145:         double cosU1 = Math.cos(U1);
146:         double cosU2 = Math.cos(U2);
147:         double sinU1 = Math.sin(U1);
148:         double sinU2 = Math.sin(U2);
149:         double cosU1cosU2 = cosU1 * cosU2;
150:         double sinU1sinU2 = sinU1 * sinU2;
151: 
152:         double sigma = 0.0;
153:         double deltaSigma = 0.0;
154:         double cosSqAlpha = 0.0;
155:         double cos2SM = 0.0;
156:         double cosSigma = 0.0;
157:         double sinSigma = 0.0;
158:         double cosLambda = 0.0;
159:         double sinLambda = 0.0;
160: 
161:         double lambda = L; // initial guess
162:         for (int iter = 0; iter < MAXITERS; iter++) {
163:             double lambdaOrig = lambda;
164:             cosLambda = Math.cos(lambda);
165:             sinLambda = Math.sin(lambda);
166:             double t1 = cosU2 * sinLambda;
167:             double t2 = cosU1 * sinU2 - sinU1 * cosU2 * cosLambda;
168:             double sinSqSigma = t1 * t1 + t2 * t2; // (14)
169:             sinSigma = Math.sqrt(sinSqSigma);
170:             cosSigma = sinU1sinU2 + cosU1cosU2 * cosLambda; // (15)
171:             sigma = Math.atan2(sinSigma, cosSigma); // (16)
172:             double sinAlpha = (sinSigma == 0) ? 0.0 :
173:                 cosU1cosU2 * sinLambda / sinSigma; // (17)
174:             cosSqAlpha = 1.0 - sinAlpha * sinAlpha;
175:             cos2SM = (cosSqAlpha == 0) ? 0.0 :
176:                 cosSigma - 2.0 * sinU1sinU2 / cosSqAlpha; // (18)
177: 
178:             double uSquared = cosSqAlpha * aSqMinusBSqOverBSq; // defn
179:             A = 1 + (uSquared / 16384.0) * // (3)
180:                 (4096.0 + uSquared *
181:                  (-768 + uSquared * (320.0 - 175.0 * uSquared)));
182:             double B = (uSquared / 1024.0) * // (4)
183:                 (256.0 + uSquared *
184:                  (-128.0 + uSquared * (74.0 - 47.0 * uSquared)));
185:             double C = (f / 16.0) *
186:                 cosSqAlpha *
187:                 (4.0 + f * (4.0 - 3.0 * cosSqAlpha)); // (10)
188:             double cos2SMSq = cos2SM * cos2SM;
189:             deltaSigma = B * sinSigma * // (6)
190:                 (cos2SM + (B / 4.0) *
191:                  (cosSigma * (-1.0 + 2.0 * cos2SMSq) -
192:                   (B / 6.0) * cos2SM *
193:                   (-3.0 + 4.0 * sinSigma * sinSigma) *
194:                   (-3.0 + 4.0 * cos2SMSq)));
195: 
196:             lambda = L +
197:                 (1.0 - C) * f * sinAlpha *
198:                 (sigma + C * sinSigma *
199:                  (cos2SM + C * cosSigma *
200:                   (-1.0 + 2.0 * cos2SM * cos2SM))); // (11)
201: 
202:             double delta = (lambda - lambdaOrig) / lambda;
203:             if (Math.abs(delta) < 1.0e-12) {
204:                 break;
205:             }
206:         }
207: 
208:         float distance = (float) (b * A * (sigma - deltaSigma));
209:         results[0] = distance;
210:         if (results.length > 1) {
211:             float initialBearing = (float) Math.atan2(cosU2 * sinLambda,
212:                 cosU1 * sinU2 - sinU1 * cosU2 * cosLambda);
213:             initialBearing *= 180.0 / Math.PI;
214:             results[1] = initialBearing;
215:             if (results.length > 2) {
216:                 float finalBearing = (float) Math.atan2(cosU1 * sinLambda,
217:                     -sinU1 * cosU2 + cosU1 * sinU2 * cosLambda);
218:                 finalBearing *= 180.0 / Math.PI;
219:                 results[2] = finalBearing;
220:             }
221:         }
222:     }
