224:     /**
225:      * Computes the approximate distance in meters between two
226:      * locations, and optionally the initial and final bearings of the
227:      * shortest path between them.  Distance and bearing are defined using the
228:      * WGS84 ellipsoid.
229:      *
230:      * <p> The computed distance is stored in results[0].  If results has length
231:      * 2 or greater, the initial bearing is stored in results[1]. If results has
232:      * length 3 or greater, the final bearing is stored in results[2].
233:      *
234:      * @param startLatitude the starting latitude
235:      * @param startLongitude the starting longitude
236:      * @param endLatitude the ending latitude
237:      * @param endLongitude the ending longitude
238:      * @param results an array of floats to hold the results
239:      *
240:      * @throws IllegalArgumentException if results is null or has length < 1
241:      */
242:     public static void distanceBetween(double startLatitude, double startLongitude,
243:         double endLatitude, double endLongitude, float[] results) {
244:         if (results == null || results.length < 1) {
245:             throw new IllegalArgumentException("results is null or has length < 1");
246:         }
247:         computeDistanceAndBearing(startLatitude, startLongitude,
248:             endLatitude, endLongitude, results);
249:     }
