251:     /**
252:      * Returns the approximate distance in meters between this
253:      * location and the given location.  Distance is defined using
254:      * the WGS84 ellipsoid.
255:      *
256:      * @param dest the destination location
257:      * @return the approximate distance in meters
258:      */
259:     public float distanceTo(Location dest) {
260:         // See if we already have the result
261:         synchronized (mResults) {
262:             if (mLatitude != mLat1 || mLongitude != mLon1 ||
263:                 dest.mLatitude != mLat2 || dest.mLongitude != mLon2) {
264:                 computeDistanceAndBearing(mLatitude, mLongitude,
265:                     dest.mLatitude, dest.mLongitude, mResults);
266:                 mLat1 = mLatitude;
267:                 mLon1 = mLongitude;
268:                 mLat2 = dest.mLatitude;
269:                 mLon2 = dest.mLongitude;
270:                 mDistance = mResults[0];
271:                 mInitialBearing = mResults[1];
272:             }
273:             return mDistance;
274:         }
275:     }
