709: 	private void calculateAlarms(RouteCalculationResult route, List<LocationPointWrapper> array, ApplicationMode mode) {
710: 		if (!settings.SHOW_ROUTING_ALARMS.getModeValue(mode)) {
711: 			return;
712: 		}
713: 		AlarmInfo prevSpeedCam = null;
714: 		AlarmInfo prevRailway = null;
715: 		for (AlarmInfo alarmInfo : route.getAlarmInfo()) {
716: 			AlarmInfoType type = alarmInfo.getType();
717: 			if (type == SPEED_CAMERA) {
718: 				if (settings.SHOW_CAMERAS.getModeValue(mode) || settings.SPEAK_SPEED_CAMERA.getModeValue(mode)) {
719: 					// ignore double speed cams
720: 					if (prevSpeedCam == null || MapUtils.getDistance(prevSpeedCam.getLatitude(), prevSpeedCam.getLongitude(),
721: 							alarmInfo.getLatitude(), alarmInfo.getLongitude()) >= DISTANCE_IGNORE_DOUBLE_SPEEDCAMS) {
722: 						addPointWrapper(alarmInfo, array, settings.SPEAK_SPEED_CAMERA.getModeValue(mode));
723: 						prevSpeedCam = alarmInfo;
724: 					}
725: 				}
726: 			} else if (type == TUNNEL) {
727: 				if (settings.SHOW_TUNNELS.getModeValue(mode) || settings.SPEAK_TUNNELS.getModeValue(mode)) {
728: 					addPointWrapper(alarmInfo, array, settings.SPEAK_TUNNELS.getModeValue(mode));
729: 				}
730: 			} else if (type == PEDESTRIAN) {
731: 				if (settings.SHOW_PEDESTRIAN.getModeValue(mode) || settings.SPEAK_PEDESTRIAN.getModeValue(mode)) {
732: 					addPointWrapper(alarmInfo, array, settings.SPEAK_PEDESTRIAN.getModeValue(mode));
733: 				}
734: 			} else if (type == RAILWAY) {
735: 				if (prevRailway == null || MapUtils.getDistance(prevRailway.getLatitude(), prevRailway.getLongitude(),
736: 						alarmInfo.getLatitude(), alarmInfo.getLongitude()) >= DISTANCE_IGNORE_DOUBLE_RAILWAYS) {
737: 					addPointWrapper(alarmInfo, array, settings.SPEAK_TRAFFIC_WARNINGS.getModeValue(mode));
738: 					prevRailway = alarmInfo;
