373: 		AlarmInfo speedAlarm = null;
374: 		if (mxspeed != 0 && loc != null && loc.hasSpeed() && mxspeed != RouteDataObject.NONE_MAX_SPEED) {
375: 			if (loc.getSpeed() > mxspeed + delta) {
376: 				int speed;
