586: 	protected void recalculatePoints(RouteCalculationResult route, int type, List<List<LocationPointWrapper>> locationPoints) {
587: 		if (route == null || route.isEmpty()) {
588: 			return;
589: 		}
590: 		boolean all = type == -1;
591: 		appMode = settings.getApplicationMode();
592: 		boolean showWaypoints = settings.SHOW_WPT.get(); // global
593: 		boolean announceWaypoints = settings.ANNOUNCE_WPT.get(); // global
