357: 		} else if (preference instanceof StringPreference stringPref) {
358: 			if (value instanceof String || (value == null && stringPref.isNullSupported(mode))) {
359: 				return stringPref.setModeValue(mode, (String) value);
360: 			}
361: 		} else {
362: 			if (value instanceof String) {
363: 				value = preference.parseString((String) value);
