744: 		if (!globalIds.isEmpty()) {
745: 			removeFromGlobalPreferences(globalIds.toArray(new String[] {}));
746: 		}
747: 		if (!profileIds.isEmpty()) {
748: 			removeFromModePreferences(profileIds.toArray(new String[] {}));
749: 		}
