100: 			if ("speed_camera".equals(ruleType.getValue())) {
101: 				alarmInfo = new AlarmInfo(SPEED_CAMERA, locationIndex);
102: 			} else if ("stop".equals(ruleType.getValue())) {
103: 				alarmInfo = new AlarmInfo(STOP, locationIndex);
