106: 			if ("toll_booth".equals(ruleType.getValue())) {
107: 				alarmInfo = new AlarmInfo(TOLL_BOOTH, locationIndex);
108: 			} else if ("border_control".equals(ruleType.getValue())) {
109: 				alarmInfo = new AlarmInfo(BORDER_CONTROL, locationIndex);
110: 			}
111: 		} else if ("traffic_calming".equals(ruleType.getTag())) {
112: 			alarmInfo = new AlarmInfo(TRAFFIC_CALMING, locationIndex);
113: 		} else if ("hazard".equals(ruleType.getTag())) {
114: 			alarmInfo = new AlarmInfo(HAZARD, locationIndex);
115: 		} else if ("railway".equals(ruleType.getTag()) && "level_crossing".equals(ruleType.getValue())) {
116: 			alarmInfo = new AlarmInfo(RAILWAY, locationIndex);
117: 		} else if ("crossing".equals(ruleType.getTag()) && "uncontrolled".equals(ruleType.getValue())) {
118: 			alarmInfo = new AlarmInfo(PEDESTRIAN, locationIndex);
119: 		}
