129: 		}
130: 		// 1 level of priorities
131: 		if (time < 6 || distance < 75 || type == SPEED_LIMIT) {
132: 			return type.getPriority();
133: 		}
134: 		if (type == SPEED_CAMERA && (time < 15 || distance < 150)) {
135: 			return type.getPriority();
136: 		}
137: 		if (type == TOLL_BOOTH && (time < 30 || distance < 500)) {
138: 			return type.getPriority();
139: 		}
140: 		// 2nd level
141: 		if (time < 7 || distance < 100) {
142: 			return type.getPriority() + MAXIMUM.getPriority();
143: 		}
144: 		return Integer.MAX_VALUE;
145: 	}
