571: 	public static class TileBoxRequest {
572: 		private final int left;
573: 		private final int top;
574: 		private final int right;
575: 		private final int bottom;
576: 		private final int width;
577: 		private final int height;
578: 		private final int zoom;
579: 		private final QuadRect latLonBounds;
580: 
581: 		public TileBoxRequest(@NonNull RotatedTileBox tileBox) {
582: 			zoom = tileBox.getZoom();
583: 
584: 			QuadRect tilesRect = tileBox.getTileBounds();
585: 			left = (int) Math.floor(tilesRect.left);
586: 			top = (int) Math.floor(tilesRect.top);
587: 			right = (int) Math.ceil(tilesRect.right);
588: 			bottom = (int) Math.ceil(tilesRect.bottom);
589: 			width = (int) Math.ceil(tilesRect.right - left);
590: 			height = (int) Math.ceil(tilesRect.bottom - top);
591: 
592: 			latLonBounds = new QuadRect(
593: 					MapUtils.getLongitudeFromTile(zoom, alignTile(left)),
594: 					MapUtils.getLatitudeFromTile(zoom, alignTile(top)),
595: 					MapUtils.getLongitudeFromTile(zoom, alignTile(right)),
596: 					MapUtils.getLatitudeFromTile(zoom, alignTile(bottom)));
597: 		}
598: 
599: 		private TileBoxRequest(@NonNull TileBoxRequest request, int tileExtentX, int tileExtentY) {
600: 			zoom = request.zoom;
601: 
602: 			left = alignTile(request.left - tileExtentX);
603: 			top = alignTile(request.top - tileExtentY);
604: 			right = alignTile(request.right + tileExtentX);
605: 			bottom = alignTile(request.bottom + tileExtentY);
606: 			width = right - left;
607: 			height = bottom - top;
608: 
609: 			latLonBounds = new QuadRect(
610: 					MapUtils.getLongitudeFromTile(zoom, alignTile((double) left)),
611: 					MapUtils.getLatitudeFromTile(zoom, alignTile((double) top)),
612: 					MapUtils.getLongitudeFromTile(zoom, alignTile((double) right)),
613: 					MapUtils.getLatitudeFromTile(zoom, alignTile((double) bottom)));
614: 		}
615: 
616: 		private double alignTile(double tile) {
617: 			if (tile < 0) {
618: 				return 0;
619: 			}
620: 			if (tile >= MapUtils.getPowZoom(zoom)) {
621: 				return MapUtils.getPowZoom(zoom) - .000001;
622: 			}
623: 			return tile;
624: 		}
625: 
626: 		private int alignTile(int tile) {
627: 			return tile < 0 ? 0 : Math.min(tile, (int) MapUtils.getPowZoom(zoom));
628: 		}
