792: 			LinkedList<WeakReference<DataReadyCallback>> ncall = new LinkedList<>(callbacks);
793: 			Iterator<WeakReference<DataReadyCallback>> it = ncall.iterator();
794: 			while (it.hasNext()) {
795: 				DataReadyCallback c = it.next().get();
796: 				if (c == callback) {
