866: 		@SuppressLint("StaticFieldLeak")
867: 		public class Task extends AsyncTask<Object, Object, Pair<T, T>> {
868: 			private final RotatedTileBox originalBox;
869: 			private final RotatedTileBox extendedBox;
870: 			private final TileBoxRequest originalBoxRequest;
871: 			private final TileBoxRequest extendedBoxRequest;
872: 
873: 			public Task(@NonNull RotatedTileBox originalBox, @NonNull RotatedTileBox extendedBox) {
874: 				this.originalBox = originalBox;
875: 				this.extendedBox = extendedBox;
876: 				this.originalBoxRequest = null;
877: 				this.extendedBoxRequest = null;
878: 			}
879: 
880: 			public Task(@NonNull TileBoxRequest originalBoxRequest, @NonNull TileBoxRequest extendedBoxRequest) {
881: 				this.originalBoxRequest = originalBoxRequest;
882: 				this.extendedBoxRequest = extendedBoxRequest;
883: 				this.originalBox = null;
884: 				this.extendedBox = null;
885: 			}
886: 
887: 			public RotatedTileBox getOriginalBox() {
888: 				return originalBox;
889: 			}
890: 
891: 			public RotatedTileBox getExtendedBox() {
892: 				return extendedBox;
893: 			}
894: 
895: 			public TileBoxRequest getOriginalBoxRequest() {
896: 				return originalBoxRequest;
897: 			}
898: 
899: 			public TileBoxRequest getExtendedBoxRequest() {
900: 				return extendedBoxRequest;
901: 			}
902: 
903: 			@Override
904: 			protected Pair<T, T> doInBackground(Object... params) {
905: 				if (extendedBoxRequest != null) {
906: 					if (queriedRequestContains(queriedRequest, extendedBoxRequest)) {
907: 						return null;
908: 					}
909: 					return calculateResult(extendedBoxRequest.getLatLonBounds(), extendedBoxRequest.getZoom());
910: 				} else {
911: 					if (queriedBoxContains(queriedBox, extendedBox)) {
912: 						return null;
913: 					}
914: 					QuadRect bounds = extendedBox.getLatLonBounds();
915: 					return bounds != null ? calculateResult(bounds, extendedBox.getZoom()) : null;
916: 				}
917: 			}
918: 
919: 			@Override
920: 			protected void onPreExecute() {
921: 				currentTask = this;
922: 				layerOnPreExecute();
923: 			}
924: 
925: 			@Override
926: 			protected void onPostExecute(Pair<T, T> result) {
927: 				if (result != null && result.first != null) {
928: 					queriedBox = extendedBox;
929: 					queriedRequest = extendedBoxRequest;
930: 					results = result.first;
931: 					displayedResults = result.second;
932: 				}
933: 				currentTask = null;
934: 				if (pendingTask != null) {
935: 					executeTaskInBackground(pendingTask);
936: 					pendingTask = null;
937: 				} else {
938: 					fireDataReadyCallback(results, displayedResults);
939: 					layerOnPostExecute();
940: 				}
941: 			}
942: 		}
