999: 			density = mapView.isCarView() ? mapView.getCarViewDensity() : tileBox.getDensity();
1000: 			int hsh = calculateHash(rrs, isNight, density);
1001: 			if (hsh != cachedHash) {
1002: 				cachedHash = hsh;
1003: 				if (rrs != null) {
1004: 					RenderingRuleSearchRequest req = new RenderingRuleSearchRequest(rrs);
1005: 					req.setBooleanFilter(rrs.PROPS.R_NIGHT_MODE, isNight);
1006: 					if (req.searchRenderingAttribute(renderingAttribute)) {
1007: 						RenderingContext rc = new OsmandRenderer.RenderingContext(app);
1008: 						rc.setDensityValue(density);
1009: 						// cachedColor = req.getIntPropertyValue(rrs.PROPS.R_COLOR);
1010: 						renderer.updatePaint(req, paint, 0, false, rc);
1011: 						isPaint2 = renderer.updatePaint(req, paint2, 1, false, rc);
1012: 						if (paint2.getStrokeWidth() == 0 && defaultWidth2 != 0) {
1013: 							paint2.setStrokeWidth(defaultWidth2);
1014: 						}
1015: 						isPaint3 = renderer.updatePaint(req, paint3, 2, false, rc);
1016: 						if (paint3.getStrokeWidth() == 0 && defaultWidth3 != 0) {
1017: 							paint3.setStrokeWidth(defaultWidth3);
1018: 						}
1019: 						isPaint_1 = renderer.updatePaint(req, paint_1, -1, false, rc);
1020: 						if (paint_1.getStrokeWidth() == 0 && defaultWidth_1 != 0) {
1021: 							paint_1.setStrokeWidth(defaultWidth_1);
1022: 						}
1023: 						isShadowPaint = req.isSpecified(rrs.PROPS.R_SHADOW_RADIUS);
1024: 						if (isShadowPaint) {
1025: 							ColorFilter cf = new PorterDuffColorFilter(
1026: 									req.getIntPropertyValue(rrs.PROPS.R_SHADOW_COLOR), Mode.SRC_IN);
1027: 							shadowPaint.setColorFilter(cf);
1028: 							shadowPaint.setStrokeWidth(paint.getStrokeWidth() + defaultShadowWidthExtent
1029: 									* rc.getComplexValue(req, rrs.PROPS.R_SHADOW_RADIUS));
1030: 						}
1031: 					} else {
1032: 						System.err.println("Rendering attribute route is not found !");
1033: 					}
1034: 					updateDefaultColor(paint, defaultColor);
1035: 					if (paint.getStrokeWidth() == 0 && defaultWidth != 0) {
1036: 						paint.setStrokeWidth(defaultWidth);
1037: 					}
1038: 					customColorPaint = new Paint(paint);
1039: 				}
1040: 				return true;
