172: 	public float[] calculateHeightArray(LatLon currentLocation) {
173: 		if (heightDistanceArray != null) {
174: 			return heightDistanceArray;
175: 		}
176: 		int startHeight = Algorithms.parseIntSilently(getValue("osmand_ele_start"), HEIGHT_UNDEFINED);
177: 		int endHeight = Algorithms.parseIntSilently(getValue("osmand_ele_end"), startHeight);
178: 		if (startHeight == HEIGHT_UNDEFINED) {
179: 			heightDistanceArray = new float[0];
180: 			return heightDistanceArray;
181: 		}
182: 
183: 		heightDistanceArray = new float[2 * getPointsLength()];
184: 		double plon = 0;
185: 		double plat = 0;
186: 		float prevHeight = startHeight;
187: 		heightByCurrentLocation = Float.NaN;
188: 		double prevDistance = 0;
189: 		for (int k = 0; k < getPointsLength(); k++) {
190: 			double lon = MapUtils.get31LongitudeX(getPoint31XTile(k));
191: 			double lat = MapUtils.get31LatitudeY(getPoint31YTile(k));
192: 			if (k > 0) {
193: 				double dd = MapUtils.getDistance(plat, plon, lat, lon);
194: 				float height = HEIGHT_UNDEFINED;
195: 				if (k == getPointsLength() - 1) {
196: 					height = endHeight;
197: 				} else {
198: 					String asc = getValue(k, "osmand_ele_asc");
199: 					if (asc != null && asc.length() > 0) {
200: 						height = (prevHeight + Float.parseFloat(asc));
201: 					} else {
202: 						String desc = getValue(k, "osmand_ele_desc");
203: 						if (desc != null && desc.length() > 0) {
204: 							height = (prevHeight - Float.parseFloat(desc));
205: 						}
206: 					}
207: 				}
208: 				heightDistanceArray[2 * k] = (float) dd;
209: 				heightDistanceArray[2 * k + 1] = height;
210: 
211: 				if (currentLocation != null) {
212: 					double distance = MapUtils.getDistance(currentLocation, lat, lon);
213: 					if (height != HEIGHT_UNDEFINED && distance < prevDistance) {
214: 						prevDistance = distance;
215: 						heightByCurrentLocation = height;
216: 					}
217: 				}
218: 
219: 				if (height != HEIGHT_UNDEFINED) {
220: 					// interpolate undefined
221: 					double totalDistance = dd;
222: 					int startUndefined = k;
223: 					while (startUndefined - 1 >= 0 && heightDistanceArray[2 * (startUndefined - 1) + 1] == HEIGHT_UNDEFINED) {
224: 						startUndefined--;
225: 						totalDistance += heightDistanceArray[2 * (startUndefined)];
226: 					}
227: 					if (totalDistance > 0) {
228: 						double angle = (height - prevHeight) / totalDistance;
229: 						for (int j = startUndefined; j < k; j++) {
230: 							heightDistanceArray[2 * j + 1] = (float) ((heightDistanceArray[2 * j] * angle) + heightDistanceArray[2 * j - 1]);
231: 						}
232: 					}
233: 					prevHeight = height;
234: 				}
235: 
236: 			} else {
237: 				heightDistanceArray[0] = 0;
238: 				heightDistanceArray[1] = startHeight;
239: 			}
240: 			plat = lat;
241: 			plon = lon;
242: 			if (currentLocation != null) {
243: 				prevDistance = MapUtils.getDistance(currentLocation, plat, plon);
244: 			}
245: 		}
246: 		return heightDistanceArray;
247: 	}
