604: 	public static float parseWeightInTon(String v, float def) {
605: 		int i = Algorithms.findFirstNumberEndIndex(v);
606: 		if (i > 0) {
607: 			float f = Float.parseFloat(v.substring(0, i));
608: 			if (v.contains("\"") || v.contains("lbs")) {
609: 				// lbs -> kg -> ton
610: 				f = (f * 0.4535f) / 1000f;
611: 			}
612: 			return f;
613: 		}
614: 		return def;
615: 	}
