942: 	public double directionRoute(int startPoint, boolean plus, float dist) {
943: 		int x = getPoint31XTile(startPoint);
944: 		int y = getPoint31YTile(startPoint);
945: 		int nx = startPoint;
946: 		int px = x;
947: 		int py = y;
948: 		double total = 0;
949: 		do {
950: 			if (plus) {
951: 				nx++;
952: 				if (nx >= getPointsLength()) {
953: 					break;
954: 				}
955: 			} else {
956: 				nx--;
957: 				if (nx < 0) {
958: 					break;
959: 				}
960: 			}
961: 			px = getPoint31XTile(nx);
962: 			py = getPoint31YTile(nx);
963: 			// translate into meters
964: 			total += simplifyDistance(x, y, px, py);
965: 		} while (total < dist);
966: 		return -Math.atan2(x - px, y - py);
967: 	}
