350:     private static String simplifyFileName(String filename) {
351:         String lc = filename.toLowerCase();
352:         if (lc.contains(".")) {
353:             lc = lc.substring(0, lc.indexOf("."));
354:         }
355:         if (lc.endsWith("_" + IndexConstants.BINARY_MAP_VERSION)) {
356: 			lc = lc.substring(0, lc.length() - ("_" + IndexConstants.BINARY_MAP_VERSION).length());
357: 		}
358:         boolean hasTimestampEnd = false;
359:         for (int i = 0; i < lc.length(); i++) {
360:             if (lc.charAt(i) >= '0' && lc.charAt(i) <= '9') {
361:                 hasTimestampEnd = true;
362:                 break;
363:             }
364:         }
365:         if (!hasTimestampEnd) {
366:             lc += "_00_00_00";
367:         }
368:         return lc;
369:     }
