302: 	// TODO doesn't look correct
303: 	@SuppressWarnings("unchecked")
304: 	public boolean setPreference(String key, Object value, ApplicationMode mode) {
305: 		OsmandPreference<?> preference = registeredPreferences.get(key);
306: 		if (preference == null) {
307: 			return false;
308: 		}
309: 		if (preference == APPLICATION_MODE) {
310: 			if (value instanceof String appModeKey) {
311: 				ApplicationMode appMode = ApplicationMode.valueOfStringKey(appModeKey, null);
312: 				if (appMode != null) {
313: 					return setApplicationMode(appMode);
314: 				}
315: 			}
316: 		} else if (preference == DEFAULT_APPLICATION_MODE) {
317: 			if (value instanceof String appModeKey) {
318: 				ApplicationMode appMode = ApplicationMode.valueOfStringKey(appModeKey, null);
319: 				if (appMode != null) {
320: 					return DEFAULT_APPLICATION_MODE.setPreference(appMode);
321: 				}
322: 			}
323: 		} else if (preference instanceof EnumStringPreference enumPref) {
324: 			if (value instanceof String) {
325: 				Enum<?> enumValue = enumPref.parseString((String) value);
326: 				if (enumValue != null) {
327: 					return enumPref.setModePreferenceValue(mode, enumValue);
328: 				}
329: 				return false;
330: 			} else if (value instanceof Enum) {
331: 				return enumPref.setModePreferenceValue(mode, value);
332: 			} else if (value instanceof Integer) {
333: 				int newVal = (Integer) value;
334: 				if (newVal >= 0 && newVal < enumPref.getValues().length) {
335: 					Enum<?> enumValue = enumPref.getValues()[newVal];
336: 					return enumPref.setModePreferenceValue(mode, enumValue);
337: 				}
338: 				return false;
339: 			}
340: 		} else if (preference instanceof ListStringPreference listStringPreference) {
341: 			if (value instanceof List<?> || (value == null && listStringPreference.isNullSupported(mode))) {
342: 				if (value == null) {
343: 					listStringPreference.setStringsListForProfile(mode, null);
344: 				} else {
345: 					List<?> list = (List<?>) value;
346: 					boolean isListOfString = list.stream().allMatch(element -> element instanceof String);
347: 					if (isListOfString) {
348: 						List<String> listOfString = (List<String>) list;
349: 						listStringPreference.setStringsListForProfile(mode, listOfString);
350: 					}
351: 				}
352: 			}
353: 			if (value instanceof String) {
354: 				return listStringPreference.setModePreferenceValue(mode, (String) value);
355: 			}
356: 		} else if (preference instanceof StringPreference stringPref) {
357: 			if (value instanceof String || (value == null && stringPref.isNullSupported(mode))) {
358: 				return stringPref.setModePreferenceValue(mode, (String) value);
359: 			}
360: 		} else {
361: 			if (value instanceof String) {
362: 				value = preference.parseString((String) value);
363: 			}
364: 			if (preference instanceof BooleanPreference) {
365: 				if (value instanceof Boolean) {
366: 					return ((BooleanPreference) preference).setModePreferenceValue(mode, (Boolean) value);
367: 				}
368: 			} else if (preference instanceof FloatPreference) {
369: 				if (value instanceof Float) {
370: 					return ((FloatPreference) preference).setModePreferenceValue(mode, (Float) value);
371: 				}
372: 			} else if (preference instanceof IntPreference) {
373: 				if (value instanceof Integer) {
374: 					return ((IntPreference) preference).setModePreferenceValue(mode, (Integer) value);
375: 				}
376: 			} else if (preference instanceof LongPreference) {
377: 				if (value instanceof Long) {
378: 					return ((LongPreference) preference).setModePreferenceValue(mode, (Long) value);
379: 				}
380: 			} else if (preference instanceof ContextMenuItemsPreference) {
381: 				if (value instanceof ContextMenuItemsSettings) {
382: 					return ((ContextMenuItemsPreference) preference).setModePreferenceValue(mode, (ContextMenuItemsSettings) value);
383: 				}
384: 			}
385: 		}
386: 		return false;
387: 	}
