487: 	public ApplicationMode getSwitchedAppMode(ApplicationMode selectedMode, boolean next) {
488: 		List<ApplicationMode> enabledModes = ApplicationMode.values(ctx);
489: 		int indexOfCurrent = enabledModes.indexOf(selectedMode);
490: 		int indexOfNext;
491: 		if (next) {
492: 			indexOfNext = indexOfCurrent < enabledModes.size() - 1 ? indexOfCurrent + 1 : 0;
493: 		} else {
494: 			indexOfNext = indexOfCurrent > 0 ? indexOfCurrent - 1 : enabledModes.size() - 1;
495: 		}
496: 		return enabledModes.get(indexOfNext);
497: 	}
