892: 			set.add(pluginId);
893: 		} else {
894: 			set.remove(pluginId);
895: 			set.add("-" + pluginId);
896: 		}
897: 		StringBuilder serialization = new StringBuilder();
898: 		Iterator<String> it = set.iterator();
899: 		while (it.hasNext()) {
900: 			serialization.append(it.next());
901: 			if (it.hasNext()) {
902: 				serialization.append(",");
903: 			}
904: 		}
905: 		if (!serialization.toString().equals(PLUGINS.get())) {
906: 			return PLUGINS.setPreference(serialization.toString());
907: 		}
908: 		return false;
909: 	}
