2053: 
2054: 		Iterator<String> iterator = pages.iterator();
2055: 		while (iterator.hasNext()) {
2056: 			boolean pageSeparatorAdded = false;
2057: 			String page = iterator.next();
2058: 			for (String id : page.split(WIDGET_SEPARATOR)) {
2059: 				if (WidgetType.isComplexWidget(id)) {
2060: 					pageSeparatorAdded = true;
2061: 					builder.append(id).append(PAGE_SEPARATOR);
2062: 				} else {
2063: 					pageSeparatorAdded = false;
2064: 					builder.append(id).append(WIDGET_SEPARATOR);
2065: 				}
2066: 			}
2067: 			if (iterator.hasNext() && !pageSeparatorAdded) {
2068: 				builder.append(PAGE_SEPARATOR);
2069: 			}
2070: 		}
2071: 		return builder.toString();
2072: 	}
