2198: 	public Map<String, String> getTileSourceEntries(boolean sqlite) {
2199: 		Map<String, String> map = new LinkedHashMap<String, String>();
2200: 		File dir = ctx.getAppPath(IndexConstants.TILES_INDEX_DIR);
2201: 		if (dir != null && dir.canRead()) {
2202: 			File[] files = dir.listFiles();
2203: 			if (files != null) {
2204: 				Arrays.sort(files, (f1, f2) -> {
2205: 					if (f1.lastModified() > f2.lastModified()) {
2206: 						return -1;
2207: 					} else if (f1.lastModified() == f2.lastModified()) {
2208: 						return 0;
2209: 					}
2210: 					return 1;
2211: 				});
2212: 				for (File f : files) {
2213: 					String fileName = f.getName();
2214: 					if (fileName.endsWith(SQLITE_EXT)) {
2215: 						if (sqlite) {
2216: 							map.put(fileName, getTileSourceTitle(fileName));
2217: 						}
2218: 					} else if (f.isDirectory() && !fileName.equals(IndexConstants.TEMP_SOURCE_TO_LOAD)
2219: 							&& !fileName.startsWith(".")) {
2220: 						map.put(fileName, fileName);
2221: 					}
2222: 				}
2223: 			}
2224: 		}
2225: 		for (TileSourceTemplate l : TileSourceManager.getKnownSourceTemplates()) {
2226: 			if (!l.isHidden()) {
2227: 				map.put(l.getName(), l.getName());
2228: 			} else {
2229: 				map.remove(l.getName());
2230: 			}
2231: 		}
2232: 		return map;
2233: 	}
