669: 
670: 		@Override
671: 		public boolean equals(Object o) {
672: 			if (this == o) {
673: 				return true;
674: 			}
675: 			if (o == null || getClass() != o.getClass()) {
676: 				return false;
677: 			}
678: 			TileBoxRequest that = (TileBoxRequest) o;
679: 			return left == that.left && top == that.top && width == that.width
680: 					&& height == that.height && zoom == that.zoom;
681: 		}
