824: 					RotatedTileBox original = tileBox.copy();
825: 					RotatedTileBox extended = original.copy();
826: 					extended.increasePixelDimensions(tileBox.getPixWidth() / 2, tileBox.getPixHeight() / 2);
827: 					Task task = new Task(original, extended);
828: 					if (currentTask == null) {
