236: 	@Override
237: 	public void updateLocation(Location location) {
238: 		Location prevLocation = myLocation;
239: 		long prevLocationTime = myLocationTime;
240: 
241: 		long locationTime = System.currentTimeMillis();
242: 		long movingTime = locationTime - prevLocationTime;
243: 		myLocation = location;
244: 		myLocationTime = locationTime;
245: 
246: 		Location predictedLocation = null;
247: 		Integer interpolationPercent = app.getSettings().LOCATION_INTERPOLATION_PERCENT.get();
248: 		if (location != null && prevLocation != null && animateMyLocation(location) && movingTime > 100
249: 				&& app.getSettings().SNAP_TO_ROAD.get()
250: 				&& routingHelper.isRouteCalculated() && routingHelper.isFollowingMode()
251: 				&& interpolationPercent > 0) {
252: 			List<Location> predictedLocations = RoutingHelperUtils.predictLocations(prevLocation,
253: 					location, movingTime / 1000.0, routingHelper.getRoute(), interpolationPercent);
254: 			if (!predictedLocations.isEmpty()) {
255: 				predictedLocation = predictedLocations.get(0);
256: 			}
257: 		}
258: 
259: 		boolean showViewAngle = false;
260: 		if (location != null) {
261: 			locationProvider = location.getProvider();
262: 			if (settings.DRIVING_REGION_AUTOMATIC.get() && !drivingRegionUpdated && !app.isApplicationInitializing()) {
263: 				drivingRegionUpdated = true;
264: 				RoutingHelperUtils.updateDrivingRegionIfNeeded(app, location, true);
265: 			}
266: 		}
267: 		if (mapView != null) {
268: 			MapRendererView mapRenderer = mapView.getMapRenderer();
269: 			RotatedTileBox tb = mapView.getRotatedTileBox();
270: 			if (isMapLinkedToLocation() && location != null) {
271: 				Float rotation = null;
272: 				boolean pendingRotation = false;
273: 				int currentMapRotation = settings.ROTATE_MAP.get();
274: 				boolean smallSpeedForCompass = isSmallSpeedForCompass(location);
275: 
276: 				showViewAngle = (tb != null &&
277: 						NativeUtilities.containsLatLon(mapRenderer, tb, location.getLatitude(), location.getLongitude()));
278: 				if (currentMapRotation == OsmandSettings.ROTATE_MAP_BEARING) {
279: 					// special case when bearing equals to zero (we don't change anything)
280: 					if (location.hasBearing() && location.getBearing() != 0f) {
281: 						rotation = -location.getBearing();
282: 					}
283: 					if (rotation == null && prevLocation != null && tb != null) {
284: 						double distDp = (tb.getPixDensity() * MapUtils.getDistance(prevLocation, location)) / tb.getDensity();
285: 						if (distDp > SKIP_ANIMATION_DP_THRESHOLD) {
286: 							movingTime = 0;
287: 						}
288: 					}
289: 				} else if (currentMapRotation == OsmandSettings.ROTATE_MAP_COMPASS) {
290: 					showViewAngle = routePlanningMode; // disable compass rotation in that mode
291: 					pendingRotation = true;
292: 				} else if (currentMapRotation == OsmandSettings.ROTATE_MAP_NONE) {
293: 					rotation = 0.0f;
294: 					pendingRotation = true;
295: 				} else if (currentMapRotation == OsmandSettings.ROTATE_MAP_MANUAL) {
296: 					pendingRotation = true;
297: 				}
298: 				registerUnregisterSensor(location, smallSpeedForCompass);
299: 
300: 				if (mapRenderer != null && !settings.USE_DISCRETE_AUTO_ZOOM.get()) {
301: 					setMyLocationV2(mapView, mapRenderer, location, predictedLocation, movingTime, rotation);
302: 				} else {
303: 					setMyLocationV1(mapView, location, movingTime, rotation, pendingRotation);
304: 				}
305: 			} else if (location != null) {
306: 				showViewAngle = (tb != null && NativeUtilities.containsLatLon(mapRenderer, tb, location.getLatitude(), location.getLongitude()));
307: 				registerUnregisterSensor(location, false);
308: 			}
309: 			this.showViewAngle = showViewAngle;
310: 			followingMode = routingHelper.isFollowingMode();
311: 			if (routePlanningMode != routingHelper.isRoutePlanningMode()) {
312: 				switchRoutePlanningMode();
313: 			}
314: 			// When location is changed we need to refresh map in order to show movement!
315: 			mapView.refreshMap();
316: 		}
317: 
318: 		if (dashboard != null) {
319: 			dashboard.updateMyLocation(location);
320: 		}
321: 		if (contextMenu != null) {
322: 			contextMenu.updateMyLocation(location);
323: 		}
324: 	}
