334: 	private void setMyLocationV2(@NonNull OsmandMapTileView mapView, @NonNull MapRendererView mapRenderer,
335: 	                             @NonNull Location location, @Nullable Location predictedLocation, long timeDiff,
336: 	                             @Nullable Float rotation) {
337: 		boolean animateMyLocation = animateMyLocation(location);
338: 
339: 		ComplexZoom autoZoom = null;
340: 		if (shouldAutoZoom(location, 0)) {
341: 			if (animateMyLocation) {
342: 				mapView.getAnimatedDraggingThread().stopAnimatingSync();
343: 			}
344: 			autoZoom = autoZoomBySpeedHelper.calculateZoomBySpeedToAnimate(mapRenderer, location, rotation, getNextTurn());
345: 		}
346: 
347: 		long movingTime;
348: 		if (animateMyLocation) {
349: 			movingTime = timeDiff;
350: 		} else {
351: 			if (settings.DO_NOT_USE_ANIMATIONS.get()) {
352: 				movingTime = 0;
353: 			} else {
354: 				movingTime = movingToMyLocation
355: 						? (long) Math.min(timeDiff * 0.7, MOVE_ANIMATION_TIME) : 0;
356: 			}
357: 		}
358: 
359: 		float fixedZoomDuration = animateMyLocation ? -1 : AnimateDraggingMapThread.NAV_ANIMATION_TIME;
360: 		Pair<ComplexZoom, Float> zoomParams = autoZoom != null
361: 				? autoZoomBySpeedHelper.getAutoZoomParams(mapRenderer.getZoom(), autoZoom, fixedZoomDuration)
362: 				: null;
363: 
364: 		int elevationAngle = 0;
365: 		if (zoomParams != null && mapView.getElevationAngle() != DEFAULT_ELEVATION_ANGLE) {
366: 			elevationAngle  = settings.AUTO_ZOOM_3D_ANGLE.get();
367: 		}
368: 		double latitude = predictedLocation != null ? predictedLocation.getLatitude() : location.getLatitude();
369: 		double longitude = predictedLocation != null ? predictedLocation.getLongitude() : location.getLongitude();
370: 		mapView.getAnimatedDraggingThread().startMoving(
371: 				latitude, longitude, zoomParams,
372: 				false, rotation, elevationAngle, movingTime, false,
373: 				() -> movingToMyLocation = false);
374: 	}
375: 
376: 	private void setMyLocationV1(@NonNull OsmandMapTileView mapView,
377: 	                             @NonNull Location location, long movingTime,
378: 	                             @Nullable Float rotation, boolean pendingRotation) {
379: 		RotatedTileBox tileBox = mapView.getRotatedTileBox();
380: 		ComplexZoom autoZoom = null;
381: 		if (shouldAutoZoom(location, AUTO_ZOOM_DEFAULT_CHANGE_ZOOM)) {
382: 			autoZoom = autoZoomBySpeedHelper.calculateAutoZoomBySpeedV1(tileBox, location.getSpeed());
383: 			lastTimeAutoZooming = System.currentTimeMillis();
384: 		}
385: 
386: 		if (animateMyLocation(location)) {
387: 			Pair<ComplexZoom, Float> zoomParams = autoZoom != null
388: 					? new Pair<>(autoZoom, AnimateDraggingMapThread.NAV_ANIMATION_TIME)
389: 					: null;
390: 			mapView.getAnimatedDraggingThread().startMoving(
391: 					location.getLatitude(), location.getLongitude(), zoomParams,
392: 					pendingRotation, rotation, 0, movingTime, false,
393: 					() -> movingToMyLocation = false);
394: 		} else {
395: 			if (autoZoom != null) {
396: 				mapView.getAnimatedDraggingThread().startZooming(autoZoom.base, autoZoom.floatPart, null, false);
397: 			}
398: 			if (rotation != null && allowRotationAfterReset()) {
399: 				mapView.setRotate(rotation, false);
400: 			}
401: 			mapView.setLatLon(location.getLatitude(), location.getLongitude());
402: 		}
403: 	}
