185: 				app.getTargetPointsHelper().removeAllWayPoints(true, true);
186: 			} else {
187: 				for (int i = checkedIntermediates.length - 2; i >= 0; i--) { // skip the destination until a retained waypoint is found
188: 					if (checkedIntermediates[i] && changeDestinationFlag) { // Find a valid replacement for the destination
189: 						app.getTargetPointsHelper().makeWayPointDestination(cnt == 0, i);
