234: 	public AlarmInfo getMostImportantAlarm(SpeedConstants sc, boolean showCameras) {
235: 		Location lastProjection = app.getRoutingHelper().getLastProjection();
236: 		float mxspeed = route.getCurrentMaxSpeed(appMode.getRouteTypeProfile());
237: 		float delta = settings.SPEED_LIMIT_EXCEED_KMH.get() / 3.6f;
238: 		AlarmInfo speedAlarm = createSpeedAlarm(sc, mxspeed, lastProjection, delta);
239: 		if (speedAlarm != null) {
240: 			getVoiceRouter().announceSpeedAlarm(speedAlarm.getIntValue(), lastProjection.getSpeed());
241: 		}
242: 		AlarmInfo mostImportant = speedAlarm;
243: 		int mostPriority = speedAlarm != null ? speedAlarm.updateDistanceAndGetPriority(0, 0) : Integer.MAX_VALUE;
244: 		float speed = lastProjection != null && lastProjection.hasSpeed() ? lastProjection.getSpeed() : 0;
245: 		AnnounceTimeDistances atd = getVoiceRouter().getAnnounceTimeDistances();
246: 		if (ALARMS < pointsProgress.size()) {
247: 			int kIterator = pointsProgress.get(ALARMS);
248: 			List<LocationPointWrapper> lp = locationPoints.get(ALARMS);
249: 			while (kIterator < lp.size()) {
250: 				LocationPointWrapper lwp = lp.get(kIterator);
251: 				AlarmInfo inf = (AlarmInfo) lwp.point;
252: 				int currentRoute = route.getCurrentRoute();
253: 				// getLastLocationIndex()  == -1 is always < currentRoute
254: 				if (inf.getLocationIndex() <= currentRoute && inf.getLastLocationIndex() < currentRoute) {
255: 					// skip already passed alarms
256: 				} else {
257: 					int distanceByRoute = 0;
258: 					Location lastKnownLocation = app.getRoutingHelper().getLastProjection();
259: 					if (inf.getLocationIndex() < currentRoute) {
260: 						// update remaining length
261: 						inf.setFloatValue(route.getDistanceToPoint(lastKnownLocation, inf.getLastLocationIndex()));
262: 					} else {
263: 						distanceByRoute = route.getDistanceToPoint(lastKnownLocation, inf.getLocationIndex() - 1);
264: 					}
265: 					if (!atd.isTurnStateActive(0, distanceByRoute, STATE_LONG_PNT_APPROACH)) {
266: 						// break once first future alarm is far away as others will be also far away
267: 						break;
268: 					}
269: 					float time = speed > 0 ? distanceByRoute / speed : Integer.MAX_VALUE;
270: 					int priority = inf.updateDistanceAndGetPriority(time, distanceByRoute);
271: 					if (priority < mostPriority && (showCameras || inf.getType() != SPEED_CAMERA)) {
272: 						mostImportant = inf;
273: 						mostPriority = priority;
274: 					}
275: 				}
276: 				kIterator++;
277: 			}
278: 		}
279: 		return mostImportant;
