388: 	public void announceVisibleLocations() {
389: 		Location lastKnownLocation = app.getRoutingHelper().getLastProjection();
390: 		if (lastKnownLocation != null && app.getRoutingHelper().isFollowingMode()) {
391: 			for (int type = 0; type < locationPoints.size(); type++) {
392: 				int currentRoute = route.getCurrentRoute();
393: 				List<LocationPointWrapper> approachPoints = new ArrayList<>();
394: 				List<LocationPointWrapper> announcePoints = new ArrayList<>();
395: 				List<LocationPointWrapper> lp = locationPoints.get(type);
396: 				if (lp != null) {
397: 					int kIterator = pointsProgress.get(type);
398: 					while (kIterator < lp.size() && lp.get(kIterator).routeIndex < currentRoute) {
399: 						if (type == ALARMS) {
400: 							AlarmInfo alarm = (AlarmInfo) lp.get(kIterator).getPoint();
401: 							if (alarm.getLastLocationIndex() >= currentRoute) {
402: 								break;
403: 							}
404: 						}
405: 						kIterator++;
406: 					}
407: 					pointsProgress.set(type, kIterator);
408: 
409: 					VoiceRouter voiceRouter = getVoiceRouter();
410: 					AnnounceTimeDistances atd = voiceRouter.getAnnounceTimeDistances();
411: 					RouteDirectionInfo nextRoute = voiceRouter.getNextRouteDirection();
412: 					float atdSpeed = atd.getSpeed(lastKnownLocation);
413: 					while (kIterator < lp.size()) {
414: 						LocationPointWrapper lwp = lp.get(kIterator);
415: 						if (lwp.announce) {
416: 							if (!atd.isTurnStateActive(atdSpeed,
417: 									route.getDistanceToPoint(lwp.routeIndex) / 2f, STATE_LONG_PNT_APPROACH)) {
418: 								break;
419: 							}
420: 							LocationPoint point = lwp.point;
421: 							double d1 = Math.max(0.0, route.getDistanceToPoint(lastKnownLocation, lwp.routeIndex - 1)
422: 									- lwp.getDeviationDistance());
423: 							Integer state = locationPointsStates.get(point);
424: 							if (state != null && state == ANNOUNCED_ONCE
425: 									&& atd.isTurnStateActive(atdSpeed, d1, STATE_SHORT_PNT_APPROACH)) {
426: 								locationPointsStates.put(point, ANNOUNCED_DONE);
427: 								announcePoints.add(lwp);
428: 							} else if (type != ALARMS && (state == null || state == NOT_ANNOUNCED)
429: 									&& atd.isTurnStateActive(atdSpeed, d1, STATE_LONG_PNT_APPROACH)) {
430: 								locationPointsStates.put(point, ANNOUNCED_ONCE);
431: 								approachPoints.add(lwp);
432: 							} else if (type == ALARMS && (state == null || state == NOT_ANNOUNCED)) {
433: 								AlarmInfo alarm = (AlarmInfo) point;
434: 								AlarmInfoType t = alarm.getType();
435: 								if (beforeTunnelEntrance(currentRoute, alarm)) {
436: 									kIterator++;
437: 									continue;
438: 								}
439: 								int announceRadius;
440: 								boolean filterCloseAlarms = false;
441: 								switch (t) {
442: 									case TRAFFIC_CALMING:
443: 									case HAZARD:
444: 										announceRadius = STATE_SHORT_ALARM_ANNOUNCE;
445: 										filterCloseAlarms = true;
446: 										break;
447: 									case PEDESTRIAN:
448: 										announceRadius = ((nextRoute != null)
449: 												&& (nextRoute.getTurnType().isRoundAbout())
450: 												&& (kIterator != 0))
451: 												? STATE_SHORT_ALARM_ANNOUNCE
452: 												: STATE_LONG_ALARM_ANNOUNCE;
453: 										break;
454: 									default:
455: 										announceRadius = STATE_LONG_ALARM_ANNOUNCE;
456: 										break;
457: 								}
458: 								boolean proceed = atd.isTurnStateActive(atdSpeed, d1, announceRadius);
459: 								if (proceed && filterCloseAlarms) {
460: 									AlarmInfo lastAlarm = lastAnnouncedAlarms.get(t);
461: 									if (lastAlarm != null) {
462: 										double dist = MapUtils.getDistance(lastAlarm.getLatitude(), lastAlarm.getLongitude(), alarm.getLatitude(), alarm.getLongitude());
463: 										if (atd.isTurnStateActive(atdSpeed, dist, STATE_SHORT_ALARM_ANNOUNCE)) {
464: 											locationPointsStates.put(point, ANNOUNCED_DONE);
465: 											proceed = false;
466: 										}
467: 									}
468: 									Long timeLastAlarm = lastAnnouncedAlarmsTime.get(t);
469: 									if (timeLastAlarm != null && proceed) {
470: 										long ms = System.currentTimeMillis();
471: 										if (ms - timeLastAlarm < SAME_ALARM_INTERVAL * 1000) {
472: 											locationPointsStates.put(point, ANNOUNCED_DONE);
473: 											proceed = false;
474: 										}
475: 									}
476: 								}
477: 								if (proceed) {
478: 									locationPointsStates.put(point, ANNOUNCED_ONCE);
479: 									approachPoints.add(lwp);
480: 								}
481: 							}
482: 						}
483: 						kIterator++;
484: 					}
485: 					if (!announcePoints.isEmpty()) {
486: 						if (announcePoints.size() > ANNOUNCE_POI_LIMIT) {
487: 							announcePoints = announcePoints.subList(0, ANNOUNCE_POI_LIMIT);
488: 						}
489: 						if (type == WAYPOINTS) {
490: 							voiceRouter.announceWaypoint(announcePoints);
491: 						} else if (type == POI) {
492: 							voiceRouter.announcePoi(announcePoints);
493: 						} else if (type == ALARMS) {
494: 							// nothing to announce
495: 						} else if (type == FAVORITES) {
496: 							voiceRouter.announceFavorite(announcePoints);
497: 						}
498: 					}
499: 					if (!approachPoints.isEmpty()) {
500: 						if (approachPoints.size() > APPROACH_POI_LIMIT) {
501: 							approachPoints = approachPoints.subList(0, APPROACH_POI_LIMIT);
502: 						}
503: 						if (type == WAYPOINTS) {
504: 							voiceRouter.approachWaypoint(lastKnownLocation, approachPoints);
505: 						} else if (type == POI) {
506: 							voiceRouter.approachPoi(lastKnownLocation, approachPoints);
507: 						} else if (type == ALARMS) {
508: 							for (LocationPointWrapper pw : approachPoints) {
509: 								AlarmInfo alarm = (AlarmInfo) pw.point;
510: 								voiceRouter.announceAlarm(new AlarmInfo(alarm.getType(), -1), lastKnownLocation.getSpeed());
511: 								lastAnnouncedAlarms.put(alarm.getType(), alarm);
512: 								lastAnnouncedAlarmsTime.put(alarm.getType(), System.currentTimeMillis());
513: 							}
514: 						} else if (type == FAVORITES) {
515: 							voiceRouter.approachFavorite(lastKnownLocation, approachPoints);
516: 						}
517: 					}
518: 				}
519: 			}
520: 		}
521: 	}
