152: 	public void removeVisibleLocationPoint(List<LocationPointWrapper> points) {
153: 		List<TargetPoint> ps = app.getTargetPointsHelper().getIntermediatePointsWithTarget();
154: 		boolean[] checkedIntermediates = null;
155: 		for (LocationPointWrapper lp : points) {
156: 			if (lp.type == TARGETS) {
157: 				if (checkedIntermediates == null) {
158: 					checkedIntermediates = new boolean[ps.size()];
159: 					Arrays.fill(checkedIntermediates, true);
160: 				}
161: 				if (((TargetPoint) lp.point).intermediate) {
162: 					checkedIntermediates[((TargetPoint) lp.point).index] = false;
163: 				} else {
164: 					checkedIntermediates[ps.size() - 1] = false;
165: 				}
166: 			} else if (lp.type < locationPoints.size()) {
167: 				locationPoints.get(lp.type).remove(lp);
168: 			}
169: 		}
170: 		if (checkedIntermediates != null) {
171: 			commitPointsRemoval(checkedIntermediates);
172: 		}
173: 	}
174: 
175: 	private void commitPointsRemoval(boolean[] checkedIntermediates) {
176: 		int cnt = 0;
177: 		for (int i = checkedIntermediates.length - 1; i >= 0; i--) {
178: 			if (!checkedIntermediates[i]) {
179: 				cnt++;
180: 			}
181: 		}
182: 		if (cnt > 0) {
183: 			boolean changeDestinationFlag = !checkedIntermediates[checkedIntermediates.length - 1];
184: 			if (cnt == checkedIntermediates.length) { // there is no alternative destination if all points are to be removed?
185: 				app.getTargetPointsHelper().removeAllWayPoints(true, true);
186: 			} else {
187: 				for (int i = checkedIntermediates.length - 2; i >= 0; i--) { // skip the destination until a retained waypoint is found
188: 					if (checkedIntermediates[i] && changeDestinationFlag) { // Find a valid replacement for the destination
189: 						app.getTargetPointsHelper().makeWayPointDestination(cnt == 0, i);
190: 						changeDestinationFlag = false;
191: 					} else if (!checkedIntermediates[i]) {
192: 						cnt--;
193: 						app.getTargetPointsHelper().removeWayPoint(cnt == 0, i);
194: 					}
195: 				}
196: 			}
197: 		}
198: 	}
