200: 	public LocationPointWrapper getMostImportantLocationPoint(List<LocationPointWrapper> list) {
201: 		if (list != null) {
202: 			list.clear();
203: 		}
204: 		LocationPointWrapper found = null;
205: 		AnnounceTimeDistances atd = getVoiceRouter().getAnnounceTimeDistances();
206: 		for (int type = 0; type < locationPoints.size(); type++) {
207: 			if (type == ALARMS || type == TARGETS) {
208: 				continue;
209: 			}
210: 			int kIterator = pointsProgress.get(type);
211: 			List<LocationPointWrapper> lp = locationPoints.get(type);
212: 			while (kIterator < lp.size()) {
213: 				LocationPointWrapper lwp = lp.get(kIterator);
214: 				if (lp.get(kIterator).routeIndex < route.getCurrentRoute()) {
215: 					// skip
216: 				} else {
217: 					if (atd.isTurnStateActive(0,
218: 							route.getDistanceToPoint(lwp.routeIndex), STATE_LONG_PNT_APPROACH)) {
219: 						if (found == null || found.routeIndex < lwp.routeIndex) {
220: 							found = lwp;
221: 							if (list != null) {
222: 								list.add(lwp);
223: 							}
224: 						}
225: 					}
226: 					break;
227: 				}
228: 				kIterator++;
229: 			}
230: 		}
231: 		return found;
232: 	}
