343: 	@Nullable
344: 	public AlarmInfo calculateMostImportantAlarm(RouteDataObject ro, Location loc, MetricsConstants mc,
345: 	                                             SpeedConstants sc, boolean showCameras) {
346: 		float maxSpeed = ro.getMaximumSpeed(ro.isBearingAlignedWithRoute(loc), appMode.getRouteTypeProfile());
347: 		float delta = settings.SPEED_LIMIT_EXCEED_KMH.get() / 3.6f;
348: 		AlarmInfo speedAlarm = createSpeedAlarm(sc, maxSpeed, loc, delta);
349: 		if (speedAlarm != null) {
350: 			getVoiceRouter().announceSpeedAlarm(speedAlarm.getIntValue(), loc.getSpeed());
351: 			return speedAlarm;
352: 		}
353: 		for (int i = 0; i < ro.getPointsLength(); i++) {
354: 			int[] pointTypes = ro.getPointTypes(i);
355: 			RouteRegion reg = ro.region;
356: 			if (pointTypes != null) {
357: 				for (int pointType : pointTypes) {
358: 					RouteTypeRule typeRule = reg.quickGetEncodingRule(pointType);
359: 					AlarmInfo info = AlarmInfo.createAlarmInfo(typeRule, 0, loc);
360: 					if (info != null) {
361: 						if (info.getType() != SPEED_CAMERA || showCameras) {
362: 							return info;
363: 						}
364: 					}
365: 				}
366: 			}
367: 		}
368: 		return null;
369: 	}
