371: 	@Nullable
372: 	private static AlarmInfo createSpeedAlarm(@NonNull SpeedConstants constants, float mxspeed, Location loc, float delta) {
373: 		AlarmInfo speedAlarm = null;
374: 		if (mxspeed != 0 && loc != null && loc.hasSpeed() && mxspeed != RouteDataObject.NONE_MAX_SPEED) {
375: 			if (loc.getSpeed() > mxspeed + delta) {
376: 				int speed;
377: 				if (constants.getImperial()) {
378: 					speed = Math.round(mxspeed * 3.6f / 1.6f);
379: 				} else {
380: 					speed = Math.round(mxspeed * 3.6f);
381: 				}
382: 				speedAlarm = AlarmInfo.createSpeedLimit(speed, loc);
383: 			}
384: 		}
385: 		return speedAlarm;
386: 	}
