599: 		boolean announcePOI = settings.announceNearbyPoisEnabled.getModeValue(appMode);
600: 		boolean showFavorites = settings.showNearbyFavoritesEnabled.getModeValue(appMode);
601: 		boolean announceFavorites = settings.announceNearbyFavoritesEnabled.getModeValue(appMode);
