636: 	private float dist(LocationPoint l, List<Location> locations, int[] ind, boolean[] devDirRight) {
637: 		float dist = Float.POSITIVE_INFINITY;
638: 		// Special iterations because points stored by pairs!
639: 		for (int i = 1; i < locations.size(); i++) {
640: 			double ld = MapUtils.getOrthogonalDistance(
641: 					l.getLatitude(), l.getLongitude(),
642: 					locations.get(i - 1).getLatitude(), locations.get(i - 1).getLongitude(),
643: 					locations.get(i).getLatitude(), locations.get(i).getLongitude());
644: 			if (ld < dist) {
645: 				if (ind != null) {
646: 					ind[0] = i;
647: 				}
648: 				dist = (float) ld;
649: 			}
650: 		}
651: 
652: 		if (ind != null && dist < Float.POSITIVE_INFINITY) {
653: 			int i = ind[0];
654: 			devDirRight[0] = MapUtils.rightSide(l.getLatitude(), l.getLongitude(),
655: 					locations.get(i - 1).getLatitude(), locations.get(i - 1).getLongitude(),
656: 					locations.get(i).getLatitude(), locations.get(i).getLongitude());
657: 		}
658: 
659: 		return dist;
660: 	}
