1028: 	private void onPauseActivity() {
1029: 		settings.MAP_SCREEN_ORIENTATION.removeListener(mapScreenOrientationSettingListener);
1030: 		settings.USE_SYSTEM_SCREEN_TIMEOUT.removeListener(useSystemScreenTimeoutListener);
1031: 		if (!app.getRoutingHelper().isRouteWasFinished()) {
1032: 			DestinationReachedFragment.resetShownState();
1033: 		}
1034: 		if (trackDetailsMenu.isVisible()) {
1035: 			trackDetailsMenu.dismiss(false);
1036: 		}
1037: 		isPausePending = false;
1038: 		OsmandMapTileView mapView = getMapView();
1039: 		mapView.setOnDrawMapListener(null);
1040: 		cancelSplashScreenTimer();
1041: 		app.getMapMarkersHelper().removeListener(this);
1042: 		app.getRoutingHelper().removeListener(this);
1043: 		app.getDownloadThread().resetUiActivity(this);
1044: 
1045: 		if (mapViewWithLayers != null) {
1046: 			mapViewWithLayers.onPause();
1047: 		}
1048: 		app.getLocationProvider().pauseAllUpdates();
1049: 		app.getDaynightHelper().stopSensorIfNeeded();
1050: 		settings.APPLICATION_MODE.removeListener(applicationModeListener);
1051: 
1052: 		LatLon mapLocation = new LatLon(mapView.getLatitude(), mapView.getLongitude());
1053: 		settings.setLastKnownMapLocation(mapLocation);
1054: 		AnimateDraggingMapThread animatedThread = mapView.getAnimatedDraggingThread();
1055: 		if (animatedThread.isAnimating() && animatedThread.getTargetIntZoom() != 0 && !getMapViewTrackingUtilities().isMapLinkedToLocation()) {
1056: 			settings.setMapLocationToShow(animatedThread.getTargetLatitude(), animatedThread.getTargetLongitude(),
1057: 					animatedThread.getTargetIntZoom());
1058: 		}
1059: 		mapView.syncRotate();
1060: 
1061: 		MapRendererView mapRenderer = mapView.getMapRenderer();
1062: 		if (mapRenderer != null)
1063: 			settings.setLastKnownMapHeight(mapRenderer.getMapTargetHeightInMeters());
1064: 		settings.setLastKnownMapZoom(mapView.getZoom());
1065: 		settings.setLastKnownMapZoomFloatPart(mapView.getZoomFloatPart());
1066: 		settings.setLastKnownMapRotation(mapView.getRotate());
1067: 		settings.setLastKnownMapElevation(mapView.getElevationAngle());
1068: 		settings.isMapActivityEnabled = false;
1069: 		LOG.info(">>>> MAP_ACTIVITY_ENABLED = false");
1070: 
1071: 		getMapView().getAnimatedDraggingThread().toggleAnimations();
1072: 		app.getResourceManager().interruptRendering();
1073: 		PluginsHelper.onMapActivityPause(this);
1074: 	}
