234: 		LifecycleObserver appLifecycleObserver = new DefaultLifecycleObserver() {
235: 			@Override
236: 			public void onStart(@NonNull LifecycleOwner owner) {
237: 				appInForeground = true;
238: 			}
239: 
240: 			@Override
241: 			public void onStop(@NonNull LifecycleOwner owner) {
242: 				appInForeground = false;
243: 			}
244: 		};
245: 		ProcessLifecycleOwner.get().getLifecycle().addObserver(appLifecycleObserver);
246: 
247: 		createInUiThread();
248: 		uiHandler = new Handler();
249: 		appCustomization = new OsmAndAppCustomization();
250: 		appCustomization.setup(this);
251: 		settings = appCustomization.getOsmandSettings();
252: 		appInitializer.initVariables();
253: 		if (appInitializer.isAppVersionChanged() && appInitializer.getPrevAppVersion() < AppVersionUpgradeOnInit.VERSION_2_3) {
254: 			settings.freezeExternalStorageDirectory();
255: 		} else if (appInitializer.isFirstTime()) {
256: 			settings.initExternalStorageDirectory();
257: 		}
258: 		externalStorageDirectory = settings.getExternalStorageDirectory();
259: 		if (!FileUtils.isWritable(externalStorageDirectory)) {
260: 			externalStorageDirectoryReadOnly = true;
261: 			externalStorageDirectory = settings.getInternalAppPath();
262: 		}
263: 		FileUtils.removeUnnecessaryFiles(this);
264: 
265: 		// Initialize shared library
266: 		net.osmand.shared.util.PlatformUtil.INSTANCE.initialize(this, new OsmAndContextImpl(this));
267: 
268: 		localeHelper.checkPreferredLocale();
269: 		appInitializer.onCreateApplication();
270: 		osmandMap.getMapLayers().createLayers(osmandMap.getMapView());
271: 		startApplication();
272: 		System.out.println("Time to start application " + (System.currentTimeMillis() - timeToStart) + " ms. Should be less < 800 ms");
273: 
274: 		timeToStart = System.currentTimeMillis();
275: 		PluginsHelper.initPlugins(this);
276: 		PluginsHelper.createLayers(this, null);
277: 		System.out.println("Time to init plugins " + (System.currentTimeMillis() - timeToStart) + " ms. Should be less < 800 ms");
278: 
279: 		osmandMap.getMapLayers().updateLayers(null);
280: 
281: 		if (appInitializer.isFirstTime()) {
282: 			settings.resetLastGlobalPreferencesEditTime();
283: 			settings.resetLastPreferencesEditTime(settings.APPLICATION_MODE.get());
284: 		}
285: 
286: 		SearchUICore.setDebugMode(PluginsHelper.isDevelopment());
287: 		BackupHelper.DEBUG = true;//PluginsHelper.isDevelopment();
288: 	}
