507: 	public void onConfigurationChanged(@NonNull Configuration newConfig) {
508: 		Resources resources = getResources();
509: 		resources.updateConfiguration(newConfig, resources.getDisplayMetrics());
510: 
511: 		resources = getBaseContext().getResources();
512: 		resources.updateConfiguration(newConfig, resources.getDisplayMetrics());
513: 
514: 		DisplayMetrics displayMetrics = resources.getDisplayMetrics();
515: 		if (density != displayMetrics.density) {
516: 			density = displayMetrics.density;
517: 			getUIUtilities().clearCache();
518: 			PointImageUtils.clearCache();
519: 
520: 			OsmandMap osmandMap = getOsmandMap();
521: 			if (osmandMap != null) {
522: 				osmandMap.getMapView().updateDisplayMetrics(displayMetrics, displayMetrics.widthPixels,
523: 						displayMetrics.heightPixels - AndroidUtils.getStatusBarHeight(this));
524: 			}
525: 		}
526: 
527: 		Locale preferredLocale = localeHelper.getPreferredLocale();
528: 		if (preferredLocale != null && !Objects.equals(newConfig.locale.getLanguage(), preferredLocale.getLanguage())) {
529: 			super.onConfigurationChanged(newConfig);
530: 			Locale.setDefault(preferredLocale);
531: 		} else {
532: 			super.onConfigurationChanged(newConfig);
533: 		}
534: 	}
