684: 			@Nullable Runnable onCommandPlayerCreated, boolean warnNoProvider,
685: 			boolean showProgress, boolean forceInitialization, boolean applyAllModes) {
686: 		String voiceProvider = settings.VOICE_PROVIDER.getModeValue(appMode);
687: 		if (OsmandSettings.VOICE_PROVIDER_NOT_USE.equals(voiceProvider)) {
688: 			settings.VOICE_MUTE.setModePreferenceValue(appMode, true);
689: 		} else if (Algorithms.isEmpty(voiceProvider)) {
690: 			if (warnNoProvider && context instanceof MapActivity) {
691: 				VoiceProviderDialog.showVoiceProviderDialog((MapActivity) context, appMode, applyAllModes);
692: 			}
693: 		} else {
694: 			if (player == null || !voiceProvider.equals(player.getCurrentVoice()) || forceInitialization) {
695: 				appInitializer.initVoiceDataInDifferentThread(context, appMode, voiceProvider, onCommandPlayerCreated, showProgress);
696: 			}
697: 		}
698: 	}
