707: 		} else if (mode.getRouteService() == RouteService.STRAIGHT) {
708: 			MetricsConstants mc = settings.METRIC_SYSTEM.getModeValue(mode);
709: 			if (mc == MetricsConstants.KILOMETERS_AND_METERS || mc == MetricsConstants.MILES_AND_METERS) {
710: 				return 500.f;
711: 			} else {
712: 				// 1/4 mile
713: 				return 482.f;
714: 			}
715: 		}
716: 		return posTolerance * POS_TOLERANCE_DEVIATION_MULTIPLIER;
