385: 	private Location setCurrentLocation(Location currentLocation, boolean returnUpdatedLocation,
386: 	                                    RouteCalculationResult previousRoute, boolean targetPointsChanged) {
387: 		Location locationProjection = currentLocation;
388: 		if (isPublicTransportMode() && currentLocation != null && finalLocation != null &&
389: 				(targetPointsChanged || transportRoutingHelper.getStartLocation() == null)) {
390: 			lastFixedLocation = currentLocation;
391: 			lastProjection = locationProjection;
392: 			transportRoutingHelper.setApplicationMode(mode);
393: 			transportRoutingHelper.setFinalAndCurrentLocation(finalLocation,
394: 					new LatLon(currentLocation.getLatitude(), currentLocation.getLongitude()));
395: 		}
396: 		if (finalLocation == null || currentLocation == null || isPublicTransportMode()) {
397: 			isOffRouteDetected = false;
398: 			return locationProjection;
399: 		}
400: 		float posTolerance = getPosTolerance(currentLocation.hasAccuracy() ? currentLocation.getAccuracy() : 0);
401: 		boolean calculateRoute = false;
402: 		synchronized (this) {
403: 			isOffRouteDetected = false;
404: 			double distOrth = 0;
405: 
406: 			// 0. Route empty or needs to be extended? Then re-calculate route.
407: 			if (route.isEmpty()) {
408: 				calculateRoute = !route.hasMissingMaps() || isLocationJumping(currentLocation, targetPointsChanged);
409: 			} else {
410: 				// 1. Update current route position status according to latest received location
411: 				boolean finished = updateCurrentRouteStatus(currentLocation, posTolerance);
412: 				if (finished) {
413: 					return null;
414: 				}
415: 				List<Location> routeNodes = route.getImmutableAllLocations();
416: 				int currentRoute = route.currentRoute;
417: 				double allowableDeviation = route.getRouteRecalcDistance();
418: 				if (allowableDeviation <= 0) {
419: 					allowableDeviation = getDefaultAllowedDeviation(settings, route.getAppMode(), posTolerance);
420: 				}
421: 
422: 				// 2. Analyze if we need to recalculate route
423: 				// >100m off current route (sideways) or parameter (for Straight line)
424: 				if (allowableDeviation > 0) {
425: 					if (currentRoute == 0) {
426: 						distOrth = currentLocation.distanceTo(routeNodes.get(currentRoute)); // deviation at the start
427: 					} else {
428: 						distOrth = RoutingHelperUtils.getOrthogonalDistance(currentLocation, routeNodes.get(currentRoute - 1), routeNodes.get(currentRoute));
429: 					}
430: 					if (distOrth > allowableDeviation) {
431: 						log.info("Recalculate route, because correlation  : " + distOrth); //$NON-NLS-1$
432: 						isOffRouteDetected = true;
433: 						calculateRoute = !settings.DISABLE_OFFROUTE_RECALC.get();
434: 					}
435: 				}
436: 				// 3. Identify wrong movement direction
437: 				Location next = route.getNextRouteLocation();
438: 				Location prev = route.getRouteLocationByDistance(-15);//-15 meters
439: 				boolean isStraight =
440: 						route.getRouteService() == RouteService.DIRECT_TO || route.getRouteService() == RouteService.STRAIGHT;
441: 				boolean wrongMovementDirection = RoutingHelperUtils.checkWrongMovementDirection(currentLocation, prev, next);
442: 				if ((allowableDeviation > 0 && wrongMovementDirection && !isStraight
443: 						&& (currentLocation.distanceTo(routeNodes.get(currentRoute)) > allowableDeviation)) && !settings.DISABLE_WRONG_DIRECTION_RECALC.get()) {
444: 					log.info("Recalculate route, because wrong movement direction: " + currentLocation.distanceTo(routeNodes.get(currentRoute))); //$NON-NLS-1$
445: 					isOffRouteDetected = true;
446: 					calculateRoute = true;
447: 				}
448: 				// 4. Identify if UTurn is needed
449: 				if (RoutingHelperUtils.identifyUTurnIsNeeded(this, currentLocation, posTolerance)) {
450: 					isOffRouteDetected = true;
451: 				}
452: 				// 5. Update Voice router
453: 				// Do not update in route planning mode
454: 				boolean inRecalc = (calculateRoute || isRouteBeingCalculated());
455: 				if (isFollowingModeEnabled) {
456: 					if (!inRecalc && !wrongMovementDirection) {
457: 						voiceRouter.updateStatus(currentLocation, false);
458: 						isVoiceRouterStopped = false;
459: 					} else if (isOffRouteDetected && !isVoiceRouterStopped) {
460: 						voiceRouter.interruptRouteCommands();
461: 						isVoiceRouterStopped = true; // Prevents excessive execution of stop() code
462: 					}
463: 					voiceRouter.announceOffRoute(distOrth);
464: 				}
465: 
466: 				// calculate projection of current location
467: 				if (currentRoute > 0 && !inRecalc) {
468: 					Location previousRouteLocation = routeNodes.get(currentRoute - 1);
469: 					Location currentRouteLocation = routeNodes.get(currentRoute);
470: 					locationProjection = RoutingHelperUtils.getProject(currentLocation, previousRouteLocation,
471: 							currentRouteLocation);
472: 					if (settings.SNAP_TO_ROAD.get() && currentRoute + 1 < routeNodes.size()) {
473: 						boolean previewNextTurn = settings.PREVIEW_NEXT_TURN.get();
474: 						Location nextRouteLocation = routeNodes.get(currentRoute + 1);
475: 						RoutingHelperUtils.approximateBearingIfNeeded(this,
476: 								locationProjection, currentLocation, previousRouteLocation,
477: 								currentRouteLocation, nextRouteLocation, previewNextTurn);
478: 					}
479: 				}
480: 			}
481: 			lastFixedLocation = currentLocation;
482: 			lastProjection = locationProjection;
483: 			if (!route.isEmpty()) {
484: 				lastGoodRouteLocation = currentLocation;
485: 			}
486: 		}
487: 
488: 		if (calculateRoute) {
489: 			routeRecalculationHelper.recalculateRouteInBackground(currentLocation, finalLocation, intermediatePoints, currentGPXRoute,
490: 					previousRoute.isCalculated() ? previousRoute : null, false, !targetPointsChanged);
491: 		} else {
492: 			routeRecalculationHelper.stopCalculationIfParamsNotChanged();
493: 		}
494: 
495: 		double projectDist = mode != null && mode.hasFastSpeed() ? posTolerance : posTolerance / 2;
496: 		if (returnUpdatedLocation && locationProjection != null && currentLocation.distanceTo(locationProjection) < projectDist) {
497: 			return locationProjection;
498: 		} else {
499: 			return currentLocation;
500: 		}
501: 	}
