520: 	private boolean updateCurrentRouteStatus(Location currentLocation, double posTolerance) {
521: 		List<Location> routeNodes = route.getImmutableAllLocations();
522: 		int currentRoute = route.currentRoute;
523: 		// 1. Try to proceed to next point using orthogonal distance (finding minimum orthogonal dist)
524: 		currentRoute = calculateCurrentRoute(currentLocation, posTolerance, routeNodes, currentRoute, true);
525: 
526: 		// 2. check if intermediate found
527: 		if (route.getIntermediatePointsToPass() > 0
528: 				&& route.getDistanceToNextIntermediate(lastFixedLocation) < voiceRouter.getArrivalDistance() && !isRoutePlanningModeEnabled) {
529: 			app.showToastMessage(R.string.arrived_at_intermediate_point);
530: 			route.passIntermediatePoint();
531: 			TargetPointsHelper targets = app.getTargetPointsHelper();
532: 			String name = "";
533: 			if (intermediatePoints != null && !intermediatePoints.isEmpty()) {
534: 				LatLon rm = intermediatePoints.remove(0);
535: 				List<TargetPoint> ll = targets.getIntermediatePointsNavigation();
536: 				int ind = -1;
537: 				for (int i = 0; i < ll.size(); i++) {
538: 					if (ll.get(i).getLatLon() != null && MapUtils.getDistance(ll.get(i).getLatLon(), rm) < 5) {
539: 						name = ll.get(i).getOnlyName();
540: 						ind = i;
541: 						break;
542: 					}
543: 				}
544: 				if (ind >= 0) {
545: 					targets.removeWayPoint(false, ind);
546: 				}
547: 			}
548: 			if (isFollowingModeEnabled) {
549: 				voiceRouter.arrivedIntermediatePoint(name);
550: 			}
551: 			// double check
552: 			while (intermediatePoints != null && route.getIntermediatePointsToPass() < intermediatePoints.size()) {
553: 				intermediatePoints.remove(0);
554: 			}
555: 		}
556: 
557: 		// 3. check if destination found
558: 		Location lastPoint = routeNodes.get(routeNodes.size() - 1);
559: 		if (currentRoute > routeNodes.size() - 3
560: 				&& currentLocation.distanceTo(lastPoint) < voiceRouter.getArrivalDistance()
561: 				&& !isRoutePlanningModeEnabled) {
562: 			//showMessage(app.getString(R.string.arrived_at_destination));
563: 			TargetPointsHelper targets = app.getTargetPointsHelper();
564: 			TargetPoint tp = targets.getPointToNavigate();
565: 			String description = tp == null ? "" : tp.getOnlyName();
566: 			if (isFollowingModeEnabled) {
567: 				voiceRouter.arrivedDestinationPoint(description);
568: 			}
569: 			boolean onDestinationReached = true;
570: 			if (onDestinationReached) {
571: 				clearCurrentRoute(null, null);
572: 				setRoutePlanningMode(false);
573: 				app.runInUIThread(() -> {
574: 					settings.LAST_ROUTING_APPLICATION_MODE = settings.APPLICATION_MODE.get();
575: 					//settings.setApplicationMode(settings.DEFAULT_APPLICATION_MODE.get());
576: 				});
577: 				finishCurrentRoute();
578: 				// targets.clearPointToNavigate(false);
579: 				return true;
580: 			}
581: 		}
582: 
583: 		// 4. update angle point
584: 		if (route.getRouteVisibleAngle() > 0) {
585: 			// proceed to the next point with min acceptable bearing
586: 			double ANGLE_TO_DECLINE = route.getRouteVisibleAngle();
587: 			int nextPoint = route.currentRoute;
588: 			for (; nextPoint < routeNodes.size() - 1; nextPoint++) {
589: 				float bearingTo = currentLocation.bearingTo(routeNodes.get(nextPoint));
590: 				float bearingTo2 = routeNodes.get(nextPoint).bearingTo(routeNodes.get(nextPoint + 1));
591: 				if (Math.abs(MapUtils.degreesDiff(bearingTo2, bearingTo)) <= ANGLE_TO_DECLINE) {
592: 					break;
593: 				}
594: 			}
595: 
596: 			if (nextPoint > 0) {
597: 				Location next = routeNodes.get(nextPoint);
598: 				Location prev = routeNodes.get(nextPoint - 1);
599: 				float bearing = prev.bearingTo(next);
600: 				double bearingTo = Math.abs(MapUtils.degreesDiff(bearing, currentLocation.bearingTo(next)));
601: 				double bearingPrev = Math.abs(MapUtils.degreesDiff(bearing, currentLocation.bearingTo(prev)));
602: 				while (true) {
603: 					Location mp = MapUtils.calculateMidPoint(prev, next);
604: 					if (mp.distanceTo(next) <= 100) {
605: 						break;
606: 					}
607: 					double bearingMid = Math.abs(MapUtils.degreesDiff(bearing, currentLocation.bearingTo(mp)));
608: 					if (bearingPrev < ANGLE_TO_DECLINE) {
609: 						next = mp;
610: 						bearingTo = bearingMid;
611: 					} else if (bearingTo < ANGLE_TO_DECLINE) {
612: 						prev = mp;
613: 						bearingPrev = bearingMid;
614: 					} else {
615: 						break;
616: 					}
617: 				}
618: 				route.updateNextVisiblePoint(nextPoint, next);
619: 			}
620: 		}
621: 
622: 		// 5. Update car navigation
623: 		NavigationSession carNavigationSession = app.getCarNavigationSession();
624: 		if (carNavigationSession != null) {
625: 			app.runInUIThread(() -> carNavigationSession.updateCarNavigation(currentLocation));
626: 		}
627: 		return false;
628: 	}
