852: 	public void recalculateRouteDueToSettingsChange(boolean clearCurrentRoute) {
853: 		if (clearCurrentRoute) {
854: 			clearCurrentRoute(finalLocation, intermediatePoints);
855: 		}
856: 		if (isPublicTransportMode()) {
857: 			Location start = lastFixedLocation;
