161:     public List<WorkflowNodeOutputDTO> getPreviousWorkflowNodeOutputs(String workflowId, String lastWorkflowNodeName) {
162:         List<WorkflowNodeOutputDTO> workflowNodeOutputDTOs = new ArrayList<>();
163: 
164:         Workflow workflow = workflowService.getWorkflow(workflowId);
165: 
166:         List<WorkflowTrigger> workflowTriggers = WorkflowTrigger.of(workflow);
167: 
168:         for (WorkflowTrigger workflowTrigger : workflowTriggers) {
169:             if (lastWorkflowNodeName != null && Objects.equals(workflowTrigger.getName(), lastWorkflowNodeName)) {
170:                 break;
171:             }
172: 
173:             workflowNodeOutputDTOs.add(getWorkflowNodeOutputDTO(workflowId, workflowTrigger));
174:         }
175: 
176:         List<WorkflowTask> workflowTasks = workflow.getTasks(lastWorkflowNodeName);
177: 
178:         for (WorkflowTask workflowTask : workflowTasks) {
179:             if (lastWorkflowNodeName != null && Objects.equals(workflowTask.getName(), lastWorkflowNodeName)) {
180:                 break;
181:             }
182: 
183:             WorkflowNodeType workflowNodeType = WorkflowNodeType.ofType(workflowTask.getType());
184: 
185:             if (Objects.equals(workflowNodeType.name(), "loop")) {
186:                 List<WorkflowTask> childWorkflowTasks = MapUtils
187:                     .getList(
188:                         workflowTask.getParameters(), "iteratee", new TypeReference<Map<String, ?>>() {}, List.of())
189:                     .stream()
190:                     .map(WorkflowTask::new)
191:                     .toList();
192: 
193:                 if (containsWorkflowTask(childWorkflowTasks, lastWorkflowNodeName)) {
194:                     workflowNodeOutputDTOs.add(getWorkflowNodeOutputDTO(workflowId, workflowTask, false));
195:                 }
196:             } else {
197:                 workflowNodeOutputDTOs.add(getWorkflowNodeOutputDTO(workflowId, workflowTask, true));
198:             }
199:         }
200: 
201:         return workflowNodeOutputDTOs;
202:     }
