227:         boolean dynamicOutputDefined = false;
228:         Workflow workflow = workflowService.getWorkflow(workflowId);
229: 
230:         List<WorkflowTrigger> workflowTriggers = WorkflowTrigger.of(workflow);
231: 
232:         for (WorkflowTrigger workflowTrigger : workflowTriggers) {
233:             if (Objects.equals(workflowTrigger.getName(), lastWorkflowNodeName)) {
234:                 WorkflowNodeType workflowNodeType = WorkflowNodeType.ofType(workflowTrigger.getType());
235: 
236:                 dynamicOutputDefined = triggerDefinitionService.isDynamicOutputDefined(
237:                     workflowNodeType.name(), workflowNodeType.version(), workflowNodeType.operation());
238: 
239:                 break;
240:             }
241:         }
242: 
243:         if (!dynamicOutputDefined) {
244:             List<WorkflowTask> workflowTasks = workflow.getTasks(lastWorkflowNodeName);
245: 
246:             for (WorkflowTask workflowTask : workflowTasks) {
247:                 if (Objects.equals(workflowTask.getName(), lastWorkflowNodeName)) {
248:                     WorkflowNodeType workflowNodeType = WorkflowNodeType.ofType(workflowTask.getType());
249: 
250:                     if (workflowNodeType.operation() == null) {
251:                         dynamicOutputDefined = taskDispatcherDefinitionService.isDynamicOutputDefined(
252:                             workflowNodeType.name(), workflowNodeType.version());
253:                     } else {
254:                         dynamicOutputDefined = actionDefinitionService.isDynamicOutputDefined(
255:                             workflowNodeType.name(), workflowNodeType.version(), workflowNodeType.operation());
256:                     }
257: 
258:                     break;
259:                 }
260:             }
261:         }
262: 
263:         if (dynamicOutputDefined) {
264:             for (String cacheName : CACHE_NAMES) {
265:                 workflowCacheManager.clearCacheForWorkflow(workflowId, cacheName);
266:             }
267:         }
268:     }
