421:     @SuppressWarnings("unchecked")
422:     private Optional<OutputResponse> getWorkflowTaskDynamicOutputResponse(
423:         String workflowId, WorkflowTask workflowTask, boolean taskDispatcherExecuteOutput) {
424: 
425:         OutputResponse outputResponse;
426:         Map<String, ?> inputs = workflowTestConfigurationService.getWorkflowTestConfigurationInputs(workflowId);
427: 
428:         WorkflowNodeType workflowNodeType = WorkflowNodeType.ofType(workflowTask.getType());
429: 
430:         if (workflowNodeType.operation() == null) {
431:             if (!taskDispatcherDefinitionService.isDynamicOutputDefined(
432:                 workflowNodeType.name(), workflowNodeType.version())) {
433: 
434:                 return Optional.empty();
435:             }
436:         } else {
437:             if ((!actionDefinitionService.isDynamicOutputDefined(
438:                 workflowNodeType.name(), workflowNodeType.version(), workflowNodeType.operation()))) {
439: 
440:                 return Optional.empty();
441:             }
442:         }
443: 
444:         Map<String, ?> outputs = getPreviousWorkflowNodeSampleOutputs(workflowId, workflowTask.getName());
445: 
446:         Map<String, ?> inputParameters = workflowTask.evaluateParameters(
447:             MapUtils.concat((Map<String, Object>) inputs, (Map<String, Object>) outputs), evaluator);
448: 
449:         Map<String, Long> connectionIds = MapUtils.toMap(
450:             workflowTestConfigurationService.getWorkflowTestConfigurationConnections(
451:                 workflowId, workflowTask.getName()),
452:             WorkflowTestConfigurationConnection::getWorkflowConnectionKey,
453:             WorkflowTestConfigurationConnection::getConnectionId);
454: 
455:         if (workflowNodeType.operation() == null) {
456:             if (taskDispatcherExecuteOutput) {
457:                 outputResponse = taskDispatcherDefinitionService.executeOutput(
458:                     workflowNodeType.name(), workflowNodeType.version(), inputParameters);
459:             } else {
460:                 outputResponse = taskDispatcherDefinitionService.executeVariableProperties(
461:                     workflowNodeType.name(), workflowNodeType.version(), inputParameters);
462:             }
463: 
464:             if (outputResponse != null && outputResponse.outputSchema() instanceof ObjectProperty objectProperty) {
465:                 List<? extends Property> properties = objectProperty.getProperties();
466: 
467:                 if (properties.isEmpty()) {
468:                     outputResponse = null;
469:                 }
470:             }
471:         } else {
472:             outputResponse = actionDefinitionFacade.executeOutput(
473:                 workflowNodeType.name(), workflowNodeType.version(), workflowNodeType.operation(),
474:                 inputParameters, connectionIds);
475:         }
476: 
477:         return Optional.ofNullable(outputResponse);
478:     }
